  if(n <= 20){ const t = n/20, [r, g, b] = hslToRgb(38, 55 - t*10, 74 - t*50); return `rgb(${Math.min(255, Math.round(r + 25*t))} ${Math.round(g)} ${Math.round(b)})`; }
