let codexSubTab = 'browse';
// mechLine (2026-09-18, per explicit request "add an archetype filter in the codex"): the Codex
// already had a `.archetype` filter, but that field is the biome/animal Type Tags system
// (archetypesOf/ARCHETYPE_ICON) — confusingly named "archetype" internally from an earlier pass,
// but user-facing as "Type Tags". The mechanic-line concept the editor itself actually labels
// "Archetype" (None/Ecclesia/Scrapper/Devilry — see MECH_LINE_LABEL/fMechLine) had NO Codex
// filter at all until now. `type` (Structure/Unit) is retired — see isStructure()/blankCard().
// 2026-09-26, per explicit request ("add a sort view to codex"): the Codex already had a Sort
// dropdown (attack/cost/health/name), just missing Rarity — a natural 5th dimension for a card
// game — and any way to flip direction (attack/health always sorted high-to-low, name/cost
// always low-to-high/A-Z, no choice either way). `dir` adds that: 'desc' is each field's own
// previous default, so existing behavior is unchanged until someone actually flips it.
// Sticky filters (2026-10-16, user: "Codex filters and other pages filters and search bars reset when you enter them"): every
// page's filters, sort and search box are kept in localStorage (bramblewood_ui_filters_v1, one entry per page), so they are as
// you left them when you come back, this session or the next. uiSticky(page) reads a page's saved state, uiStickySave(page, obj)
// writes it, and stickyControls(page, ids) does both for a page whose filters live only in its controls (the Camp's card pool).
const UI_FILTERS_KEY = 'bramblewood_ui_filters_v1';
function uiStickyAll(){ try{ const o = JSON.parse(localStorage.getItem(UI_FILTERS_KEY) || '{}'); return o && typeof o === 'object' ? o : {}; }catch(e){ return {}; } }
// 2026-10-18 (owner 21:18: "The text filters in all my texts ... don't reset when I refresh ... or when I move between pages"):
// only the non-text choices stay sticky (sort, rarity, type, kind, level, view). The free-text query is never saved or read back.
const UI_STICKY_TEXT_KEYS = ['q', 'deckSearch'];
function uiStickyNoText(o){ const out = Object.assign({}, o || {}); UI_STICKY_TEXT_KEYS.forEach(k=> delete out[k]); return out; }
function uiSticky(page){ const o = uiStickyAll()[page]; return o && typeof o === 'object' ? uiStickyNoText(o) : {}; }
function uiStickySave(page, obj){ try{ const all = uiStickyAll(); all[page] = uiStickyNoText(Object.assign({}, all[page] || {}, obj)); localStorage.setItem(UI_FILTERS_KEY, JSON.stringify(all)); }catch(e){} }
// Text filters reset (2026-10-18, same request). Every free-text filter / search box carries data-text-filter and
// autocomplete="off" (Chrome restores form values after a reload or from the back/forward cache otherwise).
