  const g = txTypeMemo.g, opt = o=> `<option value="${escapeAttr(o.name)}" ${sel===o.name?'selected':''}>${ARCHETYPE_ICON[o.name] || PHYLUM_ICON[o.name] || (TAXO && TAXO.isHabitat(o.name) ? '🗺️' : '🌰')} ${escapeHtml(o.name)} (${o.n})</option>`;
