    + [['habitats', ()=> TX('ui.tx-type-habitats')], ['animals', ()=> TX('ui.tx-type-animals')], ['other', ()=> TX('ui.tx-type-other')]].map(([k, key])=> g[k].length ? `<optgroup label="${escapeAttr(key())}">${g[k].map(opt).join('')}</optgroup>` : '').join('');
