const CF_SORTS = [['cost', ()=> TX('ui.tx-sort-cost')], ['wait', ()=> TX('ui.tx-sort-wait')], ['attack', ()=> TX('ui.tx-sort-attack')], ['health', ()=> TX('ui.tx-sort-health')], ['rarity', ()=> TX('ui.tx-sort-rarity')],
  ['level', ()=> TX('ui.tx-sort-level')], ['br', ()=> TX('ui.tx-sort-br')], ['name', ()=> TX('ui.tx-sort-name')]];
function cardBR(id, d){ try{ return Math.round(ratingWeightOf(d) * ratingLevelFactor(getCardLevel(id)) * 10) / 10; }catch(e){ return 0; } }
function cardLevelForSort(id){ try{ return Number(getCardLevel(id)) || 0; }catch(e){ return 0; } }
// The number a sort reads (high = more); rarity by its band.
function cfSortValue(key, id, d){
  if(key === 'cost') return Number(d.cost) || 0; if(key === 'wait') return Number(d.wait) || 0; if(key === 'attack') return Number(d.attack) || 0;
  if(key === 'health') return Number(d.health) || 0; if(key === 'rarity') return RARITY_TIER_BANDS.indexOf(d.rarity || 'common');
  if(key === 'level') return cardLevelForSort(id); if(key === 'br') return cardBR(id, d); return 0;
}
// A comparator for card ids: dir 'desc' = high to low (Z to A for Name), 'asc' = low to high (A to Z).
function cfSortFn(sort, dir, defs){
  defs = defs || getCardDefs(); const sgn = dir === 'asc' ? 1 : -1, memo = new Map();
  const val = id=>{ let v = memo.get(id); if(v === undefined){ v = cfSortValue(sort, id, defs[id] || {}); memo.set(id, v); } return v; };
  return (a, b)=>{ const A = defs[a], B = defs[b]; if(!A || !B) return 0;
    if(sort === 'name') return -sgn * (A.name || '').localeCompare(B.name || '') || 0;
    return sgn * (val(a) - val(b)) || ((A.cost||0) - (B.cost||0)) || (A.name || '').localeCompare(B.name || ''); };
}
function cfSortOptionsHTML(sel, extra){
  return CF_SORTS.concat(extra || []).map(([k, key])=> `<option value="${k}" ${sel===k?'selected':''}>${escapeHtml(key())}</option>`).join('');
}
function cfDirLabel(dir){ return dir === 'asc' ? '↑ ' + TX('ui.tx-low-high') : '↓ ' + TX('ui.tx-high-low'); }
// ---- the filter bar for the deck editors ----
function cfDefaults(){ return {archetype:'', animal:'', phylum:'', rarity:'', mechLine:'', skills:[], sort:'cost', dir:'asc'}; }
function cfActiveCount(f){ return [f.archetype, f.animal, f.phylum, f.rarity, f.mechLine, (f.skills||[]).length ? 1 : ''].filter(Boolean).length; }
// Does the card pass the bar's filters (types through the taxonomy, every skill pick)?
function cfMatch(d, f){
  if(!d || !f) return true;
  if(f.archetype && !taxIsA(d, f.archetype)) return false;
  if(f.animal && animalGroupOf(d.animal) !== f.animal) return false;
  if(f.phylum && !phylumOf(d).split(' & ').includes(f.phylum)) return false;
  if(f.rarity && (d.rarity || 'common') !== f.rarity) return false;
  if(f.mechLine && inferMechanicLine(d) !== f.mechLine) return false;
  const sk = (f.skills || []).filter(k=> typeof k === 'string'); if(sk.length && (easterEggMasked(d) || !sk.every(k=> cardMatchesSkillPick(maskHiddenSkills(d), k)))) return false;
  return true;
}
function cfApply(ids, defs, f){ return ids.filter(id=> cfMatch(defs[id], f)); }
function cfBarHTML(f, P, defs, extraSorts){
  defs = defs || getCardDefs(); const n = cfActiveCount(f), ns = (f.skills || []).length;
  const rar = (()=>{ const have = new Set(Object.values(defs).map(d=> d.rarity || 'common')); return RARITY_DEFS.filter(r=> have.has(r.key)).map(r=> `<option value="${r.key}" ${f.rarity===r.key?'selected':''}>${escapeHtml(r.label)}</option>`).join(''); })();
  const animals = (()=>{ const c = {}; Object.values(defs).forEach(d=>{ if(!d || d.test || !d.animal) return; const g = animalGroupOf(d.animal); c[g] = (c[g] || 0) + 1; });
    return Object.keys(c).sort().map(g=> `<option value="${escapeAttr(g)}" ${f.animal===g?'selected':''}>${escapeHtml(animalCap(g))} (${c[g]})</option>`).join(''); })();
  return `<div class="cf-bar" data-cf="${P}">
    <button type="button" class="btn small cf-toggle" id="${P}FiltersBtn" aria-expanded="false" aria-controls="${P}Panel">⚙️ ${escapeHtml(TX('ui.tx-filters'))}<b class="cx-fcount" ${n ? '' : 'hidden'}>${n}</b></button>
    <select id="${P}Sort" aria-label="${escapeAttr(TX('ui.tx-sort'))}">${cfSortOptionsHTML(f.sort, extraSorts)}</select>
    <button type="button" class="btn small" id="${P}SortDir">${escapeHtml(cfDirLabel(f.dir))}</button>
    <div class="cf-panel" id="${P}Panel" hidden>
      <select id="${P}Arch" aria-label="${escapeAttr(TX('ui.tx-type'))}">${txTypeOptionsHTML(defs, f.archetype)}</select>
      <select id="${P}Animal" aria-label="${escapeAttr(TX('ui.codex-animal-filter'))}"><option value="">🐾 ${escapeHtml(TX('ui.codex-all-animals'))}</option>${animals}</select>
      ${phylaUnlocked() ? `<select id="${P}Phylum" aria-label="${escapeAttr(TX('ui.tx-phylum'))}"><option value="">🧬 ${escapeHtml(TX('ui.tx-all-phyla'))}</option>${[...new Set(Object.values(SPECIES_PHYLUM))].sort().map(ph=> `<option value="${escapeAttr(ph)}" ${f.phylum===ph?'selected':''}>${PHYLUM_ICON[ph]||'🧬'} ${escapeHtml(ph)}</option>`).join('')}</select>` : ''}
      <select id="${P}Rarity" aria-label="${escapeAttr(TX('ui.codex-all-rarities'))}"><option value="">${escapeHtml(TX('ui.codex-all-rarities'))}</option>${rar}</select>
      <select id="${P}MechLine" aria-label="${escapeAttr(TX('ui.tx-archetype'))}"><option value="">${escapeHtml(TX('ui.tx-all-archetypes'))}</option>${Object.entries(MECH_LINE_LABEL).filter(([k])=> k !== 'none').map(([k, label])=> `<option value="${k}" ${f.mechLine===k?'selected':''}>${escapeHtml(label)}</option>`).join('')}</select>
      <button type="button" class="btn small cx-skill-btn ${ns ? 'primary' : ''}" id="${P}SkillBtn" aria-expanded="false" aria-controls="${P}SkillPanel">✨ ${escapeHtml(TX('ui.codex-skill-filter'))}<b class="cx-fcount" ${ns ? '' : 'hidden'}>${ns}</b></button>
      <button type="button" class="btn small ghost" id="${P}Clear" ${n ? '' : 'disabled'}>${escapeHtml(TX('ui.tx-clear-filters'))}</button>
      <div class="cx-skill-panel" id="${P}SkillPanel" hidden></div>
    </div>
    <div class="cx-skill-active" id="${P}SkillActive" hidden></div>
  </div>`;
}
// Wires a bar drawn by cfBarHTML inside `root`; onChange() redraws the list (f is changed in place).
function cfWire(root, f, P, onChange, keep){
  const $ = id=> root.querySelector('#' + P + id); if(!$('Sort')) return;
  const changed = ()=>{ ui(); onChange && onChange(); };
  const ui = ()=>{ const n = cfActiveCount(f), b = $('FiltersBtn'), c = b && b.querySelector('.cx-fcount'); if(c){ c.textContent = n; c.hidden = !n; }
    const cl = $('Clear'); if(cl) cl.disabled = !n;
    const sb = $('SkillBtn'), ns = (f.skills || []).length; if(sb){ const k = sb.querySelector('.cx-fcount'); if(k){ k.textContent = ns; k.hidden = !ns; } sb.classList.toggle('primary', !!ns); }
    const pn = $('SkillPanel'); if(pn && pn.dataset.built){ const on = new Set(f.skills || []); pn.querySelectorAll('[data-cxskill]').forEach(x=> x.setAttribute('aria-pressed', on.has(x.dataset.cxskill))); }
    const act = $('SkillActive'); if(act){ act.hidden = !ns; act.innerHTML = ns ? `<span>${escapeHtml(TX('ui.codex-skill-active'))}</span>${f.skills.map(k=> `<button type="button" class="cx-sk-chip is-on" data-cxskilloff="${escapeAttr(k)}" aria-label="${escapeAttr(TX('ui.codex-skill-remove'))}: ${escapeAttr(skillPickName(k))}">${skillPickIcon(k)} ${escapeHtml(skillPickName(k))} <i aria-hidden="true">✕</i></button>`).join('')}` : ''; } };
  const tog = $('FiltersBtn'), panel = $('Panel');
  if(tog && panel) tog.addEventListener('click', ()=>{ panel.hidden = !panel.hidden; tog.setAttribute('aria-expanded', !panel.hidden); if(keep) keep.panel = !panel.hidden; });
  [['Arch', 'archetype'], ['Animal', 'animal'], ['Phylum', 'phylum'], ['Rarity', 'rarity'], ['MechLine', 'mechLine']].forEach(([id, k])=>{ const el = $(id); if(el) el.addEventListener('change', ()=>{ f[k] = el.value; changed(); }); });
  $('Sort').addEventListener('change', e=>{ f.sort = e.target.value; changed(); });
  { const d = $('SortDir'); if(d) d.addEventListener('click', ()=>{ f.dir = f.dir === 'asc' ? 'desc' : 'asc'; d.textContent = cfDirLabel(f.dir); changed(); }); }
  { const cl = $('Clear'); if(cl) cl.addEventListener('click', ()=>{ Object.assign(f, {archetype:'', animal:'', phylum:'', rarity:'', mechLine:'', skills:[]}); ['Arch', 'Animal', 'Phylum', 'Rarity', 'MechLine'].forEach(id=>{ const el = $(id); if(el) el.value = ''; }); changed(); }); }
  const sb = $('SkillBtn'), sp = $('SkillPanel');
  if(sb && sp) sb.addEventListener('click', ()=>{ if(!sp.dataset.built){ sp.innerHTML = `<div class="cx-skill-head"><small>${escapeHtml(TX('ui.codex-skill-hint'))}</small></div>` + skillPickerChipsHTML(codexSkillChoices(), new Set(f.skills || [])); sp.dataset.built = '1'; }
    sp.hidden = !sp.hidden; sb.setAttribute('aria-expanded', !sp.hidden); if(keep) keep.skills = !sp.hidden; });
  if(keep && keep.panel && tog && panel){ panel.hidden = false; tog.setAttribute('aria-expanded', true); }
  if(keep && keep.skills && sb && sp){ keep.skills = false; sb.click(); }
  const onPick = e=>{ const t = e.target && e.target.closest ? e.target : null; if(!t) return;
    const chip = t.closest('[data-cxskill]'), off = t.closest('[data-cxskilloff]'); const cur = (f.skills || []).slice();
    if(chip){ const k = chip.dataset.cxskill; f.skills = cur.includes(k) ? cur.filter(x=> x !== k) : cur.concat(k); changed(); }
    else if(off){ f.skills = cur.filter(x=> x !== off.dataset.cxskilloff); changed(); } };
  if(sp) sp.addEventListener('click', onPick); { const act = $('SkillActive'); if(act) act.addEventListener('click', onPick); }
  ui();
}
// The deck editor's bar state (Play and the Camp share it; sticky like the Codex's filters, never the text box).
let deckCfState = Object.assign(cfDefaults(), (()=>{ try{ return uiSticky('deckTx'); }catch(e){ return {}; } })());
function deckCfSave(){ try{ uiStickySave('deckTx', deckCfState); }catch(e){} }
/* [TX_FILTERS_END] */
// ---- The card album (2026-10-18, package C, owner 20:31: "bestiary - look like a card album"; 20:36: "cards dont show up if you
// havent seen them before") ----
// The Codex's Browse tab as a binder: album pages of card sleeves, 3 × 3 a page, two pages side by side on a wide screen and one
// (2 × 3) on a phone. It holds the cards you have seen, the same list the grid had (codexVisible: seen, owned, or in a pack whose
// seller is open; revealAfter "?" tiles as before): owned cards in full, seen-only ones dimmed (cx-unowned). Each section (the
// "Separated" bands, or the admin's View by) starts on a new page with its name, "N seen · M owned" and the admin buttons.
// Only the open spread is drawn (at most 18 tiles, from codexTileCache); the next spread's tiles are built while the browser is
// idle, so a turn finds them ready. The search, filters, sorts and the rarity filter all still apply (renderCodexGrid filters,
// this lays out). Turn with ‹ ›, the arrow keys, a swipe, or jump to a section.
// 2026-10-19 (package CX, owner 14:07: "Show 16 cards on each page"): 4 × 4 sleeves a page at every width (two pages side by side
// on a wide screen, one on a phone, its cards smaller); the page-turn tabs sit on the book's outer edges (codexEdgeTabsHTML).
let codexAlbumState = null, codexTurnFn = null, codexSwipedAt = 0;
function albumLayout(){
  const host = document.getElementById('codexBody'), w = (host && host.clientWidth) || window.innerWidth || 1200;
  return w >= 960 ? {pages:2, cols:4, rows:4, key:'2x16'} : {pages:1, cols:4, rows:4, key:'1x16'};
}
// groups [{sec, ids (sorted), all}] -> album pages [{sec, ids, all, cont}]: a section starts a page; a long one runs on (cont).
function albumPaginate(groups, per){
  const pages = [];
  groups.forEach(g=>{
    if(!g.ids.length){ if(!g.sec.bare) pages.push({sec:g.sec, ids:[], all:g.all, cont:false}); return; } // (an admin's empty skirmish: its page has the Edit rewards button)
    for(let i = 0; i < g.ids.length; i += per) pages.push({sec:g.sec, ids:g.ids.slice(i, i + per), all:g.all, cont:i > 0});
  });
  return pages;
}
function codexDrawAlbum(gridEl, groups, tileFor, groupIds, keepPage){
  if(gridEl._cxMore){ try{ gridEl._cxMore(); }catch(e){} gridEl._cxMore = null; } // a grid draw's chunks stop
  const L = albumLayout(), pages = albumPaginate(groups, L.cols * L.rows);
  // a redraw for another layout (a resize) keeps the first card in view
  const prev = codexAlbumState, firstId = keepPage && prev && prev.L.key !== L.key && prev.pages[codexPage] ? prev.pages[codexPage].ids[0] : null;
  if(!keepPage) codexPage = 0;
  if(firstId){ const i = pages.findIndex(p=> p.ids.includes(firstId)); if(i >= 0) codexPage = i; }
  codexAlbumState = {pages, L, tileFor, groupIds, groups, gridEl};
  codexWireGridClick(gridEl); codexWireSwipe(gridEl);
  albumDraw();
}
// 2026-10-28 (package VIS5, L12; owner 10-28 09:48: "Even if the cards shown is few, the codex book should still be at 'max height'."): an album
// page is always 4 rows tall. The empty slots were 1 px high, so a page with a few cards (a search, a filter, a section's last page) shrank
// the whole book. An empty slot now has a sleeve's own proportions (--al-sar, width / height, measured from a real sleeve after each draw
// and kept per layout in codexSleeveAR), so the rows without cards still take a sleeve's height and the book keeps its full height.
const codexSleeveAR = {};
function albumPageHTML(p, i, side){
  if(!p) return `<section class="al-page pg-${side} is-blank" aria-hidden="true"></section>`;
  const S = codexAlbumState, sec = p.sec, per = S.L.cols * S.L.rows;
  const owned = p.all.filter(id=> (myCardCopies[id]||[]).length).length;
  const editBtn = adminModeEnabled && sec.nodeKey ? `<button type="button" class="btn small ghost cx-edit-rewards" data-map="${escapeAttr(sec.mapId)}" data-node="${escapeAttr(sec.nodeKey)}">✏️ Edit rewards</button>` : '';
  const getAll = adminModeEnabled && p.all.length ? `<button type="button" class="btn small ghost cx-get-all" data-getall="${escapeAttr(sec.key)}" title="Admin: add one copy of every card in this section to your collection">🎁 Get all</button>` : '';
  const title = sec.bare ? TX('ui.codex-album-title') : sec.label + (p.cont ? ' ' + TX('ui.codex-cont') : '');
  const sleeves = p.ids.map(id=> `<div class="al-sleeve">${S.tileFor(id)}</div>`).join('') + '<div class="al-slot" aria-hidden="true"></div>'.repeat(Math.max(0, per - p.ids.length));
  return `<section class="al-page pg-${side}" aria-label="${escapeAttr(TX('ui.codex-page-of', {n: i + 1, total: S.pages.length}))}">
    <header class="al-head"><span class="al-sec"${sec.tip ? ' title="' + escapeAttr(sec.tip) + '"' : '' /* 2026-10-19 (package CX): the detail as a tooltip */}>${escapeHtml(title)}</span><span class="al-count">${escapeHtml(TX('ui.codex-section-seen', {n: p.all.length, count: owned}))}</span>${editBtn}${getAll}</header>
    <div class="al-grid" style="--al-cols:${S.L.cols}; --al-sar:${codexSleeveAR[S.L.key] || .66}">${sleeves}</div><footer class="al-foot">${i + 1}</footer></section>`;
}
function albumDraw(){
  const S = codexAlbumState; if(!S || !S.gridEl.isConnected) return;
  const {pages, L, gridEl} = S;
  codexPage = Math.max(0, Math.min(codexPage, pages.length - 1)); codexPage -= codexPage % L.pages;
  if(!pages.length){ gridEl.innerHTML = `<div class="cx-view-hint">${escapeHtml(TX('ui.codex-no-cards'))}</div>`; codexTurnFn = null; return; }
  const sides = L.pages === 2 ? ['left', 'right'] : ['single'];
  // the sections, for "Go to section": each one's first page
  const sections = []; pages.forEach((p, i)=>{ if(!p.cont && !p.sec.bare && !sections.some(s=> s.key === p.sec.key)) sections.push({key:p.sec.key, label:p.sec.label, page:i}); });
  // 2026-10-19 (package CX, owner 14:07: "The goto previous or next page buttons should be on the books themselves"): the page
  // count and "Go to section" sit above the album; ‹ « and › » are tabs on its outer edges (no bar below).
  gridEl.innerHTML = codexPagerNavHTML('album', codexPage, L.pages, pages.length, sections)
    + `<div class="al-album pg-book al-${sides.length === 2 ? 'two' : 'one'}">${sides.map((sd, k)=> albumPageHTML(pages[codexPage + k], codexPage + k, sd)).join(sides.length === 2 ? '<div class="al-spine" aria-hidden="true"></div>' : '')}${codexEdgeTabsHTML(codexPage, L.pages, pages.length)}</div>`;
  try{ const sl = gridEl.querySelector('.al-sleeve'); if(sl){ const q = sl.getBoundingClientRect(); if(q.width > 20 && q.height > 20){ const ar = Math.round(q.width / q.height * 1000) / 1000; if(Math.abs((codexSleeveAR[L.key] || 0) - ar) > .004){ codexSleeveAR[L.key] = ar; gridEl.querySelectorAll('.al-grid').forEach(g=> g.style.setProperty('--al-sar', String(ar))); } } } }catch(e){} // VIS5 (L12): the empty slots' proportions
  gridEl.querySelectorAll('[data-turn]').forEach(b=> b.addEventListener('click', ()=> albumTurn(b.dataset.turn)));
  { const j = gridEl.querySelector('[data-pgjump]'); if(j) j.addEventListener('change', ()=>{ if(j.value !== '') albumGo(+j.value); }); }
  wireCodexGrid(S.groupIds);
  codexTurnFn = albumTurn;
  // the next spread's tiles, built while the browser is idle (they land in codexTileCache)
  const ahead = pages.slice(codexPage + L.pages, codexPage + 2 * L.pages), ric = window.requestIdleCallback || (f=> setTimeout(f, 200));
  if(ahead.length) ric(()=>{ if(codexAlbumState !== S) return; ahead.forEach(p=> p.ids.forEach(id=>{ try{ S.tileFor(id); }catch(e){} })); });
}
function albumTurn(dir){
  const S = codexAlbumState; if(!S || !S.gridEl.isConnected) return;
  if(dir === 'first' || dir === 'last'){ albumGo(dir === 'first' ? 0 : S.pages.length - 1); return; } // 2026-10-19 (package CX): « and »
  dir = +dir; const next = codexPage + dir * S.L.pages; if(next < 0 || next >= S.pages.length) return;
  codexLeafTurn(S.gridEl, dir, ()=>{ codexPage = next; albumDraw(); codexKeepInView(S.gridEl); });
}
function albumGo(page){
  const S = codexAlbumState; if(!S) return; const to = page - (page % S.L.pages); if(to === codexPage){ albumDraw(); return; }
  codexLeafTurn(S.gridEl, to > codexPage ? 1 : -1, ()=>{ codexPage = to; albumDraw(); codexKeepInView(S.gridEl); });
}
// After a turn on a small screen, the page's top comes back into view.
function codexKeepInView(el){ try{ const r = el.getBoundingClientRect(); if(r.top < 0) el.scrollIntoView({block:'start', behavior: reducedMotion() ? 'auto' : 'smooth'}); }catch(e){} }
// Above the album / the book: "Pages 3–4 of 12" (read out on a turn) and, for the album, a "Go to section" list.
// 2026-10-19 (package CX, owner 14:07: "The goto previous or next page buttons should be on the books themselves"): the turn buttons
// moved onto the book (codexEdgeTabsHTML); this row keeps only the page count and the section list.
function codexPagerNavHTML(kind, first, per, total, sections){
  const last = Math.min(total, first + per);
  const label = last - first > 1 ? TX('ui.codex-pages-of', {n: first + 1, to: last, total}) : TX('ui.codex-page-of', {n: first + 1, total});
  const jump = sections && sections.length > 1 ? `<select class="pg-jump" data-pgjump aria-label="${escapeAttr(TX('ui.codex-go-to-section'))}"><option value="">${escapeHtml(TX('ui.codex-go-to-section'))}</option>${sections.map(s=> `<option value="${s.page}">${escapeHtml(s.label)}</option>`).join('')}</select>` : '';
  return `<div class="pg-info pg-info-${kind}"><span class="pg-of" aria-live="polite">${escapeHtml(label)}</span>${jump}</div>`;
}
// The page-turn tabs ON the book (2026-10-19, package CX, owner 14:07: "<< and >> for to first and to last page"; "The goto previous
// or next page buttons should be on the books themselves"): like bookmark tabs on the cover's outer edges, ‹ with « under it on the
// left page's edge, › with » on the right one (on a single page, its two edges). They follow you down a tall page (sticky), so a
// turn is always in reach. Swipes, ← / → and Home / End still turn too (codexWireSwipe, the keydown below).
function codexEdgeTabsHTML(first, per, total){
  const atStart = first <= 0, atEnd = first + per >= total;
  const tab = (turn, cls, glyph, label, off)=> `<button type="button" class="pg-tab ${cls}" data-turn="${turn}" ${off ? 'disabled' : ''} aria-label="${escapeAttr(label)}" title="${escapeAttr(label)}"><span aria-hidden="true">${glyph}</span></button>`;
  const grp = 'role="group" aria-label="' + escapeAttr(TX('ui.codex-page-nav')) + '"';
  return `<div class="pg-edge pg-edge-l" ${grp}><div class="pg-edge-in">${tab(-1, 'pg-corner pg-prev', '‹', TX('ui.codex-prev-page'), atStart)}${tab('first', 'pg-corner pg-first', '«', TX('ui.codex-first-page'), atStart)}</div></div>`
    + `<div class="pg-edge pg-edge-r" ${grp}><div class="pg-edge-in">${tab(1, 'pg-corner pg-next', '›', TX('ui.codex-next-page'), atEnd)}${tab('last', 'pg-corner pg-last', '»', TX('ui.codex-last-page'), atEnd)}</div></div>`;
}
// A page turn (album and book): the page you leave lifts off at the spine and swings away (a copy of it, over the new pages), with
// a shadow across it. Transform and opacity only. None with reduced motion or Low / None effects (like codexPageTurn): the new pages
// are simply there. Turning back on a single page swings the new page in instead.
function codexLeafTurn(host, dir, draw){
  const motion = !!host && host.isConnected && !reducedMotion() && fxAtLeast('med');
  let leaf = null;
  if(motion){
    const single = host.querySelector('.pg-single'), from = single || host.querySelector(dir > 0 ? '.pg-right' : '.pg-left');
    if(from && !(single && dir < 0)){
      leaf = from.cloneNode(true); leaf.querySelectorAll('[id]').forEach(x=> x.removeAttribute('id'));
      leaf.classList.add('pg-leaf', dir > 0 ? 'pg-leaf-fwd' : 'pg-leaf-back'); leaf.setAttribute('aria-hidden', 'true'); leaf.removeAttribute('aria-label');
      let x = 0, y = 0, n = from; while(n && n !== host){ x += n.offsetLeft; y += n.offsetTop; n = n.offsetParent; } // layout px, relative to the host
      Object.assign(leaf.style, {left: x + 'px', top: y + 'px', width: from.offsetWidth + 'px', height: from.offsetHeight + 'px'});
    }
  }
  draw();
  if(!motion) return;
  try{ SoundKit.pageTurn && SoundKit.pageTurn(); }catch(e){}
  if(leaf){ host.appendChild(leaf); let gone = false; const done = ()=>{ if(gone) return; gone = true; try{ leaf.remove(); }catch(e){} }; leaf.addEventListener('animationend', done, {once:true}); setTimeout(done, 900); }
  else { const pg = host.querySelector('.pg-single'); if(pg){ pg.classList.add('pg-in-back'); setTimeout(()=> pg.classList.remove('pg-in-back'), 700); } }
}
// A sideways swipe (touch, pen or a mouse drag) turns the page; up and down still scroll.
function codexWireSwipe(el){
  if(!el || el._cxSwipe) return; el._cxSwipe = 1;
  let x0 = null, y0 = 0, t0 = 0;
  el.addEventListener('pointerdown', e=>{ if(!e.isPrimary || (e.pointerType === 'mouse' && e.button !== 0)) return; if(e.target && e.target.closest && e.target.closest('input, select, textarea')) return; x0 = e.clientX; y0 = e.clientY; t0 = Date.now(); });
  el.addEventListener('pointercancel', ()=>{ x0 = null; });
  el.addEventListener('pointerup', e=>{ if(x0 == null) return; const dx = e.clientX - x0, dy = e.clientY - y0; x0 = null;
    if(Math.abs(dx) >= 50 && Math.abs(dx) > Math.abs(dy) * 1.5 && Date.now() - t0 < 900 && codexTurnFn){ codexSwipedAt = Date.now(); codexTurnFn(dx < 0 ? 1 : -1); } });
}
// ← / → turn the album or the book while the Codex is open (not while typing, or with a window open over it).
// 2026-10-19 (package CX): Home / End open the first / last page, like « and ».
const CODEX_TURN_KEYS = {ArrowLeft:-1, ArrowRight:1, Home:'first', End:'last'};
document.addEventListener('keydown', e=>{
  if(!codexTurnFn || (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight' && e.key !== 'Home' && e.key !== 'End') || e.altKey || e.ctrlKey || e.metaKey || e.shiftKey) return;
  try{ if(currentTab !== 'codex') return; }catch(_){ return; }
  const t = e.target; if(t && t.closest && t.closest('input, textarea, select, [contenteditable]:not([contenteditable="false"])')) return;
  if(document.querySelector('.modal-overlay:not([hidden])')) return;
  e.preventDefault(); codexTurnFn(CODEX_TURN_KEYS[e.key]);
});
// A resize that changes the layout (two pages / one, 3 or 2 across) packs the pages again.
{ let t = null; window.addEventListener('resize', ()=>{ clearTimeout(t); t = setTimeout(()=>{ try{
  if(typeof currentTab === 'undefined' || currentTab !== 'codex') return;
  const A = codexAlbumState; if(A && A.gridEl.isConnected && albumLayout().key !== A.L.key){ codexDrawAlbum(A.gridEl, A.groups, A.tileFor, A.groupIds, true); return; }
  const B = codexBookState; if(B && B.L && document.getElementById('bkBook') && (bookLayout().key !== B.L.key || Math.abs((window.innerWidth||0) - (B.vw||0)) > 40 || Math.abs((window.innerHeight||0) - (B.vh||0)) > 80)) bookBuild(true); }catch(e){} }, 180); }); }
// Hall of Fame tab (2026-10-02): Classic and Antique variants, each tagged with what it's a variant
// of; Antiques show their improvement and (admin) their balance-check result; drafts are
// admin-only until approved.
function hallOfFameTabHTML(){
  const defs = getCardDefs();
  const all = Object.values(defs).filter(d=> isHofVariant(d) && (adminModeEnabled || !d.hallOfFame.draft) && (adminModeEnabled || !isCardHiddenForPlayer(d)));
  const block = (variant, title, blurb)=>{
    const list = all.filter(d=> d.hallOfFame.variant===variant).sort((a,b)=> a.name.localeCompare(b.name));
    const tiles = list.map(d=>{
      const base = defs[d.hallOfFame.baseId];
      const chk = variant==='antique' ? antiqueCheck(d, defs) : {ok:true};
      return `<div class="hof-entry">
        <div class="hof-tile">${cardTileHTML(d, {extraClass:`hof-${variant}`, inPlay:true})}<span class="hof-ribbon hof-ribbon-${variant}">${variant==='classic'?'🏛 Classic':'🏺 Antique'}</span></div>
        <div class="hof-meta">
          ${base ? `<div>${variant==='classic'?'Classic of':'Revived from'} <b>${escapeHtml(base.name)}</b></div>` : ''}
          ${variant==='antique' && d.hallOfFame.improvement ? `<div class="hof-improve">⬆ ${escapeHtml(d.hallOfFame.improvement)}</div>` : ''}
          ${d.hallOfFame.draft ? `<div class="hof-draft">Draft — not live yet</div>` : ''}
          ${adminModeEnabled && !chk.ok ? `<div class="hof-warn">⚠ ${escapeHtml(chk.reason)}</div>` : ''}
        </div></div>`;
    }).join('');
    return `<div class="panel hof-panel"><h3>${title}</h3><p class="panel-sub">${blurb}</p><div class="hof-grid">${tiles || '<p class="panel-sub">None yet.</p>'}</div></div>`;
  };
  // Classic cards removed (2026-10-13, user: "Remove the 'classic' cards").
  return block('antique', '🏺 Antique', 'Forgotten, humble cards brought back as they were, each with one small improvement. Never strong, never abusable, one copy per deck.');
}
// Card art (2026-09-17): a card's `.ico` box shows real sprite artwork (d.art, a data URI)
// when the canonical card def has one, falling back to the plain emoji (d.icon) otherwise —
// most cards have no art yet, so this must be a silent, per-card fallback, not an all-or-
// nothing switch. Only the full-visual card renders (Codex/deck-pool/simulator-pool tiles,
// hand tiles, board cards, the drag ghost preview) use this; compact chip lists (deck-builder
// dchip, txn log line) intentionally keep showing just the bare emoji for space reasons.
// Item 6 (2026-09-17, "The card image ... should encompass the whole card, becoming
// transparent at the edges, softly. Only IF the background can't be loaded, the emoji is
// loaded in the centre instead"): the art <img> now fills the whole card (see .card-tile
