  try{ if([...ids].some(id=>{ const e = defs[id].effects || {}; return e.arrow || e.fireArrow || e.iceArrow; })){ if(ARROW_PNG) urls.add(ARROW_PNG); if(FIRE_ARROW_PNG) urls.add(FIRE_ARROW_PNG); } }catch(e){}
