// The Detail card with its look (finish, Shiny, skin) and its bar, wired. host holds both; returns the card's controller.
function mountDetailView(host, d, st){
  const defId = d.id;
  st.skins = st.skins || (window.UnitFX ? UnitFX.skinsFor(defId) : []);
  if(st.skin === undefined) st.skin = window.UnitFX ? UnitFX.equippedSkin(defId) : null;
  const faceHTML = ()=>{ const skinCls = st.skin && window.UnitFX && UnitFX.SKINS[st.skin] ? ' has-skin ' + (UnitFX.SKINS[st.skin].tileClass || '') : '';
    return cardTileHTML(Object.assign({}, d, {locked:false}), {editable:false, size:'detail', extraClass:'ci-tile dc-tile' + (st.finish ? ' is-holo ' + st.finish + (st.finish === 'holo-cosmos' ? ' holo-starlight' : '') : '') + (st.shiny ? ' is-shiny' : '') + skinCls}) + '<span class="ci-sheen" aria-hidden="true"></span>'; };
  host.querySelector('.dc-slot').innerHTML = detailCardHTML(d, {tile: faceHTML(), shadow: true, cls: 'dc-main', alias: {stage: 'ci-stage-in', spin: 'ci-spin', face: 'ci-face', front: 'ci-front', back: 'ci-back'}});
  const ctl = mountDetailCard(host.querySelector('.dc-slot'), {});
  const front = host.querySelector('.dc-front');
  const redraw = ()=>{ ctl.setFront(faceHTML()); if(st.finish) try{ decorateHolo(front); }catch(e){} };
  if(st.finish) try{ decorateHolo(front); }catch(e){}
  host.querySelectorAll('[data-dc-spin]').forEach(b=> b.addEventListener('click', ()=> ctl.spinOnce()));
  host.querySelectorAll('[data-dc-flip]').forEach(b=> b.addEventListener('click', ()=> ctl.flip(1)));
  host.querySelectorAll('.ci-fin:not(.ci-skin)').forEach(b=> b.addEventListener('click', ()=>{ st.finish = b.dataset.fin || ''; host.querySelectorAll('.ci-fin:not(.ci-skin)').forEach(x=> x.classList.toggle('is-on', x === b)); ctl.show('front'); redraw(); }));
  host.querySelectorAll('.ci-skin').forEach(b=> b.addEventListener('click', ()=>{
    const id = b.dataset.skin || null, msg = host.querySelector('.ci-skin-msg'), k = id && st.skins.find(x=> x.id === id);
    if(k && !k.owned && adminModeEnabled){ UnitFX.grantSkin(id); k.owned = true; b.textContent = EmojiStyle.textOf(b).replace(/ 🔒️?/u, ''); }
    st.skin = id; host.querySelectorAll('.ci-skin').forEach(x=> x.classList.toggle('is-on', x === b)); ctl.show('front'); redraw();
    if(!k || k.owned){ UnitFX.equipSkin(defId, id); if(msg) msg.textContent = id ? `You own ${k.name}: it dresses one copy. Put that copy in your deck at the Camp.` : 'The default look.'; } // 2026-10-16: per copy
    else if(msg) msg.textContent = `Preview only: you don't own ${k.name} yet.`; }));
  const fxb = host.querySelector('.ci-fxbtn');
  if(fxb) fxb.addEventListener('click', ()=>{
    const fx = UnitFX.resolve(Object.assign({}, d), false), sk = st.skin && UnitFX.SKINS[st.skin], tile = front.querySelector('.card-tile');
    const kind = (sk && sk.fx && sk.fx.attack) || fx.attack, hit = (sk && sk.fx && sk.fx.hit) || fx.hit;
    const r = ctl.el.getBoundingClientRect(), tgt = document.createElement('div');
    tgt.style.cssText = `position:fixed; left:${Math.min(innerWidth - 60, r.right + 40)}px; top:${r.top + r.height * 0.3}px; width:40px; height:52px; pointer-events:none;`;
    document.body.appendChild(tgt); setTimeout(()=> tgt.remove(), 1200);
    ctl.show('front');
    if(kind){ UnitFX.attackFx(kind, tile, tgt, 600); if(SoundKit[kind]) SoundKit[kind](600); }
    else if(hit && hit !== 'blunt'){ UnitFX.hitMark(hit, tile); if(SoundKit[hit]) SoundKit[hit](); } });
  return ctl;
}
