// The fly-in: the big card starts where the tapped card was (its size and place) and grows into place, the detail column slides in after it.
function neInspectFlyIn(ov, from){
  if(reducedMotion() || !from || !from.getBoundingClientRect) return;
  const st = ov.querySelector('.ci-stage'), fr = from.getBoundingClientRect(); if(!st || !fr.width) return;
  const tr = st.getBoundingClientRect(); if(!tr.width) return;
  const s = Math.max(.12, Math.min(1, fr.width / tr.width)), dx = (fr.left + fr.width / 2) - (tr.left + tr.width / 2), dy = (fr.top + fr.height / 2) - (tr.top + tr.height / 2);
  try{ st.animate([{transform:`translate(${dx}px, ${dy}px) scale(${s})`, opacity:.85}, {transform:'none', opacity:1}], {duration:460, easing:'cubic-bezier(.2,.8,.25,1)'}); }catch(e){}
  const dt = ov.querySelector('.ci-detail'); if(dt) try{ dt.animate([{transform:'translateX(28px)', opacity:0}, {transform:'translateX(28px)', opacity:0, offset:.45}, {transform:'none', opacity:1}], {duration:620, easing:'ease-out'}); }catch(e){}
  const bar = ov.querySelector('.ci-bar'); if(bar) try{ bar.animate([{opacity:0}, {opacity:0, offset:.5}, {opacity:1}], {duration:560, easing:'ease-out'}); }catch(e){}
}
function openCardInspector(defId, opts){
  opts = opts || {};
  const d = getCardDefs()[defId]; if(!d) return;
  // 2026-10-30 (package CS-C): the Card Detail overlay is the inspector now (its card is the Detail card: tilt, drag to spin, flip, the
  // finishes and skins under it). Only a viewer over a full-screen layer (a pack's results, opts.pull / opts.over) keeps this overlay.
  if(!opts.pull && !opts.over && document.getElementById('cardDetailOverlay')){ openCardDetail(defId, {returnFocus: opts.returnFocus}); return; }
  if(cardInspectStop) cardInspectStop();
  // Players see the card in the finish they own; only admins get the finish picker (it doubles as the treatment centre's in-game preview).
  // 2026-10-17: opened from a pack's results, it shows that copy's own finish and Shiny (opts.pull {foil, finish, shiny})
  const st = {finish: opts.foil ? holoClass(d).replace('is-holo','').trim().split(/\s+/)[0] : '', shiny: !!(opts.pull && opts.pull.shiny)};
  if(opts.pull){ st.finish = opts.pull.foil ? ((copyFinishClass(d, {foil:true, finish: opts.pull.finish}).match(/holo-[a-z]+/) || [''])[0]) : ''; }
  const ov = document.createElement('div');
  ov.className = 'card-inspect ci-split'; ov.setAttribute('role','dialog'); ov.setAttribute('aria-modal','true');
  ov.setAttribute('aria-label', 'Inspect: ' + (d.name||''));
  // 2026-10-24 (package NE, owner 19:27 #13): the big card on the left, the card's details on the right (under it on a phone); it flies in
  // from the card you tapped (neInspectDetailHTML / neInspectFlyIn)
  ov.innerHTML = `<button type="button" class="ci-x" aria-label="${'Close'}">✕</button>
    <div class="ci-stage"><div class="dc-slot"></div></div>
    ${detailBarHTML(d, Object.assign(st, {skins: window.UnitFX ? UnitFX.skinsFor(defId) : [], skin: window.UnitFX ? UnitFX.equippedSkin(defId) : null}), {name: true})}${neInspectDetailHTML(d)}`;
  document.body.appendChild(ov);
  const ctl = mountDetailView(ov, d, st);
  neInspectFlyIn(ov, opts.returnFocus);
  const onKey = e=>{
    if(e.key === 'Escape'){ e.stopImmediatePropagation(); e.preventDefault(); close(); }
    else if((e.key === 'ArrowLeft' || e.key === 'ArrowRight') && !(e.target && e.target.closest && e.target.closest('.dc-stage'))){ e.preventDefault(); ctl.flip(e.key === 'ArrowLeft' ? -1 : 1); }
  };
  const unInert = bwInertOthers(ov);
  const close = ()=>{
    ctl.destroy(); window.removeEventListener('keydown', onKey, true); unInert(); ov.remove(); cardInspectStop = null;
    if(opts.returnFocus && opts.returnFocus.focus) opts.returnFocus.focus();
  };
  cardInspectStop = close;
  window.addEventListener('keydown', onKey, true);
  ov.querySelector('.ci-x').addEventListener('click', close);
  ov.addEventListener('click', e=>{ if(e.target === ov) close(); });
  ov.querySelector('.ci-x').focus();
}
// Codex placement (2026-10-02, admin): where a card comes from — decides its Codex tier/section —
