function wireCodexPlacement(defId){
  const kind = document.getElementById('cdpKind'); if(!kind) return;
  const show = ()=>{
    document.getElementById('cdpMap').hidden = kind.value!=='map';
    document.getElementById('cdpNode').hidden = kind.value!=='map';
    document.getElementById('cdpPackTier').hidden = kind.value!=='pack';
    document.getElementById('cdpEventTheme').hidden = kind.value!=='event';
    document.getElementById('cdpEventName').hidden = kind.value!=='event';
  };
  kind.addEventListener('change', show);
  document.getElementById('cdpMap').addEventListener('change', e=>{ document.getElementById('cdpNode').innerHTML = nodeOptionsHTML(e.target.value, null); });
  document.getElementById('cdpSave').addEventListener('click', async ()=>{
    const raw = rawCardDef(defId); if(!raw) return;
    const k = kind.value;
    if(!k) delete raw.source;
    else if(k==='base') raw.source = {kind:'base'};
    else if(k==='map'){
      const node = document.getElementById('cdpNode').value;
      if(!node){ document.getElementById('cdpMsg').textContent = 'Pick which skirmish rewards it.'; return; }
      const was = raw.source || {}; raw.source = {kind:'map', id: document.getElementById('cdpMap').value, node};
      if(was.challenge === true && was.kind === 'map' && was.id === raw.source.id && was.node === node) raw.source.challenge = true; // 2026-10-22 (RW2): a challenge card stays one while it stays on its fight
    }
    else if(k==='pack') raw.source = {kind:'pack', tier: Math.max(1, parseInt(document.getElementById('cdpPackTier').value,10)||1)};
    else if(k==='event'){
      const theme = document.getElementById('cdpEventTheme').value.trim(), name = document.getElementById('cdpEventName').value.trim();
      if(!theme){ document.getElementById('cdpMsg').textContent = 'Give the event a theme first.'; return; }
      raw.source = {kind:'event', theme, name};
    }
    raw.hidden = document.getElementById('cdpHidden').checked;
    delete raw.unattainable; // obtainability is worked out from the source now (2026-10-12)
    if(raw.hidden) delete raw.hidden; // hidden is the default now; only "not hidden" is stored (hidden:false)
    // 2026-10-13 (user: "Saving placement doesn't work"): the card editor kept its own copy of the card, so its Save put the
    // old source back. The editor's copy now takes the new placement too, and the panel says where the card now comes from.
    try{ if(typeof editingCard !== 'undefined' && editingCard && editingCard.id === defId){ if(raw.source) editingCard.source = JSON.parse(JSON.stringify(raw.source)); else delete editingCard.source; if(raw.hidden === false) editingCard.hidden = false; else delete editingCard.hidden; delete editingCard.unattainable; } }catch(e){}
    await saveCard(raw);
    const msg = document.getElementById('cdpMsg'); if(msg) msg.textContent = 'Saved ✓';
    const ob = document.querySelector('#cdPlacement .cdp-obtain'); if(ob){ const d2 = getCardDefs()[defId] || raw; ob.className = 'cdp-obtain ' + (isUnattainable(d2) ? 'is-no' : 'is-yes'); ob.textContent = isUnattainable(d2) ? cdpNotObtainableText(d2) : '✅ Obtainable: ' + cardWhereToGetText(d2); }
    if(currentTab==='codex') renderCodexGrid(true);
  });
}
