let matchState = null; // {engine, players, sideOf, over, winner, selectedHandUid, mode:'ai'|'pc'}
// Whose turn it is to act in the current round's planning phase. In 'ai' mode this is always
// player 1 (the AI acts instantly alongside them, see aiActNow). In 'pc' mode (local hot-seat,
// pass-and-play) the two human players alternate within the same round before combat resolves.
function activePlayerId(m){ return (m && (m.mode==='pc' || m.mode==='liveRanked')) ? (m.active||1) : 1; }
// Ranked 1v1 Live (#277): "whose logical turn is it" (activePlayerId, above) and "which seat
// THIS BROWSER's owner is playing" are the SAME question in every other mode — 'pc' is
// hot-seat (one shared device physically handed over, so the current turn-holder's hand IS
// the hand to show) and every other mode is solo. They're genuinely DIFFERENT questions for a
// real two-device online match: each client only ever has one human sitting at it, so it must
// always render ITS OWN seat's hand/resources — m.liveMySeat, fixed for the whole match — never
// switch over to showing the opponent's hand just because m.active points at them right now.
// viewerHandPid() is that second question; every render-only "my hand/graveyard/own-row"
// call site below uses it instead of activePlayerId() for that reason. activePlayerId() itself
// stays reserved for the handful of sites that resolve WHO AN ACTION BELONGS TO (the 4 action
// functions' engine calls) — which correctly must follow m.active, not the fixed viewer seat,
// specifically so the host can replay a peer's intent by calling those same functions directly
// (see replayLiveIntent) and have them attribute the mutation to the PEER's seat, not the host's.
function viewerHandPid(m){ return (m && m.mode==='liveRanked') ? (m.liveMySeat||1) : activePlayerId(m); }
// Item #16 (2026-09-18): Grace/Devilry are niche mechanic lines, unlike Gold/Stone which every
// deck touches — so their HUD pills should only show up when a card of that line is actually in
// play on EITHER battlefield this match, not unconditionally. Checked against live board cards
// (row.left/center/right) for both players, using each def's mechanicLine (inferred for legacy
// cards via inferMechanicLine).
function mechLineOnEitherBoard(m, line){
  if(!m || !m.players) return false;
  const defs = getCardDefs();
  for(const pid of [1,2]){
    const pl = m.players[pid]; if(!pl || !pl.row) continue;
    // 2026-09-20 (Dark Points): also show the pill once either side has actually banked any of
    // this resource, not just while a matching card sits on a battlefield -- otherwise the
    // Devilry discard bonus (a card can grant +1 Devilry on discard with no Devilry card ever
    // having hit the board) would credit the resource invisibly, with no pill to show it on.
    if((pl[line]||0) > 0) return true;
    const cards = [...pl.row.left, ...pl.row.center, ...pl.row.right];
    for(const c of cards){
      const def = defs[c.defId]; if(!def) continue;
      if(inferMechanicLine(def)===line) return true;
    }
  }
  return false;
}
// Elemental Energy (2026-09-18, "do an advanced resource where it takes refining from units...
// e.g. maybe some units take a stone every turn and produce this advanced resource") — same
// niche-pill gating as mechLineOnEitherBoard just above, but keyed off any board card carrying a
// 'refine' custom trigger (see ACTION_DEFS/runCustomTriggers 'refine') rather than a mechanic
// line, since Refine isn't tied to Grace/Exile/Devilry at all.
function refineOnEitherBoard(m){
  if(!m || !m.players) return false;
  const defs = getCardDefs();
  for(const pid of [1,2]){
    const pl = m.players[pid]; if(!pl || !pl.row) continue;
    const cards = [...pl.row.left, ...pl.row.center, ...pl.row.right];
    for(const c of cards){
      const def = defs[c.defId];
      if(def && def.effects && Array.isArray(def.effects.triggers) && def.effects.triggers.some(t=>t.do==='refine')) return true;
    }
  }
  return false;
}
// 2026-09-19 ("make all units give 1 lumber on discard for now — remove all other resources it
// would have given"): discarding no longer ever grants Stone (see pitchYieldOf), so the
// always-on Stone HUD pill would just permanently read 0 for everyone now. Same niche-pill
// gating as refineOnEitherBoard just above — only show it if some custom card's own 'gainStone'
// trigger is actually in play, the one remaining way to ever have Stone again.
function stoneOnEitherBoard(m){
  if(!m || !m.players) return false;
  const defs = getCardDefs();
  for(const pid of [1,2]){
    const pl = m.players[pid]; if(!pl || !pl.row) continue;
    const cards = [...pl.row.left, ...pl.row.center, ...pl.row.right];
    for(const c of cards){
      const def = defs[c.defId];
      if(def && def.effects && Array.isArray(def.effects.triggers) && def.effects.triggers.some(t=>t.do==='gainStone')) return true;
    }
  }
  return false;
}
function loadMatchStats(){
  try{
    const raw = localStorage.getItem('bramblewood_arena_stats');
    if(raw){
      const s = JSON.parse(raw);
      // Item #9 (2026-09-18) fleshed-out stats added streak/mode tracking after these fields
      // already existed for some players — backfill defaults so an older saved blob doesn't
      // render as NaN/undefined on the new stats subpage.
      if(s.curStreak==null) s.curStreak = 0;
      if(s.curStreakType==null) s.curStreakType = null; // 'win' | 'loss' | null
      if(s.bestWinStreak==null) s.bestWinStreak = 0;
      return s;
    }
  }catch(e){}
  return {played:0, wins:0, losses:0, draws:0, curStreak:0, curStreakType:null, bestWinStreak:0};
}
function saveMatchStats(s){ try{ localStorage.setItem('bramblewood_arena_stats', JSON.stringify(s)); }catch(e){} }
function recordMatchResult(winner, mode){
  // Only meaningful (and only tracked) for vs-AI matches — a pass-and-play vs-PC match has no
  // single "you" to score a personal win/loss against, since the same person plays both sides.
  const s = loadMatchStats();
  s.played += 1;
  if(winner===1){
    s.wins += 1;
    s.curStreak = s.curStreakType==='win' ? s.curStreak+1 : 1;
    s.curStreakType = 'win';
    if(s.curStreak > s.bestWinStreak) s.bestWinStreak = s.curStreak;
    // Epic B (2026-09-18): the first real earn loop for the new out-of-game currencies — a
    // modest per-win grant, since there's no shop/quest system yet to earn them any other way.
    // Deliberately small relative to the seeded starting balance (see loadCurrencies) so the
    // Forge stays meaningfully gated by currency rather than trivially mashable.
    // 2026-10-11 (Forge pacing): every mode with its own payout (Arena, Gauntlet, Ghost runs, Raids, Dungeon runs) no
    // longer stacks this on top; it was a free +8 Dust per win anywhere, the biggest faucet in the game. Quick battles
    // against the computer keep a small trickle.
    if(!mode || mode === 'ai'){ grantCurrency('gold', econPay('quickMatch', 'gold', 10)); grantCurrency('dust', econPay('quickMatch', 'dust', 2)); } // 2026-10-30 (ECON1): halved, ECON_INCOME_MULT.quickMatch
  } else if(winner===2){
    s.losses += 1;
    s.curStreak = s.curStreakType==='loss' ? s.curStreak+1 : 1;
    s.curStreakType = 'loss';
  } else {
    s.draws += 1;
    s.curStreak = 0; s.curStreakType = null;
  }
  saveMatchStats(s);
}
// Match History / Replay viewer (#254, 2026-09-25). "The engine already produces a full
// per-round event log; saving it and letting a player re-watch a past match would be cheap" —
// this is exactly that: every real personal result (same eligibility as recordMatchResult just
// above) gets its m.log array persisted to Supabase, and the Profile tab lists recent matches
// with each one expandable into the same text battle-log lines logText() already renders live.
// Deliberately a TEXT replay, not a re-animated visual one — rebuilding the whole VFX/pacing
// pipeline from a stored log (rather than a live resolveRound() call) is a much bigger, riskier
// project than this scope calls for; the log already carries every damage number, status tick,
// and death in order, which is what "re-watch what happened" actually needs.
let matchHistoryList = null; // null = not loaded yet; [] = loaded, empty
function logMatchHistory(m){
  // Signed-in only (see the module comment) — an anonymous guest session already isn't the kind
  // of durable identity a "look back on your account's match history" feature is for, matching
  // the same boundary Online Raid/Shop/cross-device sync already draw.
  if(!sbClient || !isSignedIn()) return;
  const opponentLabel = (m.mode==='raidOnline' || m.mode==='raidOffline') ? ((m.raidBoss && m.raidBoss.name) || 'Raid Boss')
    : ((m.mode==='async' || m.mode==='pvp') && m.asyncGhost) ? m.asyncGhost.name
    : m.mode==='liveRanked' ? (m.liveOpponentName || 'Opponent')
    : 'AI Opponent';
  const result = m.winner===1 ? 'win' : (m.winner===2 ? 'loss' : 'draw');
  sbClient.from('match_history').insert({
    profile_id: cloudUserId, mode: m.mode, opponent_label: opponentLabel, result,
    rounds: m.round, log: (m.log||[]).filter(ev=>ev.type!=='waitTick'), // waitTick is pure noise — see renderLogLine's own filter
  }).then(({error})=>{ if(!error) trimMatchHistory(); }, ()=>{});
}
// Retention (2026-09-25): rather than a scheduled server-side job, the client that just wrote a
// row simply trims its OWN history back to the most recent 30 right after — cheap, and correct
// often enough (a player who never triggers another match-end just keeps whatever they had,
// which is fine; there's no unbounded growth risk since a trim happens on every new write).
async function trimMatchHistory(){
  if(!sbClient || !cloudUserId) return;
  try{
    const { data } = await sbClient.from('match_history').select('id').eq('profile_id', cloudUserId).order('played_at', {ascending:false});
    if(!data || data.length<=30) return;
    const staleIds = data.slice(30).map(r=>r.id);
    if(staleIds.length) await sbClient.from('match_history').delete().in('id', staleIds);
  }catch(e){ /* non-fatal — a few extra rows lingering is harmless */ }
}
async function loadMatchHistory(){
  if(!sbClient || !isSignedIn()){ matchHistoryList = []; return; }
  try{
    const { data, error } = await sbClient.from('match_history').select('*').eq('profile_id', cloudUserId).order('played_at', {ascending:false}).limit(30);
    if(error) throw error;
    matchHistoryList = data || []; matchHistoryError = false;
  }catch(e){ matchHistoryList = []; matchHistoryError = true; }
  if(currentTab==='profile') renderProfile();
}
// 2026-10-18 (R3-WP3): a failed load showed "No matches recorded yet"; it now says it couldn't load, with Retry.
