function cardLevelRange(d){ return {from: cardBaseLevel(d), to: cardMaxLevel(d)}; }
// The default curve at a level, ignoring any per-level override (what the editor shows as the placeholder).
function curveStatsAtLevel(d, L){
  if((L|0) < cardBaseLevel(d)){ const r = v=> v==null ? v : Math.max(v > 0 ? 1 : 0, Math.round(v * 0.85)); return {attack: r(d.attack), health: r(d.health)}; } // Lv 0 hatchling
  const base = cardBaseLevel(d), lv = Math.max(base, Math.min(cardMaxLevel(d), L|0));
  const row = forgeCurveOf(d).rows[lv]; // 2026-10-19 (BF): the budget curve (was +10% / +5% steps)
  return {attack: row ? row.attack : d.attack, health: row ? row.health : d.health};
}
// 2026-10-30 (package TUT3, owner TUT2-2: "All start at lvl 0 and have no skills till lvl 1"): the skills of a card at level L. A card's `effects`
// holds ALL its skills, `levelSkills` says at which level each one arrives; a copy below that level (Level 0) must not have it. Every builder of a
// levelled / Level 0 copy goes through here: drops the keys of levelSkills[k] for k > L from `fx0` (default the def's effects), then lays k <= L on.
function effectsAtLevel(b, L, fx0){
  const fx = Object.assign({}, fx0 || (b && b.effects) || {}), ls = b && b.levelSkills; if(!ls) return fx;
  const ks = Object.keys(ls).map(Number).sort((x, y)=> x - y);
  ks.filter(k=> k > L).forEach(k=> Object.keys(ls[k] || {}).forEach(x=>{ delete fx[x]; }));
  ks.filter(k=> k <= L).forEach(k=> Object.assign(fx, ls[k]));
  return fx; }
function statsAtLevel(d, L){
  if((L|0) < cardBaseLevel(d)){ const ov0 = d.levelStats && (d.levelStats[0] || d.levelStats['0']); const r = v=> v==null ? v : Math.max(v > 0 ? 1 : 0, Math.round(v * 0.85));
    return {attack: ov0 && ov0.attack != null ? ov0.attack : r(d.attack), health: ov0 && ov0.health != null ? ov0.health : r(d.health)}; } // a hatchling (Level 0); the editor can set it
  const cap = cardMaxLevel(d) === 10 ? 11 : cardMaxLevel(d); // a limit-broken card reaches 11
  const base = cardBaseLevel(d), lv = Math.max(base, Math.min(cap, L|0));
  const ov = d.levelStats && (d.levelStats[lv] || d.levelStats[String(lv)]);
  if(ov) return {attack: ov.attack!=null ? ov.attack : d.attack, health: ov.health!=null ? ov.health : d.health};
  const row = lv > base ? forgeCurveOf(d).rows[lv] : null; // 2026-10-19 (BF): the budget curve (was +10% on Lv 1/3/6/9/11, +5% on 10)
  return {attack: row ? row.attack : d.attack, health: row ? row.health : d.health};
}
// Past the top (2026-10-16, user: "Limit breaking to whatever lvl like 20. (Any stats undefined by us = assume a random +1 stat in att or
// def)"): above a card's own top level (11 for the usual Lv 10 cards) each level adds +1 Attack or +1 Health, chosen by a seed of the
// card and the level, so the same card at the same level always has the same stats. A level the designer gave its own stats
// (def.levelStats) is used as is, and the +1s carry on from there. Only the Tower's enemies reach these levels.
function statsBeyondLevel(d, L){
  const cap = cardMaxLevel(d) === 10 ? 11 : cardMaxLevel(d); L = L|0;
  if(L <= cap) return statsAtLevel(d, L);
  let from = cap, st = statsAtLevel(d, cap);
  for(let l = L; l > cap; l--){ const ov = d.levelStats && (d.levelStats[l] || d.levelStats[String(l)]); if(ov){ from = l; st = {attack: ov.attack != null ? ov.attack : st.attack, health: ov.health != null ? ov.health : st.health}; break; } }
  st = Object.assign({}, st);
  for(let l = from + 1; l <= L; l++){ const atk = st.attack != null && (st.health == null || hashStr(`${d.id}:lv${l}`) % 2 === 0); if(atk) st.attack += 1; else if(st.health != null) st.health += 1; }
  return st;
}
