// Deck-builder hero banner (2026-09-29, per explicit request: "Improve the deck view UI. It's
// abit 'technical' looking and not very inviting... Maybe the Deck's background can be a slashed
// mishmash of the castle's art on the left and leader's art on the right"): a diagonal-split
// banner across the top of the deck editor, one half painted from the player's chosen Bramble
// (castle), the other from their chosen Leader card. Neither Castles nor most cards actually have
// painted art yet (see cardIcoHTML's own `d.art` check — only a minority of cards do, and all
// three Castle/Bramble defs currently ship with an empty `art` string), so this reuses the same
// rarity-gradient system every card-without-art already falls back to (rarityStops) plus that
// card's own big icon glyph, instead of requiring real artwork that doesn't exist for most
// loadouts — a card that DOES have painted art (checked live, not hardcoded) uses it directly.
// Regenerated in place (see refreshDeckHeroBanner) rather than a full renderPlayerSubTab() re-run
// whenever the Bramble or Leader selection changes, so picking either doesn't reset scroll
// position or the card pool's current filters.
function deckHeroHalfHTML(d, side){
  const fallbackIco = side==='left' ? '🏰' : '👑';
  if(!d) return `<div class="deck-hero-half deck-hero-half-${side} deck-hero-empty"><span class="deck-hero-ico">${fallbackIco}</span></div>`;
  const [rA, rB] = rarityStops(d.rarity||'common');
  const style = d.art ? `background-image:url('${d.art}');` : `background:linear-gradient(160deg, ${rA}, ${rB});`;
  return `<div class="deck-hero-half deck-hero-half-${side} ${d.art?'has-art':''}" style="${style}">
    ${d.art?'':`<span class="deck-hero-ico">${d.icon||fallbackIco}</span>`}
  </div>`;
}
// Deck top (2026-10-05, user: "the card view and deck view should be displayed as nicely" as the
// Hero editor): the castle and leader as real cards side by side, then the deck's name, its
// signature (archetypes, averages), size and level, and the Hero if it's in. Replaces the old
// split-colour banner; same id, so refreshDeckHeroBanner() keeps it current.
// Two small charts for a deck: how many cards at each Cost and each Wait (two lines), and the
// average Attack at each Wait (bars) — the speed/power trade-off at a glance.
// The deck details button works on touch too: a tap shows the same text as the hover title.
document.addEventListener('click', e=>{ const b = e.target.closest && e.target.closest('[data-deckinfo]'); if(b) showToast('ℹ️ ' + b.getAttribute('data-deckinfo')); });
function deckMiniChartsHTML(counts){
  const defs = getCardDefs(), XS = ['0','1','2','3','4+'], bin = v=> Math.min(4, Math.max(0, v|0));
  const cost = [0,0,0,0,0], wait = [0,0,0,0,0], atkSum = [0,0,0,0,0];
  Object.entries(counts||{}).forEach(([id, n])=>{ const d = defs[id]; if(!d || !(n>0)) return; cost[bin(d.cost||0)] += n; wait[bin(d.wait||0)] += n; atkSum[bin(d.wait||0)] += (d.attack||0)*n; });
  const avgAtk = atkSum.map((a, i)=> wait[i] ? a / wait[i] : 0);
  const W = 170, H = 74, P = {l:16, r:6, t:8, b:16}, iw = W - P.l - P.r, ih = H - P.t - P.b;
  const x = i=> P.l + (i + 0.5) * iw / XS.length, y = (v, max)=> P.t + ih - (max ? v / max : 0) * ih;
  const axis = XS.map((t, i)=> `<text x="${x(i)}" y="${H-4}" text-anchor="middle">${t}</text>`).join('') + `<line x1="${P.l}" x2="${W-P.r}" y1="${P.t+ih}" y2="${P.t+ih}" class="ax"/>`;
  const m1 = Math.max(1, ...cost, ...wait);
  const line = (vals, cls)=> `<polyline class="${cls}" points="${vals.map((v, i)=> `${x(i).toFixed(1)},${y(v, m1).toFixed(1)}`).join(' ')}"/>` + vals.map((v, i)=> `<circle class="${cls}" cx="${x(i).toFixed(1)}" cy="${y(v, m1).toFixed(1)}" r="2.6"><title>${v} card${v===1?'':'s'}</title></circle>`).join('');
  const m2 = Math.max(1, ...avgAtk), bw = iw / XS.length * 0.56;
  const bars = avgAtk.map((v, i)=> `<rect class="atk" x="${(x(i) - bw/2).toFixed(1)}" y="${y(v, m2).toFixed(1)}" width="${bw.toFixed(1)}" height="${(P.t + ih - y(v, m2)).toFixed(1)}" rx="2"><title>Wait ${XS[i]}: ${wait[i]} card${wait[i]===1?'':'s'}, avg attack ${v.toFixed(1)}</title></rect>`).join('');
  return `<figure class="dt-chart"><figcaption><i class="sw cost"></i>Cost <i class="sw wait"></i>Wait <small>cards per value</small></figcaption><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Cards by cost and by wait">${axis}${line(cost, 'cost')}${line(wait, 'wait')}</svg></figure>
    <figure class="dt-chart"><figcaption><i class="sw atk"></i>Attack by Wait <small>average</small></figcaption><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Average attack at each wait">${axis}${bars}</svg></figure>`;
}
