// Battle rating (2026-10-11, user: "battle rating: Replace deck level ... a beginner level deck has rating 1-25. While
// the max it can be is about 2,500. A good middle ground is 400+ for Map 20"). Each card adds its rarity's weight (the
// same ladder as its Forge cost: Common 1, Uncommon 2, Rare 4, Very Rare 6, Super Rare 8, Epic 11, Heroic 14, Unique 17,
// Legendary 21, Mythic 25, Ancient 30; Base 0.5) × its level factor (1 at level 1, 3.79 at level 10, 0.7 at a Base
// card's level 0); the leader counts double. A full deck of level-10 Ancients with an Ancient leader is ≈2,500.
const RATING_WEIGHT = {starter:0.5, common:1, uncommon:2, rare:4, veryrare:6, superrare:8, epic:11, heroic:14, unique:17, legendary:21, mythic:25, ancient:30, divine:36, void:42, daemonic:48};
function ratingWeightOf(d){ if(!d) return 0; const r = d.rarity || 'common', as = (RARITY_DEFS.find(x=> x.key===r) || {}).as; return RATING_WEIGHT[r] || RATING_WEIGHT[as] || 1; }
// cap (2026-10-16, the Tower): its enemies fight up to Level 20, and the same straight line carries on past 11 (Lv 20 = 6.89).
function ratingLevelFactor(L, cap){ L = Math.max(0, Math.min(cap || 11, Number(L)||0)); return L <= 0 ? 0.7 : 1 + (L - 1) * 0.31; }
function deckLevelFrom(counts, levelOf, leaders, cap){
  const defs = getCardDefs();
  const one = id=>{ const k = String(id).split('~')[0], d = defs[k]; if(!d) return 0; return ratingWeightOf(d) * ratingLevelFactor(levelOf(k), cap); };
  let t = 0;
  Object.keys(counts||{}).forEach(id=>{ t += (counts[id]||0) * one(id); });
  (leaders||[]).filter(Boolean).forEach(id=>{ t += 2 * one(id); });
  return Math.max(0, Math.round(t));
}
// An enemy's battle rating is the rating a player should bring (enemy decks are small and their strength is in the
// castle), on one curve for the whole road: about 12 at Map 1, 400 at Map 20, rising about 20% a map. Inside a map the
// skirmishes run from 85% to 115% of the map's par, an elite is 115%, a boss 130%, the campaign boss 140%, a side map
// +10%. A fight can set its own (node.rating, in the skirmish editor).
// 2026-10-12 (D60 + your map list): rebased so the Sundered Peak's final boss (Map 20, ×1.4) lands on 400; its side maps set their own.
function mapParRating(mapNo){ return 12 * Math.pow((400/1.4)/12, (Math.max(1, mapNo) - 1) / 19); }
function enemyDeckLevel(node){
  // 2026-10-12 (22:25, user: "The battle rating seen in the game should be real values! Not hard coded"): worked out from the
  // enemy's actual deck, at the levels its cards will really fight at (the road level, or a level set in Edit skirmish), with its
  // leaders counted like a player's leader. No more curve or typed-in rating.
  if(!node || !node.deck) return 0;
  const defs = getCardDefs(); let road = 0;
  try{ road = roadEnemyLevel(edRealNode(node)); }catch(e){} // 2026-10-21 (package ED): the editor's draft as it stands (its Enemy level), else the map's node
  const lv = id=>{ const set = node.cardLevels && node.cardLevels[id]; const b = cardBaseLevel(CARD_DEFS_BASELINE[id] || defs[id]); return set != null && set !== '' ? Number(set) : Math.max(b, road || b); };
  // Enemy decks are smaller than a player's 20; scale to 20 cards so the two ratings compare like for like.
  const n = Object.values(node.deck).reduce((a, b)=> a + (b||0), 0) || 1;
  const leaders = skirmishLeadersOf(node); // 2026-10-22 (package SK): the explicit leaders, else from Map 2 the showcase card
  const cap = node.levelCap || 11; // the Tower's floors fight up to Level 20 (2026-10-16)
  const body = deckLevelFrom(node.deck, lv, [], cap) * (DECK_SIZE / n), lead = deckLevelFrom({}, lv, leaders, cap);
  return Math.round(body + lead);
}
function mainDeckLevel(counts, leaderId){
  // 2026-10-18 (package NF): each copy counts at its own level (the deck's k copies of a card are your k strongest, as in a fight)
  if(copyModelOn()){ const defs = getCardDefs(); let t = 0;
    Object.keys(counts||{}).forEach(id=>{ const n = counts[id]|0, d = defs[String(id).split('~')[0]]; if(n <= 0 || !d) return; const w = ratingWeightOf(d);
      const ls = (myCardCopies[id]||[]).length ? deckCopyLevels(id, n) : null; for(let k = 0; k < n; k++) t += w * ratingLevelFactor(ls ? ls[k] : getCardLevel(id)); });
    if(leaderId && defs[leaderId]) t += 2 * ratingWeightOf(defs[leaderId]) * ratingLevelFactor(getCardLevel(leaderId));
    return Math.max(0, Math.round(t)); }
  return deckLevelFrom(counts, id=> getCardLevel(id), leaderId ? [leaderId] : []);
}
// PvP matchmaking keeps the older power score (rarity × max(1, level)), so stored ghost decks stay comparable.
function deckPowerLevel(counts, leaderId){
  if(typeof BramblewoodAutobattle==='undefined') return 0;
  return BramblewoodAutobattle.deckLevelOf(getCardDefs(), counts, id=> Math.max(1, (myCardLevels||{})[id]||0), leaderId ? [leaderId] : []);
}

// ---- Deck import/export codes (2026-09-21, per the "shop/packs and deck-export-codes" pick
// from roadmap-and-backlog.md's own suggested build order — shop/packs already shipped
// 2026-09-20, this closes out the other half) ----
// A short shareable text string that fully encodes one deck (name, Castle/Bramble, Leader,
// and card counts) so a player can hand a build to someone else outside the game (Discord, a
// forum post, etc.) without a screenshot, and the recipient gets it back as a real, editable
// deck rather than a picture of one. Format: `BWD1:` + a UTF-8-safe base64 blob of a small JSON
// payload — deliberately NOT a bit-packed/minified format (a Hearthstone/Marvel-Snap-style
// deck code doesn't need to be byte-optimal to be "shareable," and staying plain JSON under the
// base64 means a future field can be added without a version-2 migration for old codes: an
// older client just ignores a key it doesn't recognize, and `decodeDeckCode` below already
// tolerates missing keys with sane defaults).
const DECK_CODE_PREFIX = 'BWD1:';
// btoa/atob only handle Latin1 — a deck name can contain any Unicode a player typed (emoji
// included), so this wraps them in the standard encodeURIComponent/escape round-trip rather
// than risk `btoa` throwing on a non-Latin1 character (a real crash a naive `btoa(JSON...)`
// would hit the first time someone names a deck with, say, an emoji).
function b64EncodeUnicode(str){ return btoa(unescape(encodeURIComponent(str))); }
function b64DecodeUnicode(str){ return decodeURIComponent(escape(atob(str))); }
function encodeDeckCode(d){
  const payload = { n: (d.name||'Deck').slice(0,40), c: d.characterId||'castle', l: d.leaderId||null, d: Object.assign({}, d.counts||{}) };
  return DECK_CODE_PREFIX + b64EncodeUnicode(JSON.stringify(payload));
}
// Returns {ok:true, deck:{name,characterId,leaderId,counts}, warnings:[...]} or {ok:false, reason}.
// Deliberately permissive rather than all-or-nothing: an otherwise-valid code from a NEWER
// build that references a card this build doesn't know about (or one that got renamed/removed
// since the code was shared) still imports everything it can, dropping just the unrecognized
// entries and reporting them as warnings — a friend's shared deck shouldn't refuse to import
// entirely over one card neither of you can do anything about.
function decodeDeckCode(str){
  const raw = (str||'').trim();
  if(!raw) return {ok:false, reason:'Empty code.'};
  if(!raw.startsWith(DECK_CODE_PREFIX)) return {ok:false, reason:'Not a Bramblewood deck code (missing the "'+DECK_CODE_PREFIX+'" prefix).'};
  let payload;
  try{ payload = JSON.parse(b64DecodeUnicode(raw.slice(DECK_CODE_PREFIX.length))); }
  catch(e){ return {ok:false, reason:'Could not read that code — it looks corrupted or truncated.'}; }
  if(!payload || typeof payload!=='object') return {ok:false, reason:'Could not read that code — it looks corrupted or truncated.'};
  const warnings = [];
  const defs = getCardDefs();
  const characterId = (payload.c && CHARACTER_DEFS[payload.c]) ? payload.c : (warnings.push('Unknown bramble — defaulted to the starting bramble.'), 'castle');
  let leaderId = null;
  if(payload.l){
    if(defs[payload.l]) leaderId = payload.l;
    else warnings.push('The Leader card in this code no longer exists — imported with no Leader.');
  }
  const counts = {};
  let droppedCards = 0;
  Object.keys(payload.d||{}).forEach(id=>{
    const n = Math.max(0, Math.min(60, Math.round(Number(payload.d[id])||0))); // 60: generous sanity cap, not a real deck-size rule
    if(n<=0) return;
    if(!defs[id]){ droppedCards++; return; }
    counts[id] = n;
  });
  if(droppedCards>0) warnings.push(`${droppedCards} card${droppedCards===1?'':'s'} in this code no longer exist${droppedCards===1?'s':''} and were skipped.`);
  const name = (typeof payload.n==='string' && payload.n.trim()) ? payload.n.trim().slice(0,40) : 'Imported Deck';
  return {ok:true, deck:{name, characterId, leaderId, counts}, warnings};
}

// ---- Local profile / "login" (2026-09-20, per explicit request: "Have a login page at the
// landing page. If already logged in, click start.") — the game is a single static file with no
// backend/server (see initUserAuth's own comment above on why real Google OAuth isn't something
// this app can do on its own), so "logged in" here means a simple on-device profile: a display
// name saved to localStorage, nothing more. No password, no account recovery, no server — the
// same honest, no-fake-auth spirit as initUserAuth's Artifact-only "Signed in as X" pill, just
// as a standalone concept that works even outside an Artifact host. ----
function loadMyProfile(){
  try{ const raw = localStorage.getItem('bramblewood_arena_profile'); if(raw) return JSON.parse(raw); }catch(e){}
  return null;
}
function saveMyProfile(p){ try{ localStorage.setItem('bramblewood_arena_profile', JSON.stringify(p)); }catch(e){} myProfile = p; }
function clearMyProfile(){ try{ localStorage.removeItem('bramblewood_arena_profile'); }catch(e){} myProfile = null; }
let myProfile = loadMyProfile();

// Conquest (2026-09-16, per explicit request) is now the featured/default sub-tab — a map
// campaign of preset AI skirmishes sits beside the existing Player (deck/character) and
// Arena (quick vs AI/vs PC/Async) sub-tabs, plus a Raid tab for permanently-unlocked Raid
// Bosses. 'conquest' | 'player' | 'arena' | 'raid' — only relevant when no match is in progress.
let playSubTab = 'conquest';
// Item #4 (2026-09-18): a small, generic ">1s hover" tooltip helper — a single shared tooltip
// element (created once, reused for every caller) that only appears after the pointer has sat
// still on `el` for `delayMs` (default 1000ms), and disappears the instant the pointer leaves,
// even mid-delay. Kept generic (not Conquest-specific) since the same "don't explain everything
// up front, only on a deliberate long hover" pattern is reusable anywhere else a button could use
// it later.
let __delayedTooltipEl = null;
// Tooltip lifecycle (2026-10-11 card-object audit, user: "tooltip fade hooks, e.g. OnFade → Tooltip.Fade()"). Rather
// than every card and button carrying its own fade/remove callbacks, each floating tip registers the element it
// describes here. While any tip is up, one animation-frame loop follows its anchor: the tip takes on the anchor's
// effective opacity (so it fades with a dying or fading card), and it closes the moment the anchor is removed from
// the page, hidden (display/visibility/opacity 0, or inside a hidden parent) or shrunk to nothing. Tips that close
// normally just stop being tracked. See docs/card-object-audit-2026-10-11.md.
const TipWatch = (()=>{
  const live = new Map(); let raf = 0;
  const effOpacity = el=>{ let o = 1; for(let n = el; n && n.nodeType === 1 && o > 0.01; n = n.parentElement) o *= Number(getComputedStyle(n).opacity); return o; };
  function gone(a){
    if(!a || !a.isConnected) return true;
    if(a.checkVisibility && !a.checkVisibility({visibilityProperty:true})) return true;
    const r = a.getBoundingClientRect(); return !(r.width || r.height);
  }
  function tick(){
    raf = 0;
    live.forEach((rec, tip)=>{
      if(!tip.isConnected || tip.hidden){ tip.style.opacity = ''; live.delete(tip); return; }
      if(gone(rec.anchor)){ tip.style.opacity = ''; live.delete(tip); try{ rec.hide(); }catch(e){} return; }
      if(rec.steady){ tip.style.opacity = ''; return; } // 2026-10-30 (package UI6, X2): the card popover does not fade with a card an animation dims
      const o = effOpacity(rec.anchor);
      if(o < 0.03){ tip.style.opacity = ''; live.delete(tip); try{ rec.hide(); }catch(e){} return; }
      tip.style.opacity = o < 0.98 ? o.toFixed(2) : '';
    });
    if(live.size) raf = requestAnimationFrame(tick);
  }
  return {
    track(tip, anchor, hide, opts){ if(!tip || !anchor) return; live.set(tip, {anchor, hide: hide || (()=>{ tip.hidden = true; }), steady: !!(opts && opts.steady)}); if(!raf) raf = requestAnimationFrame(tick); },
    release(tip){ if(tip){ live.delete(tip); tip.style.opacity = ''; } },
    count(){ return live.size; },
  };
})();
if(typeof window !== 'undefined') window.TipWatch = TipWatch;
function attachDelayedTooltip(el, text, delayMs){
  if(!el) return;
  delayMs = delayMs==null ? 1000 : delayMs;
  let timer = null;
  const show = ()=>{
    timer = null;
    if(!el.isConnected) return; // re-rendered away while the timer ran
    if(!__delayedTooltipEl){
      __delayedTooltipEl = document.createElement('div');
      __delayedTooltipEl.className = 'tab-hover-tip';
      document.body.appendChild(__delayedTooltipEl);
    }
    __delayedTooltipEl.textContent = text;
    __delayedTooltipEl.hidden = false;
    const r = el.getBoundingClientRect();
    __delayedTooltipEl.style.left = (r.left + r.width/2) + 'px';
    __delayedTooltipEl.style.top = (r.bottom + 8) + 'px';
    TipWatch.track(__delayedTooltipEl, el, hide);
  };
  const hide = ()=>{ if(timer){ clearTimeout(timer); timer=null; } if(__delayedTooltipEl) __delayedTooltipEl.hidden = true; };
  el.addEventListener('mouseenter', ()=>{ timer = setTimeout(show, delayMs); });
  el.addEventListener('mouseleave', hide);
  el.addEventListener('mousedown', hide); // clicking the button shouldn't leave a stale tooltip up
}
// Tiered hover reveal (2026-09-30, queued backlog item: "Deck hover reveal (cards-remaining
// count) + a general 'hold Shift to reveal 2nd-tier info' convention, applied to the deck first
// and meant to generalize to other hidden-info spots"). Piloted on the in-match deck pile (see
// wireDeckHoverReveal below) but deliberately generic here — content comes from two callbacks, not
// anything deck-specific — so any other hidden-info spot can adopt the exact same convention later
// just by calling this with its own tier1/tier2 builders. Tier 1 shows on a plain hover, same as
// attachDelayedTooltip above but instant (no delay -- this is meant to feel like a quick glance,
// not a "wait for it" explainer); tier 2 replaces it live, for as long as Shift stays held, without
// needing to re-hover -- pressing/releasing Shift mid-hover swaps the content immediately via the
// shared keydown/keyup listeners below, not just at the moment the pointer first arrives.
let __tieredHoverEl = null;
let __tieredHoverShiftHeld = false;
let __tieredHoverActiveRefresh = null; // the currently-hovered element's own refresh fn, or null when nothing's hovered -- lets the one shared Shift listener below live-update whichever tiered tooltip (if any) is currently open
function __tieredHoverRefreshIfActive(){ if(__tieredHoverActiveRefresh) __tieredHoverActiveRefresh(); }
document.addEventListener('keydown', e=>{ if(e.key==='Shift'){ __tieredHoverShiftHeld = true; __tieredHoverRefreshIfActive(); } });
document.addEventListener('keyup', e=>{ if(e.key==='Shift'){ __tieredHoverShiftHeld = false; __tieredHoverRefreshIfActive(); } });
window.addEventListener('blur', ()=>{ __tieredHoverShiftHeld = false; __tieredHoverRefreshIfActive(); }); // an Alt-Tab mid-hold shouldn't leave this stuck thinking Shift is still down -- same guard wireDebugBar's own Shift-hold tracking uses, at the top of this file
function attachTieredHoverReveal(el, tier1Fn, tier2Fn){
  if(!el) return;
  const refresh = ()=>{
    if(!__tieredHoverEl){
      __tieredHoverEl = document.createElement('div');
      __tieredHoverEl.className = 'tiered-hover-tip conquest-tooltip'; // reuses the Conquest map tooltip's panel look (surface/border/radius/shadow) rather than inventing a third tooltip skin
      document.body.appendChild(__tieredHoverEl);
    }
    __tieredHoverEl.innerHTML = (__tieredHoverShiftHeld ? tier2Fn : tier1Fn)();
    __tieredHoverEl.hidden = false;
    const r = el.getBoundingClientRect();
    __tieredHoverEl.style.left = (r.left + r.width/2) + 'px';
    __tieredHoverEl.style.top = (r.top - 10) + 'px';
    TipWatch.track(__tieredHoverEl, el, hide);
  };
  const hide = ()=>{ __tieredHoverActiveRefresh = null; if(__tieredHoverEl) __tieredHoverEl.hidden = true; };
  el.addEventListener('mouseenter', ()=>{ __tieredHoverActiveRefresh = refresh; refresh(); });
  el.addEventListener('mouseleave', hide);
}
// The deck hover reveal's tier-2 content (see wireDeckHoverReveal in renderMatchUI): a player's
// `deck` field is a flat array of plain defId strings (see newPlayer/buildDeckIdsFrom in
// bramblewood-engine.js) -- grouped here into counts, sorted by how many copies remain (most
// first, so "what do I still have the most of" reads at a glance), name as the tiebreak.
function deckBreakdownHTML(deckIds, defs){
  const counts = {};
  deckIds.forEach(id=>{ counts[id] = (counts[id]||0)+1; });
  const rows = Object.entries(counts).map(([id,n])=>{
    const d = defs[id];
    return { name: (d&&d.name)||id, icon: (d&&d.icon)||'❔', n };
  }).sort((a,b)=> b.n-a.n || a.name.localeCompare(b.name));
  if(!rows.length) return `<div class="dht-empty">Deck is empty.</div>`;
  return `<div class="dht-list">${rows.map(r=>`<div class="dht-row"><span class="dht-ico">${r.icon}</span><span class="dht-name">${escapeHtml(r.name)}</span><span class="dht-n">×${r.n}</span></div>`).join('')}</div>`;
}
