// Item #11 (2026-09-18): "The drag and drop works also by dragging a card into the deck list
// section of build your deck." — pool tiles were already made draggable for item #10's leader
// slot; dropping one onto #myDeckList now does the same thing a click already does (add one
// copy), just via drag. Bound once here (not inside renderMyDeckPanels, which only replaces
// #myDeckList's innerHTML on every add/remove/filter change — the container node itself is
// never recreated, so a listener attached to it survives every one of those refreshes and
// re-binding on each would just stack duplicate handlers).
function wireDeckListDrop(){
  const listEl = document.getElementById('myDeckList');
  if(!listEl) return;
  listEl.addEventListener('dragover', e=>{ e.preventDefault(); listEl.classList.add('dragover'); });
  listEl.addEventListener('dragleave', ()=> listEl.classList.remove('dragover'));
  listEl.addEventListener('drop', e=>{
    e.preventDefault(); listEl.classList.remove('dragover');
    const defId = e.dataTransfer.getData('text/plain');
    const defs = getCardDefs();
    if(!defId || !defs[defId] || defs[defId].locked) return;
    // Same rarity copy-limit enforcement as the click/tap path (deckCardClick) -- this drop
    // handler bypasses that function entirely, so it needs its own identical check.
    if(editionCapReached(myDeckCounts, defId, defs) || defId === myLeaderId || (myDeckCounts[defId]||0) >= ownedCopiesOf(defId)){ // a leader can't also sit in the deck (2026-10-12); + never more than you own (2026-10-23, package PG: the drop skipped that check)
      denyShake(listEl);
      try{ fxHook('deckFull', listEl); }catch(e){} // 2026-10-15 batch F
      return;
    }
    { const rb = deckRankBlockFor(myDeckCounts, defId, defs, deckLeaderIds()); // 2026-10-22 (package DR): the top-rank deck caps
      if(rb){ denyShake(listEl); floatText(listEl, deckRankLimitText(rb), 'debuff'); try{ fxHook('deckFull', listEl); }catch(e){} return; } }
    myDeckCounts[defId] = (myDeckCounts[defId]||0) + 1;
    saveMyDeck();
    renderMyDeckPanels();
    try{ vis4CapTip(defId, myDeckCounts, '#myDeckList'); }catch(e){} // 2026-10-27 (package VIS4, K16)
  });
}
