function activateSpot(spot){
  if(spot.needs && !featureUnlocked(spot.needs)) return; // 2026-10-24 (package MAP, owner 13:16 #20)
  const first = !featureUnlocked(spot.key);
  if(first) fxHook('mapSpotUnlock', document.querySelector(`[data-spot="${spot.key}"]`), spot.key); // each spot opens in its own way (FX.E, 2026-10-15)
  if(first){ unlockFeature(spot.key); try{ if(SoundKit.unlock) SoundKit.unlock(); }catch(e){} showToast(`${spot.icon} ${spot.name} — unlocked!`, 'ok');
    if(spot.key === 'deck') setTimeout(()=>{ try{ const n = releaseHeldPacks(); if(n) fxHook('heldPacks', n); }catch(e){} }, 1200); // fxHook: 2026-10-15 batch F // packs won before the Armoury (2026-10-15)
    const script = DIALOGUES[spot.dialogue];
    // A first visit whose conversation offers to take you there (a reply with an act) lets that reply do it (2026-10-12).
    if(script && script.lines.some(l=> l.act || (l.options||[]).some(o=> o.act))){ playDialogue(spot.dialogue, {once:true, expand:true}); return; }
    if(spot.dialogue) playDialogue(spot.dialogue, {once:true, expand:true}); } // (PL2: the Group Dungeon spot has no conversation)
  spot.go();
}
// Maps that have a generated pixel-art background baked into the build (see assemble_arena.py).
// 2026-10-15 (user: "Are there any submaps with no background? fill them in."): the Old Bramble, Ice Hollow, Glimmer Depths,
// Sunken Grove, Aerie Vault and Volcano Lair had art baked in but weren't listed here, so it never drew; Murgle Mayhem had none.
// They now borrow a recoloured map (MAP_ART_DERIVED in assemble_arena.py), and the build fails if this list falls behind.
// 2026-10-18: + the Babel Spire ("tw") and the Long Burrow ("mlb"), which drew only a gradient.
const MAP_ART_IDS = new Set(["marena","mabyss","mf","mb","mg","mu","mp","mc","mw","mk","mh","mr","ml","mt","md","my","mq","mz","me","m1","m2","m3","m4","m5","m6","m7","m8","m9","m10","m11","m21","m22","m23","m24","mtut","mj","mo","mi","mn","ms","mv","mx","mm","mlb","tw","mpd","muc"]); // + "mpd", the Pale Desert (2026-10-18, package PD: tools/make_map_backgrounds.py mpd)
// Draggable map tiles (2026-10-09, user: "Let me drag and drop the secondary map tiles like armoury, nest, and
// cave"): feature spots, the well, the chat cave and sub-map entrances keep their position in the same layout
// override as the fight nodes, under keys starting with "~" (so publishing the layout carries them too).
function decorPos(mapId, key, fallback){
  const o = (mapLayoutOverrides[mapId]||{})[key];
  return (o && isFinite(o.x) && isFinite(o.y)) ? {x:+o.x, y:+o.y} : fallback;
}
// Interactible gates (2026-10-12, user: "The interactibles on each map shouldn't be interactible till ... we complete a
// certain skirmish. Let me edit it in edit link mode. Unlike traditional skirmishes or map markets ... no line is drawn"):
// a map tile can name the fight that reveals it (`after`), kept with its position in the layout override, so 🔗 Edit links
// sets it and publishing the layout carries it. Curiosities, the well and the chat cave default to the map's first fight.
function decorAfter(mapId, key, fallback){
  const o = (mapLayoutOverrides[mapId]||{})[key];
  return (o && Object.prototype.hasOwnProperty.call(o, 'after')) ? (o.after || null) : ((Array.isArray(fallback) ? fallback.length : fallback) ? fallback : null);
}
function firstFightKey(map){ const n = map && map.nodes.find(x=> x.kind!=='tutorial'); return n ? n.key : null; }
function decorEditing(){ return !!(adminModeEnabled && (conquestLayoutEdit || conquestLinkEdit)); }
function decorRevealed(mapId, key, fallback, progress){
  const a = decorAfter(mapId, key, fallback); if(!a) return true;
  progress = progress || loadConquestProgress();
  return (progress.completed||[]).includes(conquestNodeId(mapId, a));
}
// Shown at all? Editors see every tile (a hidden one dimmed, with its gate in the tooltip).
function decorShown(mapId, key, fallback){ return decorEditing() || decorRevealed(mapId, key, fallback); }
function decorGateNote(map, key, fallback){
  if(!decorEditing()) return '';
  const a0 = decorAfter(map.id, key, fallback), a = Array.isArray(a0) ? a0[a0.length - 1] : a0, n = a && map.nodes.find(x=> x.key === a);
  return n ? ` · appears after ${skirmishCode(map.id, a) || a} ${n.name}` : ' · always there';
}
// One tap at a time (2026-10-12, user: "Dont let me spam click the sign"; "The interactibles shouldn't be spammable"):
// a map tile ignores taps for a moment after one lands.
// 2026-10-24 (package MAP, owner 13:16 #19: "While NPC dialogue is active, clicking map interactibles plays a dull sound and the object shakes
// (instead of opening)"; #20: interactibles that open the notice board before it is unlocked are uninteractible: dull sound + shake + a small
// "Locked for now" label): one helper for both. A tile that is blocked does nothing else; the caller returns when this says true.
// 2026-10-24 (package EN5, owner MAP-3: "tutorials have priority. And they dont even use the dialogue anyway, they use a different parallel
// form"): a tutorial lesson (the coach tips and their spotlight: showCoachTip / tutorialLock, and the lesson scripts that teach a rule:
// lesson_*, tut_*, pitch_lesson_*, training_wheels_off) never counts as an NPC conversation, and while a lesson is on screen no map tile is
// held back by an NPC conversation either: the tile the lesson points at always opens. Only a real NPC conversation that is playing counts.
const EN5_LESSON_DIALOGUE = /^(lesson_|tut_|pitch_lesson|pitch_spent|training_wheels)/;
function tutorialLessonOn(){ try{ return !!(coachOpen || tutorialLock || coachShield); }catch(e){ return false; } }
function npcDialogueActive(){ try{ if(tutorialLessonOn()) return false; for(const id of dialoguesPending){ if(!EN5_LESSON_DIALOGUE.test(String(id))) return true; } return false; }catch(e){ return false; } }
function noticeBoardUnlocked(){ try{ return featureUnlocked('quests'); }catch(e){ return true; } }
function lockedTileTap(el, label){
  if(!el) return;
  try{ SoundKit.dullTap(); }catch(e){}
  el.classList.remove('tile-dull-shake'); void el.offsetWidth; el.classList.add('tile-dull-shake'); setTimeout(()=> el.classList.remove('tile-dull-shake'), 420);
  if(label){ el.querySelectorAll('.map-lock-label').forEach(x=> x.remove()); const l = document.createElement('span'); l.className = 'map-lock-label'; l.textContent = label; l.setAttribute('role', 'status'); el.appendChild(l); setTimeout(()=> l.remove(), 1700); }
}
// true = the tile must not open right now (and it has shaken)
function mapTileBlocked(el, needs){
  if(needs && needs === 'quests' && !noticeBoardUnlocked()){ lockedTileTap(el, TX('ui.map-locked-for-now')); return true; }
  if(npcDialogueActive()){ lockedTileTap(el, null); return true; }
  return false;
}
// 2026-10-25 (package FIX3, G1, owner: "Noone wants to wait for the dialogue ... if I click again, I should go into the page. Even while the
// dialogue is talking."): a second tap on an open feature spot (Camp, Codex, Forge ...) within 20 s of the first opens it at once, past the
// tap gate, the NPC-is-talking shake and a first visit's "take me there" reply. The conversation carries on in its dock.
const FIX3_AGAIN_MS = 20000;
function fix3SpotAgain(b){
  const now = Date.now(), again = !!(b._fix3At && now - b._fix3At < FIX3_AGAIN_MS); b._fix3At = now;
  if(!again) return false;
  const sp = FEATURE_SPOTS.find(x=> x.key === b.dataset.spot); if(!sp || !featureUnlocked(sp.key) || (sp.needs && !featureUnlocked(sp.needs))) return false;
  b._fix3At = 0; try{ sp.go(); }catch(e){ return false; } return true;
}
function mapTapGate(el, ms){
  if(!el) return true; const now = Date.now();
  if(el._tapUntil && now < el._tapUntil) return false;
  el._tapUntil = now + (ms || 2600); return true;
}
// The "!" on a tile fades once you've looked (2026-10-12, user: "After clicking a conquest map feature like 'Quest Boards',
// the exclamation mark saying its new should fade").
function fadeNewBang(el){
  if(!el) return; el.classList.remove('is-new');
  el.querySelectorAll('.map-spot-new').forEach(b=>{ b.classList.add('is-fading'); setTimeout(()=> b.remove(), 450); });
}
function mapSpotsHTML(map, positions, progress){
  // 2026-10-08 (user: "a little higher; draw less opaque lines towards their unlocking skirmish"):
  // spots sit further above their skirmish, joined to it by a faint dashed line.
  const links = [];
  if(map.id==='m1' && !loadTutorial2Done() && !adminModeEnabled) return ''; // only the two tutorials until part 2 is won (2026-10-12)
  // 2026-10-12 (user: "Secondary points like Armoury point on conquest maps should be darked out with ? tooltip until their
  // links are established"): a spot on an open map whose fight isn't cleared yet shows as a dark "?" with no line.
  const mapOpen = isMapUnlocked(map, progress);
  // 2026-10-15: spots that share a skirmish and have no place of their own fan out side by side (Map 13's Raid Banner, Gilded
  // Caravan and Wanderer's Camp all sat on one point, names over each other), each ~11% further from the map's edge.
  const fanN = {}, fanned = (sp, idx, base, def)=>{ if(sp.pos) return def; const k = (fanN[idx] = (fanN[idx] || 0) + 1) - 1; if(!k) return def;
    const dir = base.x > 50 ? -1 : 1; return {x: Math.max(4, Math.min(96, def.x + dir*11*k)), y: def.y}; };
  const unknown = mapOpen ? FEATURE_SPOTS.filter(sp=> sp.map===map.id && !pl2SpotHidden(sp) && !ui6SpotOffMap(sp) && !spotAvailable(sp, progress)).map(sp=>{
    const after = spotAfter(sp), idx = after ? map.nodes.findIndex(n=> n.key===after) : map.nodes.findIndex(n=> n.kind!=='tutorial');
    const base = positions[Math.max(0, idx)] || {x:50, y:50};
    const def = fanned(sp, idx + ':' + !!after, base, sp.pos || {x: Math.max(4, Math.min(96, base.x + (after ? 5 : -6))), y: Math.max(8, Math.min(92, base.y + (after ? -27 : 14)))}); // sp.pos: a spot's own default spot (2026-10-15)
    const {x, y} = decorPos(map.id, '~spot:'+sp.key, def);
    const tip = decorEditing() ? sp.name + decorGateNote(map, '~spot:'+sp.key, sp.after) : '?';
    return `<button type="button" class="map-spot is-unknown" data-lkey="~spot:${sp.key}" style="left:${x}%; top:${y}%;" title="${escapeAttr(tip)}" aria-label="Something not found yet" aria-disabled="true"><span class="map-spot-ico" aria-hidden="true">?</span></button>`;
  }).join('') : '';
  const html = unknown + FEATURE_SPOTS.filter(sp=> sp.map===map.id && !pl2SpotHidden(sp) && !ui6SpotOffMap(sp) && spotAvailable(sp, progress) && !(sp.vanish && featureUnlocked(sp.key))).map(sp=>{
    const spAfter = spotAfter(sp);
    const idx = spAfter ? map.nodes.findIndex(n=> n.key===spAfter) : map.nodes.findIndex(n=> n.kind!=='tutorial');
    const base = positions[Math.max(0, idx)] || {x:50, y:50};
    const def = fanned(sp, idx + ':' + !!spAfter, base, sp.pos || {x: Math.max(4, Math.min(96, base.x + (spAfter ? 5 : -6))), y: Math.max(8, Math.min(92, base.y + (spAfter ? -27 : 14)))});
    const {x, y} = decorPos(map.id, '~spot:'+sp.key, def);
    if(spAfter) links.push(`<line data-a="${escapeAttr(spAfter)}" data-b="~spot:${sp.key}" x1="${base.x}" y1="${base.y}" x2="${x}" y2="${y}"/>`);
    const open = featureUnlocked(sp.key), waits = !!(sp.needs && !featureUnlocked(sp.needs)); // 2026-10-24 (package MAP, owner 13:16 #20): waits for the Notices
    return `<button type="button" class="map-spot ${waits ? 'is-waiting' : open?'is-open':'is-new'}${sp.mapHidden ? ' ui6-map-hidden' /* X22: only the layout editor draws it */ : ''}" ${waits ? `data-needs="${escapeAttr(sp.needs)}" aria-disabled="true" ` : ''}data-spot="${sp.key}" data-lkey="~spot:${sp.key}" style="left:${x}%; top:${y}%; --shk:-${((sp.key||"").length*0.7)%5}s;" title="${escapeAttr(sp.name + (waits ? ' — ' + TX('ui.map-locked-for-now') : open ? '' : ' — something new!'))}" aria-label="${escapeAttr(sp.name)}">
      <span class="map-spot-ico">${sp.icon}</span>${waits ? '<span class="map-spot-lock" aria-hidden="true">🔒</span>' : open ? '' : '<span class="map-spot-new">!</span>'}<span class="map-spot-name">${escapeHtml(sp.name)}</span></button>`;
  }).join('');
  return (links.length ? `<svg class="map-spot-links" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${links.join('')}</svg>` : '') + html;
}
// The old well (2026-10-08, user: "a well object in the first map, that triggers a conversation in
// the top left. This only happens once."). A small stone well by the pond on the Outskirts; the first
// visit plays a short scene (with a choice), after that it just ripples.
function mapWellHTML(){
  if(!decorShown('m1', '~well', '0-1')) return '';
  const seen = !!loadDialogueFlags()['seen:well_m1'];
  const p = decorPos('m1', '~well', {x:67, y:79});
  const gated = !decorRevealed('m1', '~well', '0-1'), m1 = CONQUEST_MAPS.find(m=> m.id==='m1');
  return `<button type="button" class="map-well ${seen ? '' : 'is-new'} ${gated ? 'is-gated' : ''}" id="mapWell" data-lkey="~well" style="left:${p.x}%; top:${p.y}%;" title="${escapeAttr('An old well' + (m1 ? decorGateNote(m1, '~well', '0-1') : ''))}" aria-label="An old well">
    <span class="mw-roof" aria-hidden="true"></span><span class="mw-posts" aria-hidden="true"></span><span class="mw-bucket" aria-hidden="true"></span><span class="mw-ring" aria-hidden="true"></span>
    ${seen ? '' : '<span class="map-spot-new">!</span>'}</button>`;
}
