let conquestSubZoom = null;
function subMapEntrancesHTML(map, progress){
  return CONQUEST_MAPS.filter(m=> m.sub && m.parent===map.id && m.entry && !(typeof dungeonHiddenFromPlayer === 'function' && dungeonHiddenFromPlayer(m)) /* 2026-10-23 (TU2): a hidden daily dungeon has no entrance */).map(sm=>{
    const open = isMapUnlocked(sm, progress), after = sm.entry.after && map.nodes.find(n=> n.key===sm.entry.after);
    const fightable = sm.nodes.filter(n=> n.kind!=='tutorial'), done = fightable.filter(n=> progress.completed.includes(conquestNodeId(sm.id, n.key))).length;
    const seen = !!loadDialogueFlags()['submap_seen:'+sm.id];
    // 2026-10-18 (owner: Lilypad Reach waits on Gatorback Swamp): an entrance gated on another map names that map ("Clear
    // Gatorback Swamp to open"); that map is always further down the road than the entrance's own fight.
    const gateMap = !open && sm.entry.afterMapCleared && !conquestMapCleared(sm.entry.afterMapCleared) ? CONQUEST_MAPS.find(m=> m.id===sm.entry.afterMapCleared) : null;
    // 2026-10-18 (owner: Lilypad Reach waits on Map 6): a main map is named with its number, "Clear Sable Swampmire (Map 6) to open".
    const gateName = gateMap ? gateMap.name + (!gateMap.sub && mapNumberOf(gateMap.id) != null ? ` (Map ${mapNumberOf(gateMap.id)})` : '') : '';
    const tip = open ? `${sm.name} — ${done}/${fightable.length} cleared` : gateMap ? `${sm.entry.label || 'A cave'} — Clear ${gateName} to open` : `${sm.entry.label || 'A cave'} — clear ${after ? after.name : 'more of this map'} to find a way in`;
    const p = decorPos(map.id, '~sub:'+sm.id, {x: sm.entry.x, y: sm.entry.y});
    // 2026-10-12 (user: "For those submaps whose maps are not caves - change the map icon/logo to be more representative.
    // Lilypad reach should be a lotus flower. and just that!"): only the real caves keep the rock and cave mouth; every other
    // side map is just its own emblem (a lotus, a clover, a nest…), with a padlock badge while it's locked.
    if(!SUBMAP_CAVES.has(sm.id)){
      return `<button type="button" class="map-cave map-subcave map-subemblem ${open ? '' : 'is-locked'} ${done && done===fightable.length ? 'is-done' : ''}${flairLairMap(sm) ? ' is-lair-final' : ''}" ${open ? `data-submap="${sm.id}"` : ''} ${open || conquestLayoutEdit ? '' : 'disabled'} data-lkey="~sub:${sm.id}" style="left:${p.x}%; top:${p.y}%;" title="${escapeAttr(tip)}" aria-label="${escapeAttr(tip)}">
      <span class="mse-ico" aria-hidden="true">${SUBMAP_EMBLEM_SVG[sm.id] || sm.icon}</span>${flairLairMap(sm) ? flairLairEntranceHTML() /* FLAIR1 (2026-10-28): the Dragon Lair's molten ring and crown */ : ''}${open ? '' : '<span class="mse-lock" aria-hidden="true">🔒</span>'}${open && !seen ? '<span class="map-spot-new">!</span>' : ''}${open ? `<span class="msc-name">${escapeHtml(sm.name)}</span>` : ''}</button>`;
    }
    return `<button type="button" class="map-cave map-subcave ${open ? '' : 'is-locked'} ${done && done===fightable.length ? 'is-done' : ''}" ${open ? `data-submap="${sm.id}"` : ''} ${open || conquestLayoutEdit ? '' : 'disabled'} data-lkey="~sub:${sm.id}" style="left:${p.x}%; top:${p.y}%;" title="${escapeAttr(tip)}" aria-label="${escapeAttr(tip)}">
      <span class="mc-rock" aria-hidden="true"></span><span class="mc-mouth" aria-hidden="true"></span>${open ? '' : '<span class="mse-lock" aria-hidden="true">🔒</span>'}${open && !seen ? '<span class="map-spot-new">!</span>' : ''}${open ? `<span class="msc-name">${escapeHtml(sm.name)}</span>` : ''}</button>`;
  }).join('');
}
// "Boom, transition-zooms into the cave": the parent map zooms into the cave mouth and goes dark, then
// the sub-map grows out of the dark. Leaving reverses it with a quick pull-back.
function enterSubMap(id, el, body){
  const sm = CONQUEST_MAPS.find(m=> m.id===id); if(!sm || !isMapUnlocked(sm, loadConquestProgress())) return;
  try{ setDialogueFlag('submap_seen:'+id, true); }catch(e){}
  abandonMapLayoutEdit();
  const mainEl = document.getElementById('conquestMain');
  const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const go = ()=>{ conquestSelectedMap = id; conquestSelectedNodeKey = null; conquestSubZoom = reduce ? null : 'in'; renderConquestSubTab(body); };
  if(!mainEl || reduce || !mainEl.animate || !el) return go();
  const mr = mainEl.getBoundingClientRect(), r = el.getBoundingClientRect();
  // A side map in daylight (2026-10-14, user: "If the submap is not dark, don't need to darken the screen - just zoom into the
  // entrance, then open and zoom out from the new submap."): no iris and no loading card, just the camera. Caves and dark side
  // maps keep the dive into the dark below.
  // 2026-10-14 (user: "When going into clovermead and similar submaps, dont zoom the whole screen in, just the map. Then when we go
  // into the submap, the new map zooms in to fit our screen size. (The same method as zoom out, but opposite)"): only the map
  // (its art, trail and fights) zooms into the entrance; the map list beside it holds still. The side map then starts small in
  // the middle of its panel and grows to fill it, the reverse of leaving one.
  if(!subMapIsDark(sm)){
    const lay = document.getElementById('conquestLayout') || mainEl, lr = lay.getBoundingClientRect();
    try{ SoundKit && SoundKit.play && SoundKit.play('whoosh'); }catch(e){}
    document.documentElement.classList.add('submap-zooming');
    // 2026-10-16 (user: "When zooming in a submap like Tutorial, and clovermead, the map background doesnt need to zoom in that much, just a
    // little bit."): a small push toward the entrance (×1.3, was ×4.5), and the side map grows from 90% (was 35%), below.
    const za = mapOnlyZoom(lay, 1, SUBMAP_PUSH_ZOOM, r.left + r.width/2 - lr.left, r.top + r.height/2 - lr.top, 480, t=> t*t, true);
    za.onfinish = ()=>{ conquestVeiledMap = id; // the side map's loading card would darken the screen again
      conquestSelectedMap = id; conquestSelectedNodeKey = null; conquestSubZoom = 'grow'; renderConquestSubTab(body); try{ za.cancel(); }catch(e){} };
    setTimeout(()=> document.documentElement.classList.remove('submap-zooming'), 2200);
    return;
  }
  mainEl.style.transformOrigin = `${r.left + r.width/2 - mr.left}px ${r.top + r.height/2 - mr.top}px`;
  try{ SoundKit && SoundKit.play && SoundKit.play('whoosh'); }catch(e){}
  // An iris closes on the cave mouth while the map dives into it (the map art lives on the layout
  // behind #conquestMain, so the iris is what sells the "into the cave" part).
  // 2026-10-12 (user: "When entering a cave, the blackness is not full-screen"): the iris covers the whole screen, not
  // just the map panel, closing on the cave mouth wherever it sits.
  const vw = window.innerWidth, vh = window.innerHeight, scr = {left:0, top:0, width:vw, height:vh};
  const cx = r.left + r.width/2, cy = r.top + r.height/2;
  const iris = subMapIris(scr, cx, cy);
  const big = 2 * Math.hypot(Math.max(cx, vw-cx), Math.max(cy, vh-cy));
  iris.firstChild.animate([{width:big+'px', height:big+'px'}, {width:'0px', height:'0px'}], {duration:470, easing:'ease-in', fill:'forwards'});
  const a = mainEl.animate([{transform:'none', filter:'none'}, {transform:'scale(5)', filter:'brightness(0)'}], {duration:470, easing:'cubic-bezier(.6,0,.9,.4)', fill:'forwards'});
  a.onfinish = ()=>{ mainEl.style.transformOrigin = ''; go();
    // …and opens again from the middle of the new map.
    const m2 = document.getElementById('conquestMain'); const nr = m2 ? m2.getBoundingClientRect() : mr;
    const W = window.innerWidth, H = window.innerHeight, ox = nr.left + nr.width/2, oy = nr.top + nr.height/2;
    iris.style.left = '0px'; iris.style.top = '0px'; iris.style.width = W+'px'; iris.style.height = H+'px';
    iris.firstChild.style.left = ox+'px'; iris.firstChild.style.top = oy+'px';
    const big2 = 2 * Math.hypot(Math.max(ox, W-ox), Math.max(oy, H-oy)) * 1.05;
    const o = iris.firstChild.animate([{width:'0px', height:'0px'}, {width:big2+'px', height:big2+'px'}], {duration:600, easing:'cubic-bezier(.4,0,.3,1)', fill:'forwards'});
    o.onfinish = ()=> iris.remove(); setTimeout(()=> iris.remove(), 900);
  };
}
// Zoom the map but not the map list (2026-10-14): the art lives on #conquestLayout, which also holds the list, so the layout is
// scaled about (ox, oy) and the list gets the exact inverse scale at every keyframe (its own origin placed on the same point),
// which keeps it where it is. ease maps 0–1 progress to 0–1; the keyframes carry the easing, so they run linear.
const SUBMAP_PUSH_ZOOM = 1.3, SUBMAP_GROW_FROM = .9; // daylight side maps: how far the map pushes in, and where the side map grows from (2026-10-16)
function mapOnlyZoom(lay, from, to, ox, oy, ms, ease, hold){
  const list = lay.querySelector(':scope > .conquest-maps'), N = 18, ks = [], lk = [];
  const lo = list ? {x: list.offsetLeft, y: list.offsetTop} : null;
  for(let k = 0; k <= N; k++){ const t = k / N, sc = from + (to - from) * ease(t);
    ks.push({transform:`scale(${sc})`, transformOrigin:`${ox}px ${oy}px`, offset:t});
    if(list) lk.push({transform:`scale(${1/sc})`, transformOrigin:`${ox - lo.x}px ${oy - lo.y}px`, offset:t}); }
  const o = {duration:ms, easing:'linear', fill: hold ? 'forwards' : 'none'};
  const a = lay.animate(ks, o);
  // shrunk below full size, the layout's own clip would cut the (held-still) list off, so it may overflow while the zoom runs
  if(list){ list.style.zIndex = '3'; if(Math.min(from, to) < 1) lay.style.overflow = 'visible'; const b = list.animate(lk, o); const done = ()=>{ list.style.zIndex = ''; lay.style.overflow = ''; };
    a.addEventListener('finish', ()=> setTimeout(()=>{ try{ b.cancel(); }catch(e){} done(); }, 0)); a.addEventListener('cancel', ()=>{ try{ b.cancel(); }catch(e){} done(); }); }
  return a;
}
function subMapIris(rect, cx, cy){
  document.querySelectorAll('.submap-iris').forEach(e=> e.remove());
  const w = document.createElement('div'); w.className = 'submap-iris'; w.setAttribute('aria-hidden', 'true');
  w.style.cssText = `left:${rect.left}px; top:${rect.top}px; width:${rect.width}px; height:${rect.height}px;`;
  w.innerHTML = `<span style="left:${cx}px; top:${cy}px;"></span>`;
  document.body.appendChild(w); return w;
}
function leaveSubMap(sm, body){
  const mainEl = document.getElementById('conquestMain');
  const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const go = ()=>{ conquestSelectedMap = sm.parent; conquestSelectedNodeKey = null; conquestSubZoom = reduce ? null : 'out'; renderConquestSubTab(body); };
  if(!mainEl || reduce || !mainEl.animate) return go();
  const a = mainEl.animate([{transform:'none', opacity:1}, {transform:'scale(.6)', opacity:0}], {duration:220, easing:'ease-in', fill:'forwards'});
  a.onfinish = go;
}
// Sub-map exit (2026-10-10, user: "The Smuggler's grotto should also have a corresponding cave exit symbol in the
// map to go back out... a shine from its hole... a 'link' that leads to the first skirmish"). Daylight spills out of
// the mouth; a faint dashed line joins it to the first fight. Click to climb back out to the parent map.
// Which side maps are underground (2026-10-13, user: "Those submaps which are not caves - the exit areas should not be cave
// symbols - just use an icon representing the main map"). A map can say `cave:true` itself.
const CAVE_SUBMAPS = new Set(['mg', 'mz', 'mx']);
function isCaveSubMap(map){ return !!(map && (map.cave || CAVE_SUBMAPS.has(map.id))); }
// Dark side maps (2026-10-14): caves, cave-look maps and any map whose fights are in the dark keep the dive into the dark.
function subMapIsDark(map){ if(!map) return false; if(isCaveSubMap(map) || map.dark || DARK_MAPS.has(map.id)) return true; try{ if(isCaveMap(map)) return true; }catch(e){}
  try{ return map.nodes.some(n=> n.kind !== 'tutorial' && (n.rules || {}).dark); }catch(e){ return false; } }
function subMapExitHTML(map, positions){
  if(!map.sub) return '';
  // 2026-10-23 (package TU2, owner 00:10: "If T1-T2 is complete, T2 leads to an exit to Map 0"): the Tutorial's way out opens once
  // T-1 and T-2 are both won (tutorialPairDone: the flags or the progress), stands beside T-2 (tutorial2) and leads to Map 0;
  // taking it also sets the flags the full map needs (see the #mapSubExit click). Was: only once the Tutorial II flag was set.
  const tut = map.id === 'mtut';
  if(tut && !tutorialPairDone()) return '';
  const parent = CONQUEST_MAPS.find(m=> m.id === map.parent); if(!parent) return '';
  const idx = tut ? map.nodes.findIndex(n=> n.key === 'tutorial2') : map.nodes.findIndex(n=> n.kind !== 'tutorial'), base = positions[Math.max(0, idx)] || {x:50, y:50};
  const def = tut ? {x: Math.max(6, Math.min(94, base.x + 12)), y: Math.max(10, Math.min(90, base.y - 14))} // beside T-2, up and to its right
    : map.axis === 'x' ? {x: Math.max(1, base.x - 2.6), y: Math.max(10, Math.min(90, base.y + 24))} // a left-to-right dungeon: just behind floor 1 (2026-10-16)
    : {x: Math.max(6, Math.min(94, base.x - 12)), y: Math.max(10, Math.min(90, base.y + 16))};
  const p = decorPos(map.id, tut ? '~exit-t2' : '~exit', def), key = map.nodes[Math.max(0, idx)] && map.nodes[Math.max(0, idx)].key;
  const tip = tut ? TX('map.tu2-exit-tip', {n: mapNumberOf(parent.id) ?? 0, name: parent.name}) : 'Way out — back to ' + parent.name;
  return `<svg class="map-spot-links map-exit-link" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><line ${key ? `data-a="${escapeAttr(key)}" data-b="~exit"` : ''} x1="${base.x}" y1="${base.y}" x2="${p.x}" y2="${p.y}"/></svg>
    <button type="button" class="map-cave map-subexit ${isCaveSubMap(map) ? 'is-cave' : 'is-open'}" id="mapSubExit" data-lkey="~exit" style="left:${p.x}%; top:${p.y}%;" title="${escapeAttr(tip)}" aria-label="${escapeAttr(tip)}">
      ${isCaveSubMap(map) ? `<span class="mse-rays" aria-hidden="true"></span><span class="mc-rock" aria-hidden="true"></span><span class="mc-mouth mse-mouth" aria-hidden="true"></span><span class="mse-lamp" aria-hidden="true"></span>` : `<span class="mse-home" aria-hidden="true">${parent.icon || '🗺️'}</span>`}<span class="msc-name">${tut ? escapeHtml(TX('map.tu2-exit')) /* 2026-10-23 (package FX4, owner: "Tutorials: \"To Map 0\" should just \"Exit\""): was '↑ To Map 0' */ : '↑ Way out'}</span></button>`;
}
