// The leaves part to reveal the map (end of the tutorial).
function leavesRevealToMap(){
  playSubTab = 'conquest'; conquestSelectedMap = 'm1'; conquestSelectedNodeKey = null;
  switchTab('play');
  const cover = document.createElement('div');
  cover.className = 'leaves-cover'; cover.setAttribute('aria-hidden','true');
  const glyphs = ['🌿','🍂','🍁','🌿','🍂','🌱'];
  const rnd = seededRng(20261003);
  let html = '';
  // a jittered grid, so the cover is dense everywhere without visible rows
  for(let i=0;i<160;i++){ const gx = i%16, gy = Math.floor(i/16); const x = Math.min(99, (gx + rnd())*6.4 - 1), y = Math.min(99, (gy + rnd())*10.4 - 2); html += `<span class="lc-leaf" style="left:${x}%; top:${y}%; font-size:${46 + (i*7)%40}px; transform:rotate(${(i*47)%360}deg)" data-side="${x<50?-1:1}">${glyphs[i%glyphs.length]}</span>`; }
  cover.innerHTML = html;
  document.body.appendChild(cover);
  const done = ()=>{ cover.remove(); playDialogue('outskirts_reveal', {once:true}); };
  if(!hasGsap()){ setTimeout(done, 400); return; }
  try{ if(SoundKit.shift) SoundKit.shift(); }catch(e){}
  const tl = gsap.timeline({delay:.5, onComplete: done});
  cover.querySelectorAll('.lc-leaf').forEach(l=>{ const side = +l.dataset.side; tl.to(l, {x: side*(window.innerWidth*0.75 + Math.random()*200), y: (Math.random()-.5)*240, rotation: '+=' + (side*(180+Math.random()*240)), duration: 1.3 + Math.random()*.5, ease: 'power3.in'}, Math.random()*.25); });
  tl.to(cover, {backgroundColor: 'rgba(20,40,16,0)', duration: 1.1, ease: 'power2.in'}, .2);
}
