// bursts up through the struck card, embers fly, and the whole field flashes red.
// Tide-spout (2026-10-14): the same geyser in water (water=true): a blue-white column and spray, no red flash.
function eruptionGeyserVfx(el, water){
  if(!el || reducedMotion() || !fxAtLeast('low')) return;
  const r = el.getBoundingClientRect(), g = document.createElement('div');
  g.className = 'lava-geyser' + (water ? ' is-water' : ''); g.setAttribute('aria-hidden', 'true');
  g.style.left = (r.left + r.width / 2) + 'px'; g.style.top = (r.bottom - 6) + 'px'; g.style.setProperty('--h', Math.round(r.height * 1.25) + 'px');
  // 2026-10-16 (user: "Tide Spout - Make it fade in and fade out faster."): the water spout rises and drains in about half the time.
  g.innerHTML = '<i class="lg-col"></i>' + Array.from({length: 12}, (_, k)=> `<b style="--x:${Math.round((Math.random() - .5) * r.width * 1.2)}px; --y:${-Math.round(r.height * (.6 + Math.random() * .8))}px; --d:${(k * (water ? 0.02 : 0.04)).toFixed(2)}s"></b>`).join('');
  document.body.appendChild(g); setTimeout(()=> g.remove(), water ? 750 : 1300);
  if(water) return;
  const bf = document.getElementById('battlefieldEl'); if(bf){ bf.classList.remove('erupt-flash'); void bf.offsetWidth; bf.classList.add('erupt-flash'); setTimeout(()=> bf.classList.remove('erupt-flash'), 800); }
}
// The terrain's first appearance in a match: a banner across the field saying what it does, then it lives in the pill.
function maybeTerrainIntro(m){
  if(!m || m._terrainIntro) return; const tr = terrainOfMatch(m); if(!tr) return; m._terrainIntro = true;
  if(!(tr.t ? terrainSummary(tr.t, tr.rules) : Number(tr.rules.eruption) > 0)) return; // no home ground any more (2026-10-14): a quiet terrain has nothing to announce
  setTimeout(()=>{ const bf = document.getElementById('battlefieldEl'); if(!bf || matchState !== m) return;
    const t = tr.t, er = Number(tr.rules.eruption) || 0;
    const b = document.createElement('div'); b.className = 'terrain-banner biome-' + (t ? t.biome : 'ash'); b.setAttribute('role', 'status');
    b.innerHTML = `<b>${escapeHtml(t ? `${t.icon} ${t.name}` : '🔥 ' + SCORCHED_NAME)}</b><span>${keywordizeHTML(escapeHtml(t ? terrainSummary(t, tr.rules) : scorchedGroundText(er)))}</span>`;
    bf.appendChild(b); try{ fxHook('terrainBanner', b); }catch(e){} // FX batch B (2026-10-15)
    // 2026-10-14: it then shrinks into the field card on the enemy's side, where it stays.
    setTimeout(()=>{ const c = document.getElementById('fieldCondCard'); if(!c || reducedMotion()){ b.classList.add('is-out'); return; }
      const cr = c.getBoundingClientRect(), br = b.getBoundingClientRect(); const dx = (cr.left + cr.width/2) - (br.left + br.width/2), dy = (cr.top + cr.height/2) - (br.top + br.height/2);
      b.style.transition = 'transform .65s cubic-bezier(.5,0,.75,0), opacity .65s ease-in'; b.style.animation = 'none';
      b.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px)) scale(.12)`; b.style.opacity = '0';
      setTimeout(()=>{ const c2 = document.getElementById('fieldCondCard'); if(c2){ c2.classList.remove('is-landing'); void c2.offsetWidth; c2.classList.add('is-landing'); setTimeout(()=> c2.classList.remove('is-landing'), 700); } }, 600); }, 5200);
    setTimeout(()=> b.remove(), 6000); }, 900);
}
