    deckTotals: snap.deckTotals || {1:snap.players[1].deck.length, 2:snap.players[2].deck.length}, speedMult: snap.speedMult||1,
    leaderDefId: snap.leaderDefId||null, leaderUid: snap.leaderUid||null,
