    const tgt = idle ? {x: Math.max(3, Math.min(97, cur.x + (Math.random()*16-8))), y: Math.max(5, Math.min(95, cur.y + (Math.random()*12-6)))} : spots[Math.floor(Math.random()*spots.length)];
    const dist = Math.hypot(tgt.x-cur.x, tgt.y-cur.y);
