  return tutSideCentred(map, map.nodes.map((n,i)=> (!n.ambush && !(opening && n.kind==='tutorial') && ov[n.key] && isFinite(ov[n.key].x) && isFinite(ov[n.key].y)) ? {x:+ov[n.key].x, y:+ov[n.key].y} : base[i]));
