    const fightable = m.nodes.filter(n=> n.kind!=='raidboss' && n.kind!=='tutorial');
    const doneN = fightable.filter(n=> progress.completed.includes(conquestNodeId(m.id, n.key))).length;
    const pos = mapNodePositions(m);
