function startTipTicker(el, tips){
  if(!el || el.dataset.ticking) return; el.dataset.ticking = '1';
  const list = tips || GAME_TIPS;
  const order = tips ? list.slice() : list.slice().sort(()=> Math.random() - .5); // a page's own list keeps its first line first
  let i = 0;
  const show = ()=>{
    if(!el.isConnected) return;
    if(document.hidden){ setTimeout(show, 2000); return; }
    const next = order[i++ % order.length];
    // 2026-10-08 (user): the tip keeps drifting very slowly while it shows (so it reads as temporary), leaves with a
    // fade and a zoom-out, the next one waits for most of that, and each tip stays twice as long (14 s).
    const out = el.querySelector('.tip-line:not(.tip-out)');
    if(out){ try{ out.style.translate = getComputedStyle(out).translate; }catch(e){} out.classList.add('tip-out'); setTimeout(()=> out.remove(), 450); }
    setTimeout(()=>{ if(!el.isConnected) return; const line = document.createElement('span'); line.className = 'tip-line'; line.textContent = next; el.appendChild(line); }, out ? 280 : 0);
    setTimeout(show, 14000);
  };
  show();
}
function placePlayFullHud(){
  const wrap = document.getElementById('appWrap'), view = document.getElementById('view-play'); if(!wrap || !view) return;
  wrap.classList.add('cq-hud');
  const tabs = view.querySelector('.play-subtabs-row .play-subtabs');
  wrap.classList.toggle('cq-no-tabs', !tabs || tabs.hidden);
  view.style.setProperty('--cq-top', '0px');
}
function placeConquestHud(){
  const wrap = document.getElementById('appWrap'), view = document.getElementById('view-play'), layout = document.getElementById('conquestLayout');
  if(!wrap || !view || !layout) return;
  wrap.classList.add('cq-hud');
  // A saved fight can be rejoined from the map as well as from Home (2026-10-08).
  const snap = (!matchState && loadTutorialDone()) ? loadResumeSnapshot() : null, main = document.getElementById('conquestMain');
  if(main && !main.querySelector('.cq-rejoin') && snap){
    const name = (snap.conquestNode && snap.conquestNode.name) || RESUME_MODE_LABEL[snap.mode] || 'your fight';
    const b = document.createElement('button'); b.type = 'button'; b.className = 'cq-rejoin'; b.innerHTML = `<span>▶</span> Continue <b>${escapeHtml(name)}</b> <small>round ${snap.round||1}</small>`;
    b.onclick = ()=>{ if(!resumeAbandonedMatchNow()) b.remove(); };
    main.appendChild(b);
  }
  const tabs = view.querySelector('.play-subtabs-row .play-subtabs');
  wrap.classList.toggle('cq-no-tabs', !tabs || tabs.hidden);
  requestAnimationFrame(()=>{ const pane = document.getElementById('conquestMain') || layout; const t = pane.getBoundingClientRect().top - view.getBoundingClientRect().top; view.style.setProperty('--cq-top', Math.max(0, Math.round(t)) + 'px'); });
}
// Map leaders (2026-10-10): each of Maps 1–10 has a Heroic leader as its boss's first-clear reward. Players who beat
// that boss before the leader existed get it the first time they open the map.
function grantClearedBossLeaders(){
  try{
    const pr = loadConquestProgress(), defs = getCardDefs();
    Object.values(defs).forEach(d=>{ const src = d && d.source; if(!src || src.kind !== 'map' || !(d.archetypes||[]).includes('Leader')) return;
      if((pr.completed||[]).includes(conquestNodeId(src.id, src.node)) && !myUnlockedCardIds.has(d.id) && !(myCardCopies[d.id]||[]).length){ if(loadDialogueFlags()['leaderGrant:' + d.id]) return; setDialogueFlag('leaderGrant:' + d.id, true); // once (2026-10-12: it toasted on every visit when the grant was refused)
        unlockCardForPlayer(d.id, 'conquestReward'); if(myUnlockedCardIds.has(d.id) || (myCardCopies[d.id]||[]).length) try{ showToast(TX('toast.joins-you-for-beating-that-map', {name: d.name}), 'ok'); }catch(e){} } });
  }catch(e){}
}
const CARD_REWARD_CLAIMED_KEY = 'bramblewood_card_rewards_claimed_v1';
function cardRewardsClaimed(){ try{ const raw = localStorage.getItem(CARD_REWARD_CLAIMED_KEY); if(raw) return new Set(JSON.parse(raw)); }catch(e){}
  // first run: every fight already cleared has had its cards (the old rule gave them on the first clear)
  const s0 = new Set((loadConquestProgress().completed||[])); try{ localStorage.setItem(CARD_REWARD_CLAIMED_KEY, JSON.stringify([...s0])); }catch(e){} return s0; }
function markCardRewardsClaimed(nid){ const s0 = cardRewardsClaimed(); s0.add(nid); try{ localStorage.setItem(CARD_REWARD_CLAIMED_KEY, JSON.stringify([...s0])); }catch(e){} }
// The first-clear rank a reward CARD asks (the rule today; 2026-10-24, package BAL2, T21-4: these notes said SS / SSS and "elites ask SS", which
// RW2 had replaced). Per card, not per fight: resources (Maple Leaves, Dust, materia ...) need only the clear. A Common or Uncommon asks B, a
// Rare or above S; an elite or a boss (bosses count as elites, owner call RW-1) asks S. Every CARD_RANK_STEP_MAPS (20) maps the ask steps up one
// rank, CAPPED AT S (CARD_RANK_CAP): Maps 0-19 B / S, Maps 20-39 A / S, Maps 40+ S. The one thing past S is a challenge card (a first-clear
// reward whose source carries challenge:true, set by tools/challenge_cards_2026_10_22.js): SS (CHALLENGE_CARD_RANK). A fight's own
// node.cardRank can only raise the ask. A tutorial fight (and a map with no number) asks nothing. cardId is the reward card (its rarity
// decides); with no cardId it is the rank a Common needs, the lowest the fight asks (the fight panel's drop line).
// History: 2026-10-16 a rank per fight (none on Maps 0-5, B from 6, A from 21); 2026-10-22 (RW, N22-4) per card, B / S, elites SS, +1 every 20
// maps up to SSS; 2026-10-22 (RW2, owner on RW-1: "The max cap is always S. SS and SSS is only for challenge missions") capped at S.
const CARD_RANK_STEP_MAPS = 20; // every 20 maps the ranks step up one
const CARD_RANK_CAP = 'S', CHALLENGE_CARD_RANK = 'SS'; // 2026-10-22 (RW2)
function rarityAtLeastRare(r){
  const d = RARITY_DEFS.find(x=> x.key === r), key = d ? (d.as || d.key) : 'common'; // Quest / Special / Event … count as the rank they stand for
  return RARITY_DEFS.findIndex(x=> x.key === key) >= RARITY_DEFS.findIndex(x=> x.key === 'rare');
}
function nodeIsEliteForRank(node){ const k = baseKind((node && node.kind) || 'skirmish'); return k === 'elite' || k === 'boss' || k === 'raidboss' || k === 'finalboss'; } // owner call RW-1: bosses count as elites
// Is this card a challenge card of this fight (2026-10-22, RW2): its source is this fight and carries challenge:true.
function cardRewardIsChallenge(mapId, node, cardId){
  const d = cardId ? getCardDefs()[cardId] : null, s = d && d.source;
  return !!(s && s.kind === 'map' && s.challenge === true && node && s.id === mapId && s.node === node.key);
}
function cardRewardRankFor(mapId, node, cardId){
  if(node && node.kind === 'tutorial') return null;
  const n = mapNumberOf(mapId); if(n == null) return null;
  if(cardRewardIsChallenge(mapId, node, cardId)) return CHALLENGE_CARD_RANK; // 2026-10-22 (RW2): a challenge card asks SS
  const d = cardId ? getCardDefs()[cardId] : null;
  let i = RANK_ORDER.indexOf(nodeIsEliteForRank(node) ? 'S' /* RW2: was SS */ : (d && rarityAtLeastRare(d.rarity)) ? 'S' : 'B') + Math.floor(n / CARD_RANK_STEP_MAPS);
  if(node && node.cardRank && /^(B|A|S+)$/.test(node.cardRank)) i = Math.max(i, RANK_ORDER.indexOf(node.cardRank));
  return RANK_ORDER[Math.min(i, RANK_ORDER.indexOf(CARD_RANK_CAP))]; // RW2: capped at S (was SSS)
}
// Which of a fight's reward cards are already yours (2026-10-22, RW): the node-level ledger (cardRewardsClaimed) says "all of them"; a fight
