  const all = econPayAll('raids', all0); // 2026-10-30 (ECON1): halved (Leaves, Dust, Gold Leaves, Metal), shown as paid
  Object.entries(all).forEach(([k,v])=>{ if(v>0 && CURRENCY_META[k]) grantCurrency(k, v); });
