function raidClaimTierLabel(t){ return t === 'top1' ? TX('ui.i2-top-n', {n: 1}) : t === 'top10' ? TX('ui.i2-top-n', {n: 10}) : t === 'top50' ? TX('ui.i2-top-n', {n: 50}) /* I2 template (SX) */ : TX('results.raid-tier-participant'); }
