const PG_STARTER_TOP_UP = ['pond-duck', 'acorn-chipmunk', 'cottontail', 'chipmunk-forager', 'river-carp', 'burrow-rabbit', 'meadow-rabbit', 'duckling', 'harvest-mouse', 'sheep', 'garden-snail', 'earthworm', 'guppy'];
