const TUTORIAL_COST1_IDS = { otters: ['lucky-hopper','chipmunk-cavalry','jackrabbit-sprinter'], hummingbirds: ['dominion-nestguard'] };
const TUTORIAL_COMBO_IDS = { otters: ['monarch-wingblade','termite-mound','swarm-matriarch','migration-leader'], hummingbirds: ['dominion-nestguard'] };
const TUTORIAL_WAIT_CONTRAST_IDS = { hummingbirds: ['sunthroat-courier','voidfeather-scout'] };
