// Stage 3's "have fun arranging your deck" lesson: a small curated pool (see tutorialCuratedPool)
// the player toggles cards in/out of, rather than a free-for-all across the whole Codex -- keeps
// the choice meaningful (varied stat lines) instead of 20+ near-identical Basics to sift through.
// Each selected card contributes 2 copies to the actual fight deck (see tutorialStagePlayerDeck).
let tutorialPickerSelected = null;
function showTutorialDeckPicker(){
  const el = document.getElementById('tutorialDeckPickerScreen');
  if(!el){ startTutorialMatch(3, null); return; } // defensive: DOM node missing -> skip straight to the fight rather than getting stuck
  const pick = loadFactionChoice() || 'both';
  const pool = tutorialCuratedPool(pick);
  const defs = getCardDefs();
  // Default to the first 6 pre-selected so a player who just clicks straight through still gets a
  // real, playable deck -- "arranging" is an invitation, not a gate that can strand them.
  tutorialPickerSelected = new Set(pool.slice(0,6));
  const MIN_PICKS = 4;
  function renderPicker(){
    const startBtn = document.getElementById('tdpStartBtn');
    const countEl = document.getElementById('tdpCount');
    if(countEl) countEl.textContent = `${tutorialPickerSelected.size} selected`;
    if(startBtn) startBtn.disabled = tutorialPickerSelected.size < MIN_PICKS;
    el.querySelectorAll('.tdp-card').forEach(tile=>{
      tile.classList.toggle('selected', tutorialPickerSelected.has(tile.getAttribute('data-cardid')));
    });
  }
  el.querySelector('.tdp-list').innerHTML = pool.map(id=>{
    const d = defs[id] || {};
    return `<button type="button" class="tdp-card" data-cardid="${id}">
      <span class="tdp-ico">${d.icon||'🃏'}</span>
      <span class="tdp-name">${d.name||id}</span>
      <span class="tdp-stats">⚔️${d.attack||0} ❤️${d.health||0}${d.wait?` ⏳${d.wait}`:''}${d.cost?` 🪵${d.cost}`:''}</span>
    </button>`;
  }).join('');
  el.querySelectorAll('.tdp-card').forEach(tile=>{
    tile.addEventListener('click', ()=>{
      const id = tile.getAttribute('data-cardid');
      if(tutorialPickerSelected.has(id)) tutorialPickerSelected.delete(id); else tutorialPickerSelected.add(id);
      renderPicker();
    });
  });
  const startBtn = document.getElementById('tdpStartBtn');
  if(startBtn) startBtn.onclick = ()=>{
    if(tutorialPickerSelected.size < MIN_PICKS) return;
    el.hidden = true;
    startTutorialMatch(3, Array.from(tutorialPickerSelected));
  };
  renderPicker();
  el.hidden = false;
}
// Series-completion rewards (2026-09-23 batch #31, per explicit request: "at the end of the
// series of skirmishes, you get rewarded with a special otter or hummingbird" + "[the Cost-1
// Stone card is] a card unlocked in the first series of skirmishes"). Grants via the same
// myUnlockedCardIds mechanism Shop packs already use (see loadUnlockedCardIds's own comment) --
// additive-only, never re-locks anything, and shows up in the Codex like any other unlock.
// river-warden/sunspire-envoy/quarry-mole are new cards added to canonical/cards.json this batch
// specifically for this reward (see their flavor text for why quarry-mole is Cost 0 today rather
// than a real Stone cost -- Stone has no live payment mechanic in the engine at all right now).
// 2026-09-25: routed through unlockCardForPlayer() (see its own comment) instead of touching
// myUnlockedCardIds directly -- same net effect, now going through the one shared, logged unlock
// path every card-reward source should use going forward.
// The starter deck, handed over (2026-10-08): after the last tutorial fight the player sees the 20
// cards they've earned (plus the tutorial reward cards) and must press "Add to deck"; the cards fly
// into the deck box, and only then does the map open.
// 2026-10-15 (user: "in the 'Add to deck' screen of the tutorial part 1 ending, the cards rush into your deck. But the middle
// label is lying OVER the cards. So the cards looked like their disappeared into the label. Change the layering of that."):
// the grid scrolls (overflow:auto), so a card flying out of it was clipped at its edge, right where the label sits. Each
// flying card is now a fixed-position copy on its own top layer above the whole modal; the real tile just fades in place.
function ssFlyTile(t, br, vars){
  const r = t.getBoundingClientRect();
  const fly = t.cloneNode(true); fly.classList.add('ss-fly'); fly.setAttribute('aria-hidden', 'true');
  Object.assign(fly.style, {position:'fixed', left:r.left+'px', top:r.top+'px', width:r.width+'px', height:r.height+'px', margin:'0', zIndex:'10050', pointerEvents:'none'});
  document.body.appendChild(fly);
  gsap.set(t, {opacity:0});
  const done = vars.onComplete;
  gsap.to(fly, Object.assign({}, vars, {x: br.left + br.width/2 - (r.left + r.width/2), y: br.top + br.height/2 - (r.top + r.height/2),
    onComplete:()=>{ fly.remove(); done && done(); }}));
}
