// A full renderMatchUI() runs at the end of every resolved round. Rebuilding the control panel
// each time would yank focus out of a search box mid-word and reset its scroll — so the live
// panel node is lifted out before the rebuild and dropped back in afterwards (UX audit fix).
function testKitCaptureForRerender(m){
  if(!m || !m.testKit) return {};
  const panel = document.getElementById('testKitPanel');
  const a = document.activeElement;
  const focus = (a && panel && panel.contains(a) && a.id) ? {id:a.id, start:a.selectionStart, end:a.selectionEnd} : null;
  return {panel, focus, scroll: panel ? panel.scrollTop : 0, logScroll: (document.getElementById('battleLog')||{}).scrollTop||0};
}
function testKitRestoreFocus(keep){
  const panel = document.getElementById('testKitPanel'); if(panel) panel.scrollTop = keep.scroll||0;
  const log = document.getElementById('battleLog'); if(log) log.scrollTop = battleLogPinned ? log.scrollHeight : (keep.logScroll||0); // pinned to the newest line (2026-10-18, BP)
  if(keep.focus){ const f = document.getElementById(keep.focus.id); if(f){ f.focus({preventScroll:true}); try{ if(keep.focus.start!=null) f.setSelectionRange(keep.focus.start, keep.focus.end); }catch(e){} } }
}
function testKitArrangeLayout(root, keep){
  root.classList.add('testkit-mode');
  let panel = root.querySelector('#testKitPanel');
  if(keep && keep.panel && panel){ panel.replaceWith(keep.panel); panel = keep.panel; }
  const stage = document.createElement('div'); stage.className = 'testkit-stage';
  ['.top-play-row','.battlefield','.bottom-play-row'].forEach(sel=>{ const el = root.querySelector(':scope > '+sel); if(el) stage.appendChild(el); });
  const layout = document.createElement('div'); layout.className = 'testkit-layout';
  layout.appendChild(stage); if(panel) layout.appendChild(panel);
  root.insertBefore(layout, root.firstChild);
  const log = root.querySelector('.battle-log-panel'); if(log){ log.classList.remove('collapsed'); log.classList.add('testkit-log'); root.appendChild(log); }
}
function testKitRefreshStatus(){ const el = document.getElementById('tkStatus'); if(el && testKit) el.innerHTML = testKitStatusHTML(); }
function testKitRefreshTransport(){ const el = document.getElementById('tkTransport'); if(el && testKit){ el.innerHTML = testKitTransportHTML(); wireTestKitTransport(); } }
function testKitLogDivider(text){ pushLog({type:'tkDivider', text}); }
// Keep every scrolled box where it was across a re-render (2026-10-10, user: "Clicking on a new skill in the skill list
// ... shouldn't reset the y-scroll position. This should be a general tautology"): each scrolled element is keyed by
// its id, or by its class and position, and put back after the swap.
function scrollKeyOf(el, root){ if(el.id) return '#' + el.id; const cls = (el.className && typeof el.className === 'string') ? el.className.trim().split(/\s+/)[0] : el.tagName; const all = [...root.querySelectorAll(el.id ? '#' + el.id : '.' + cls)]; return '.' + cls + ':' + all.indexOf(el); }
function captureScrolls(root){ const out = {}; if(!root) return out; [root, ...root.querySelectorAll('*')].forEach(el=>{ if(el.scrollTop > 0 || el.scrollLeft > 0) out[el===root ? ':root' : scrollKeyOf(el, root)] = [el.scrollTop, el.scrollLeft]; }); return out; }
function restoreScrolls(root, saved){ if(!root || !saved) return; Object.entries(saved).forEach(([k, [t, l]])=>{ let el = null;
  if(k === ':root') el = root; else if(k[0] === '#') el = root.querySelector(k); else { const [cls, i] = k.slice(1).split(':'); el = root.querySelectorAll('.' + cls)[Number(i)]; }
  if(el){ el.scrollTop = t; el.scrollLeft = l; } }); }
function testKitRerenderPanel(focusId){
  const old = document.getElementById('testKitPanel'); if(!old) return;
  const saved = captureScrolls(old);
  const sel = focusId && document.getElementById(focusId); const caret = sel && sel.selectionStart;
  const tmp = document.createElement('div'); tmp.innerHTML = testKitPanelHTML();
  old.replaceWith(tmp.firstElementChild);
  wireTestKitPanel();
  const panel = document.getElementById('testKitPanel'); restoreScrolls(panel, saved);
  if(focusId){ const f = document.getElementById(focusId); if(f){ f.focus({preventScroll:true}); try{ if(caret!=null) f.setSelectionRange(caret, caret); }catch(e){} } }
}
function wireTestKitTransport(){
  const m = matchState;
  const play = document.getElementById('tkPlayBtn'); if(play) play.onclick = ()=>{ testKit.running = !testKit.running; testKitRefreshTransport(); testKitRefreshStatus(); };
  const step = document.getElementById('tkStepBtn'); if(step) step.onclick = ()=>{ if(!testKit.running) testKitPlayRound(testKit.token); };
  const reset = document.getElementById('tkResetBtn'); if(reset) reset.onclick = ()=> testKitRequestReset('Manual reset');
  document.querySelectorAll('[data-tkspeed]').forEach(b=> b.onclick = ()=>{
    testKit.speed = Number(b.getAttribute('data-tkspeed')); if(matchState) matchState.speedMult = testKit.speed; testKitSavePrefs(); testKitRefreshTransport();
  });
}
let testKitSkillDebounce = null;
function testKitSkillsChanged(){
  testKitSavePrefs();
  const cnt = document.getElementById('tkSkillCount'); if(cnt) cnt.textContent = `(${Object.keys(testKit.skills).length} on)`;
  clearTimeout(testKitSkillDebounce);
  // UX: debounce typing so "50" doesn't update twice ("5", then "50").
  // 2026-10-10 (user: "when im updating the card, just update the test card, don't reset the field. There should be an
  // upgrade vfx/sfx when you add skills and a neutral grey and neutral sfx when you remove skills"): the Test Card on
  // the board takes the new stats and skills where it stands; only a different card choice rebuilds the field.
  testKitSkillDebounce = setTimeout(()=>{ if(!testKitUpdateInPlace()) testKitRequestReset('Test card changed'); }, 450);
}
function testKitSkillKeys(){ const e = {}; testKitSkillDefs().forEach(sd=>{ if(testKit.skills[sd.key]!==undefined){ try{ sd.apply(e, testKit.skills[sd.key]); }catch(err){} } }); return Object.keys(Object.assign(e, testKit.extraEffects||{})).concat((testKit.triggers||[]).map((t, i)=> 'trigger' + i)); }
function testKitUpdateInPlace(){
  const m = matchState; if(!m || !m.testKit || !m.tkDefs || testKit.sel !== TESTKIT_CARD_ID) return false;
  const c = testKitAllCards(m, 1).find(x=> x.uid === testKit.subjectUid); if(!c) return false;
  const before = testKit.lastSkillKeys || [], oldDef = m.tkDefs[TESTKIT_CARD_ID] || {};
  testKitBuildDefs();
  const nd = testKitDefsOverlay[TESTKIT_CARD_ID]; m.tkDefs[TESTKIT_CARD_ID] = nd;
  const dA = (nd.attack||0) - (oldDef.attack||0), dH = (nd.health||0) - (oldDef.health||0);
  if(dA){ c.atk = Math.max(0, c.atk + dA); c.baseAtk = Math.max(0, (c.baseAtk||0) + dA); }
  if(dH){ c.maxHp = Math.max(1, c.maxHp + dH); c.hp = Math.max(1, Math.min(c.maxHp, c.hp + Math.max(0, dH))); }
  const after = testKitSkillKeys(); testKit.lastSkillKeys = after;
  const added = after.filter(k=> !before.includes(k)), removed = before.filter(k=> !after.includes(k));
  lastBoardSig = {1:null, 2:null}; renderBoard(); renderHUD();
  const el = boardCardEl(c.uid);
  const label = k=>{ const sd = Registry.skills().find(x=> x.key===k); return (SKILL_ICON[k] ? SKILL_ICON[k] + ' ' : '') + (sd ? sd.label : (/^trigger/.test(k) ? 'Trigger' : k)); };
  if(added.length || dA > 0 || dH > 0){ try{ SoundKit.growthSwell(); }catch(e){} if(el){ el.classList.remove('tk-upgrade','tk-downgrade'); void el.offsetWidth; el.classList.add('tk-upgrade'); setTimeout(()=> el.classList.remove('tk-upgrade'), 1100); }
    if(added.length && el) floatText(el, '+ ' + added.map(label).join(', '), 'gold stat-up'); }
  if(removed.length || dA < 0 || dH < 0){ try{ SoundKit.neutralTick(); }catch(e){} if(el){ el.classList.remove('tk-upgrade','tk-downgrade'); void el.offsetWidth; el.classList.add('tk-downgrade'); setTimeout(()=> el.classList.remove('tk-downgrade'), 1100); }
    if(removed.length && el) floatText(el, '− ' + removed.map(label).join(', '), 'tk-removed'); }
  if(dA || dH) statPillPulse(c.uid, (dA + dH) >= 0 ? 'up' : 'down', dA ? 'atk' : 'hp');
  testKitLogDivider('Test Card updated' + (added.length ? ' · +' + added.map(label).join(', ') : '') + (removed.length ? ' · −' + removed.map(label).join(', ') : ''));
  return true;
}
/* ---- Test Kit additions (2026-10-10, user: "improve the test lab UI ... so I can test EACH skill or custom trigger"
   and "let me also control combat with manual attack, do 1 damage etc buttons. Attack button makes the test card
   attack. If they have an alternate attack type or on-hit effect, it happens"). ---- */
// Skill tour: step through every skill one at a time (the Test Card gets just that one skill).
function testKitTourHTML(){
  const all = testKitSkillDefs(), i = testKit.tour, cur = i >= 0 && all[i];
  return `<div class="tk-tour"><span class="tk-tour-label">One at a time</span><button type="button" class="btn small" id="tkTourPrev" aria-label="Previous skill">◀</button><span class="tk-tour-name">${cur ? `${i+1}/${all.length} · ${escapeHtml(cur.label)}` : `${all.length} skills`}</span><button type="button" class="btn small" id="tkTourNext" aria-label="Next skill">▶</button></div>`;
}
function testKitTourGo(d){
  const all = testKitSkillDefs(); if(!all.length) return;
  testKit.tour = testKit.tour < 0 ? (d > 0 ? 0 : all.length - 1) : (testKit.tour + d + all.length) % all.length;
  const sd = all[testKit.tour]; testKit.skills = {[sd.key]: testKitSkillDefault(sd)};
  testKitRerenderPanel(); testKitSavePrefs(); testKitRequestReset(`Skill tour: ${sd.label}`);
}
// Custom triggers on the Test Card: the card editor's own trigger row (same picker, same fields, same engine data).
