    host.addEventListener('pointermove', e=>{ if(lp && Math.hypot(e.clientX - sx, e.clientY - sy) > 10){ clearTimeout(lp); lp = null; } });
    ['pointerup', 'pointercancel'].forEach(k=> host.addEventListener(k, ()=>{ clearTimeout(lp); lp = null; }));
