function renderMyDeckPanels(){
  const defs = getCardDefs();
  // Item #12: the rest of the deck-searcher toolbar (search box, Structure/Unit kind filter,
  // sort) — each optional; a missing element (e.g. a stale test harness) just no-ops that filter
  // rather than throwing, same defensive style the pre-existing `arch` read above already used.
  const searchEl = document.getElementById('deckSearch');
  const q = searchEl ? searchEl.value.trim().toLowerCase() : '';
  const kindEl = document.getElementById('deckKindFilter');
  const kind = kindEl ? kindEl.value : '';
  const cfSort = cfSortFn(deckCfState.sort, deckCfState.dir, defs); // 2026-10-21 (package TX): the bar's sort, high to low or low to high
  // Card levels (2026-10-03, explicit: "really ugly to display card levels ANYWHERE except for your
  // collection or when crafting... Also filterable for when building your deck"): hidden in the pool
  // unless this filter is on; then the pool shows level badges and keeps only cards at that level+.
  const lvlEl = document.getElementById('deckLevelFilter');
  const lvlMode = lvlEl ? lvlEl.value : '';
  const minLvl = /^\d+$/.test(lvlMode) ? +lvlMode : 0;
  // 2026-09-16 follow-up ("the number of cards is not dynamic"): the "X/20 cards" badge lives
  // in the panel-sub, which is only painted once by renderPlayerSubTab — every add/remove click
  // was refreshing the deck list/pool below it but leaving the stale count sitting above. Now
  // refreshed here too, every time the deck actually changes.
  const badgeEl = document.getElementById('myDeckSizeBadge');
  if(badgeEl) badgeEl.innerHTML = deckSizeBadgeHTML(myDeckCounts);
  try{ refreshDeckHeroBanner(); }catch(e){}
  const listEl = document.getElementById('myDeckList'); listEl.classList.add('is-stacks');
  listEl.innerHTML = Object.keys(myDeckCounts).filter(id=> myDeckCounts[id]>0 && defs[id]).sort(cfSort).map(id=>{ const n = myDeckCounts[id];
    // 2026-10-15 (user: "In the main deck editor - click = +, shift click = -"): a deck card adds a copy on click and takes one out on
    // Shift+click (or right-click); the small − corner does it with a tap on touch screens.
    // 2026-10-16: a card's Shiny / alt-art copies in the deck are their own chips (data-look), after its plain ones.
    const looks = deckLooksFor(id), plainN = n - deckLookCount(looks);
    const chip = (look, k)=> `<span class="dchip deck-stack ${look ? 'is-look' : ''}" draggable="true" data-defid="${id}" ${look ? `data-look="${escapeAttr(look)}" style="${lookStyle(id, look)}"` : ''} title="${escapeAttr(defs[id].name + (look ? ' (' + lookLabel(id, look) + ')' : ''))} ×${k}: click to add one, Shift+click to take one out">${stackHTML(cardTileHTML(defs[id], {inPlay:true, extraClass: lookTileClass(id, look), size:'full' /* 2026-10-30 (CS-A) */}), k, '×' + k)}${look ? `<span class="look-tag" aria-hidden="true">${look === 'shiny' ? '✦' : '🎨'}</span>` : ''}<button type="button" class="dchip-minus" data-minus="${id}" ${look ? `data-minus-look="${escapeAttr(look)}"` : ''} aria-label="Take one ${escapeAttr(defs[id].name)} out" title="Take one out">−</button></span>`;
    return (plainN > 0 ? chip('', plainN) : '') + Object.keys(looks).map(k=> chip(k, looks[k])).join(''); }).join('') || '<span class="empty-hint">No cards yet — add some below.</span>';
  const baseSort = cfSort;
  const sortFn = (a,b)=>{ if(lvlMode==='sort'){ const d = (myCardLevels[b]||0) - (myCardLevels[a]||0); if(d) return d; } return baseSort(a, b); };
  const allIds = (defs[HERO_ID] ? [HERO_ID] : []).concat(getDraftableIds())
    .filter(id=> cfMatch(defs[id], deckCfState)) // 2026-10-21 (package TX): the bar's filters (an eagle is a Bird)
    .filter(id=> !kind || defs[id].type===kind)
    .filter(id=> !q || defs[id].name.toLowerCase().includes(q))
    .filter(id=> !minLvl || (myCardLevels[id]||0) >= minLvl);
  document.getElementById('myDeckPool').classList.toggle('show-levels', !!lvlMode);
  // 2026-10-12 (user: "In the deck editor, don't show me cards I don't own"): only cards you have (or the basics everyone has).
  const unlockedIds = allIds.filter(id=>!defs[id].locked && ownedForDeck(id)).sort(sortFn);
  const lockedIds = allIds.filter(id=>defs[id].locked).sort(sortFn);
  document.getElementById('myDeckPool').innerHTML =
    // 2026-10-08 (user: "The locked cards shouldn't appear in the deck editor's card selector. The card
    // selector only shows cards the user literally owns"): locked cards are left out (they live in the Codex).
    (unlockedIds.map(id=>{
      return neDeckPoolStackHTML(id, defs); // 2026-10-24 (package NE): one stack per card, the copy fan, the leader counted, greyed when full (NE_DECK)
    }).join('') || '<p class="empty-hint">No cards match. Win fights and open packs to collect more.</p>') + (lockedIds.length && false ? '' : '');
  { const after = ()=>{ saveMyDeck(); renderMyDeckPanels(); };
    // 2026-10-21 (package ED, owner #10): a plain +1 / −1 rewrites the counts in place (tentQuickCount); 0 <-> 1 and split copies redraw
    const fast = id=>{ const prev = myDeckCounts[id] | 0; return ()=>{ { const p = deckCopyPicks(id), n = myDeckCounts[id] | 0; if(p.length > n) setDeckCopyPicks(id, p.slice(0, n)); } /* NE: picks never outnumber the copies */ saveMyDeck(); if(!tentQuickCount(id, prev)) renderMyDeckPanels(); }; };
    // 2026-10-16: a click on a look (a Shiny / alt-art chip or pool stack) adds or takes out that copy; plain ones work as before.
    const lookClick = (e, id, look)=>{
      const remove = !!e.shiftKey, cur = deckLooksFor(id);
      if(remove){ if(!(cur[look] > 0)) return; deckCardClick({shiftKey:true}, id, myDeckCounts, '#myDeckPool', '#myDeckList', ()=>{ setDeckLook(id, look, -1); after(); }, true); return; }
      const st = lookStock(id), have = look === 'shiny' ? st.shiny : (st.skins[look.slice(5)] ? 1 : 0), used = myDeckCounts[id] | 0;
      const plainRoom = st.plain === Infinity ? Infinity : st.plain - (used - deckLookCount(cur)) - Object.keys(cur).filter(k=> k.startsWith('skin:')).length;
      if((cur[look] | 0) >= have || (look !== 'shiny' && plainRoom <= 0)){ const el = document.querySelector(`#myDeckPool .look-stack[data-look="${cssEsc(look)}"][data-lookid="${cssEsc(id)}"]`); denyShake(el); if(el) floatText(el, look === 'shiny' ? _t('All in your deck') : _t('No plain copy left to dress'), 'debuff'); return; }
      deckCardClick({}, id, myDeckCounts, '#myDeckPool', '#myDeckList', ()=>{ setDeckLook(id, look, +1); after(); }, true);
    };
    // 2026-10-24 (package NE): the copy fan adds exactly the copy clicked (a pick), a Shiny one with its look
    neLookClick = lookClick;
    neFanAddCopy = (id, uid, btn)=>{ const c = copyByUid(id, uid); if(!c) return;
      if(neDeckFull(id)){ denyShake(btn); floatText(btn, id === myLeaderId ? '👑 ' + _t('Your leader') : _t('Max {n} per deck', {n: maxCopiesForRarity((getCardDefs()[id] || {}).rarity)}), 'debuff'); return; }
      deckCardClick({}, id, myDeckCounts, '#myDeckPool', '#myDeckList', ()=>{ const p = deckCopyPicks(id).filter(u=> u !== uid); p.push(uid); setDeckCopyPicks(id, p.slice(-(myDeckCounts[id] | 0)));
        if(c.shiny){ const lk = deckLooksFor(id); if((lk.shiny | 0) < (myDeckCounts[id] | 0)) setDeckLook(id, 'shiny', +1); } after(); }, true); };
    document.querySelectorAll('#myDeckList .dchip').forEach(el=>{ const id = el.getAttribute('data-defid'), look = el.getAttribute('data-look');
      el.addEventListener('click', e=>{ if(e.target.closest('.dchip-minus')){ e.stopPropagation(); if(look) lookClick({shiftKey:true}, id, look); else deckCardClick({shiftKey:true}, id, myDeckCounts, '#myDeckPool', '#myDeckList', fast(id), true); return; } if(look) lookClick(e, id, look); else deckCardClick(e, id, myDeckCounts, '#myDeckPool', '#myDeckList', fast(id), true); });
      el.addEventListener('contextmenu', e=>{ e.preventDefault(); if(look) lookClick({shiftKey:true}, id, look); else deckCardClick({shiftKey:true}, id, myDeckCounts, '#myDeckPool', '#myDeckList', fast(id), true); }); });
    document.querySelectorAll('#myDeckPool .look-stack').forEach(el=>{ const id = el.dataset.lookid, look = el.dataset.look; const t = el.querySelector('.card-tile'); if(t) t.classList.add('is-look-tile');
      el.addEventListener('click', e=>{ e.stopPropagation(); lookClick(e, id, look); }, true);
      el.addEventListener('contextmenu', e=>{ e.preventDefault(); e.stopPropagation(); lookClick({shiftKey:true}, id, look); }, true); });
    document.querySelectorAll('#myDeckPool .card-tile:not(.locked)').forEach(el=>{ el.title = (el.title ? el.title + ' · ' : '') + 'Click: add one · Shift+click: take one out';
      el.addEventListener('contextmenu', e=>{ const id = el.getAttribute('data-defid'); if(!(myDeckCounts[id] > 0)) return; e.preventDefault(); deckCardClick({shiftKey:true}, id, myDeckCounts, '#myDeckPool', '#myDeckList', fast(id), true); }); });
  // only unlocked tiles are clickable — locked ones sit there, grayed out, as a preview
  // `true` here (and on the chip handler above) turns on the real deck's rarity copy-limit
  // enforcement -- see deckCardClick's own comment. The Sandbox tool's identical-looking listeners
  // below (renderSimPools) deliberately omit this argument.
  // 2026-10-23 (package PG): this listener now sits inside the block that defines fast(); since package ED (10-21) it sat outside it, so a
  // click on a pool card threw "fast is not defined" and added nothing (owner 10-23 01:03 item 7: "clicking the card in the tent's deck
  // editor should add the card in - not just drag and drop").
  document.querySelectorAll('#myDeckPool .card-tile:not(.locked):not(.is-look-tile)').forEach(el=> el.addEventListener('click', (e)=>{ const id=el.getAttribute('data-defid');
    // 2026-10-16: a plain tile takes a plain copy. When every plain copy is in (only a Shiny / alt-art look is left), say so.
    // 2026-10-24 (package NE): the one stack adds your best copy not in the deck (deckCopyUidsFor); the "every plain copy is in" refusal went
    deckCardClick(e, id, myDeckCounts, '#myDeckPool', '#myDeckList', fast(id), true); })); } // 2026-10-21 (package ED): count-only
  // Item #10: both the pool tiles and the deck-list chips can be dragged (2026-10-18: onto #myDeckList; the leader slot they were
  // also dropped on is gone, the leader is picked in openLoadoutPicker) — a locked pool
  // tile is deliberately excluded, matching the same "not usable yet" rule the click-to-add
  // handlers above already apply.
  document.querySelectorAll('#myDeckList .dchip, #myDeckPool .card-tile:not(.locked)').forEach(el=>{
    el.setAttribute('draggable', 'true');
    el.addEventListener('dragstart', e=> e.dataTransfer.setData('text/plain', el.getAttribute('data-defid')));
  });
  wireCardTileFlourish(document.getElementById('myDeckPool'));
  { const pool = document.getElementById('myDeckPool'); if(pool){ pool.classList.toggle('ne-show-limits', !!neShowLimits); neWirePoolFan(pool); } neFanRefresh(); } // 2026-10-24 (package NE)
}
// Card hover flourish wiring (2026-09-20) — the tilt half of the same request
// wireHomeMenuFlourish already covers for the home menu buttons: on mousemove, sets --ctTiltX/
// --ctTiltY (read by .card-tile-magnetic's transform in arena_template.html) from the cursor's
// position within the tile, tipping the nearest edge toward the viewer (same sign convention as
// wireHomeMenuFlourish — see its own comment for why); on mouseleave, eases both back to 0deg via
// that same rule's CSS transition, so the tile settles back to flat with no extra animation logic
// needed here. The shimmer sweep itself is pure CSS (:hover-gated, see .card-tile-magnetic:hover
// ::after) and needs no JS at all — only the tilt does. Safe to call repeatedly on a freshly
// rendered container (renderMyDeckPanels replaces #myDeckPool's innerHTML on every add/remove/
// filter change) since it only ever wires the CURRENT set of .card-tile-magnetic elements found
// under `root`; the old, now-detached elements and their listeners are simply garbage collected.
function wireCardTileFlourish(root){
  if(!root) return;
  const maxTilt = 7;
  root.querySelectorAll('.card-tile-magnetic').forEach(el=>{
    el.addEventListener('mousemove', (e)=>{
      const r = el.getBoundingClientRect();
      const nx = ((e.clientX - r.left) / r.width) * 2 - 1;
      const ny = ((e.clientY - r.top) / r.height) * 2 - 1;
      el.style.setProperty('--ctTiltY', (-nx * maxTilt).toFixed(2) + 'deg');
      el.style.setProperty('--ctTiltX', (ny * maxTilt).toFixed(2) + 'deg');
    });
    el.addEventListener('mouseleave', ()=>{
      el.style.setProperty('--ctTiltX', '0deg');
      el.style.setProperty('--ctTiltY', '0deg');
    });
  });
}

// mode: 'ai' (default — a computer opponent takes player 2, acting the instant you do) or
// 'pc' (local hot-seat pass-and-play — a second human takes player 2, alternating turns with
// a "pass the device" beat between them; see activePlayerId/afterPlayerAction).
// One deck-size gate shared by every mode that fights with your own deck (Conquest and Raid used
// to skip it, so a 21-card deck could start a Conquest fight — found in the 2026-10-03 story pass).
function deckSizeOkOrWarn(){
  if(typeof restoreMainDeck==='function' && currentTab!=='deck') restoreMainDeck();
  // 2026-10-23 (package PG): + the copy limits (rarity: Common 5 … Very Rare 2, higher 1; and the copies you own), named card by card
  if(deckTotal(myDeckCounts)===DECK_SIZE){ const cp = deckCopyProblem(myDeckCounts); if(cp){ showToast(deckCopyProblemText(cp), 'warn'); try{ SoundKit.deny && SoundKit.deny(); }catch(e){} return false; }
    return deckRankOkOrWarn(myDeckCounts, deckLeaderIds()); } // + the Legendary / Mythic / higher deck caps (2026-10-22, package DR)
  showToast(TX('toast.your-main-deck-has-cards-it-3', {v1: deckTotal(myDeckCounts), DECK_SIZE}), 'warn');
  return false;
}
