      [['.atk', Math.max(0, (d.attack|0) - (hc.consterned|0))], ['.hp', Math.max(1, (d.health|0) - (hc.consterned|0))]].forEach(([sel, v])=>{ const sp = el.querySelector('.stats ' + sel), n = sp && sp.querySelector('.sim-stat'); if(n){ n.replaceWith(document.createTextNode(String(v))); sp.removeAttribute('title'); } });
