  ov.querySelector('.sr-ok').onclick = close; ov.addEventListener('pointerdown', e=>{ if(e.target === ov) close(); });
  setTimeout(()=>{ try{ ov.querySelector('.sr-ok').focus(); }catch(e){} }, 60);
