  const el = document.createElement('div'); el.className = 'grave-peek' + (mine ? ' is-mine' : ' is-theirs'); el.dataset.pid = String(pid);
  el.setAttribute('role', 'dialog'); el.setAttribute('aria-label', (mine ? 'Your' : 'Enemy') + ' Graveyard');
