  try{ ribbonShieldSync(side, shOverride); }catch(e){}
  const hq = m.players[side==='A' ? 1 : 2].hq, el = hqTileEl(side); if(!el || !hq) return;
  const tile = el.classList.contains('card-tile') ? el : el.querySelector('.card-tile'); if(!tile) return;
