function currentCardByUid(uid){
  const m = matchState; if(!m) return null;
  // Replay snapshot (2026-09-16, items #8/#9 — "HP not updating on every hit" / "a killed
  // card's poison counters don't display"): resolveCombat() runs the WHOLE round
  // synchronously before any of it is animated, so by the time an event from partway
  // through the round gets replayed here, the live board already reflects the round's
  // FINAL state — and a card that died this round has already been spliced out of
  // pl.row entirely, so a plain live-board search can never find it again. m.replayCards
  // is a per-round snapshot captured at round start (see resolveRound) and then updated in
  // lockstep with each event as renderVfxForEvent plays it back, so HP/status badges show
  // the correct value AT THAT POINT in the replay for every card — survivors and cards
  // that are about to die alike — not just whichever cards happen to still be standing
  // once the whole round is already over.
  if(m.replayCards && m.replayCards[uid]) return m.replayCards[uid];
  for(const pid of [1,2]){
    const pl = m.players[pid];
    for(const side of ['left','center','right']){
      const c = pl.row[side].find(x=>x.uid===uid);
      if(c) return c;
    }
  }
  return null;
}
// Attack amplification (2026-10-11, user: "The enhanced stats shouldn't be blue ... thresholds for how to amplify the
// attack label ... 1.5x, 2x, 2.5x etc. redder and more glowy"): a buffed attack stays red and heats up in steps.
function atkAmpTier(eff, base){
  base = Number(base)||0; eff = Number(eff)||0; if(eff <= base) return 0;
  const r = base > 0 ? eff / base : 1 + eff / 2;
  return r >= 3 ? 4 : r >= 2.5 ? 3 : r >= 2 ? 2 : r >= 1.5 ? 1 : 0.5;
}
