    gsap.to(p, {x:`+=${-dir*(20 + Math.random()*20)}`, y:`+=${55 + Math.random()*35}`, rotation:`+=${-dir*140}`, opacity:0, duration:1.1, delay:.33, ease:'sine.inOut', onComplete:()=> p.remove()});
