    if(el.matches('.falling, .burning, .bleeding, .is-entering')) return;
    const r = el.getBoundingClientRect(); if(r.width > 4) out.set(String(el.getAttribute('data-uid')), {left:r.left, top:r.top, width:r.width, height:r.height});
