  rowIds.forEach(id=>{ const row = document.getElementById(id); if(!row) return;
    row.querySelectorAll('.board-card[data-uid]').forEach(el=>{ const f = fromRects.get(el.getAttribute('data-uid')); if(f && !el.classList.contains('is-entering')) els.push([el, f]); }); });
  if(!els.length) return;
