// Click = add a copy, Shift+Click = deduct one — applies the same way whether the click
// lands on a pool tile or on an existing deck chip (2026-09-14; previously pool-click=add
// and chip-click=remove were two different gestures). Animates a small flight between the
// pool tile and the deck's mini chip list in whichever direction the change actually went.
function deckCardClick(e, id, counts, poolSel, deckListSel, onChange, enforceRarityLimit){
  const remove = !!e.shiftKey;
  if(remove && (counts[id]||0)<=0) return;
  const poolTileEl = document.querySelector(`${poolSel} [data-defid="${id}"]`);
  const chipEl = document.querySelector(`${deckListSel} [data-defid="${id}"]`);
  const deckListEl = document.querySelector(deckListSel);
  // Rarity copy-limit enforcement (2026-09-30): only ever passed `true` from the real Deck
  // builder's own pool/chip click handlers -- the Sandbox/Myriad test-deck tool (which reuses this
  // same function) deliberately allows stacking unlimited copies of anything to test interactions,
  // so it never passes this flag and stays uncapped.
  if(!remove && enforceRarityLimit){
    // 2026-10-12 (user: "If I used a card as my leader, i can't use it in my deck. Likewise vice versa").
    if(id === myLeaderId){ const el = poolTileEl || chipEl; denyShake(el); if(el) floatText(el, '👑 Your leader', 'debuff'); return; }
    const owned = ownedCopiesOf(id);
    if(owned !== Infinity && (counts[id]||0) >= owned){ const el = poolTileEl || chipEl; denyShake(el); if(el) floatText(el, _t('You own {n}', {n:owned}), 'debuff'); return; }
    const def = getCardDefs()[id];
    if(def && editionCapReached(counts, id, getCardDefs())){
      const el = poolTileEl || chipEl;
      denyShake(el); if(el) floatText(el, _t('Max {n} per deck', {n:maxCopiesForRarity(def.rarity)}), 'debuff');
      try{ fxHook('deckFull', el); }catch(e){} // 2026-10-15 batch F
      try{ vis4CapTip(id, counts, deckListSel); }catch(e){} // 2026-10-27 (package VIS4, K16)
      return;
    }
    { const rb = deckRankBlockFor(counts, id, getCardDefs(), deckLeaderIds()); // 2026-10-22 (package DR): Legendary 3 / Mythic 2 / higher 1 per deck, the leader counted
      if(rb){ const el = poolTileEl || chipEl; denyShake(el); if(el) floatText(el, deckRankLimitText(rb), 'debuff'); try{ fxHook('deckFull', el); }catch(e){} return; } }
  }
  const fromRect = (remove ? chipEl : poolTileEl) ? (remove ? chipEl : poolTileEl).getBoundingClientRect() : null;
  const toRectFallback = remove ? (poolTileEl && poolTileEl.getBoundingClientRect()) : ((chipEl||deckListEl) && (chipEl||deckListEl).getBoundingClientRect());
  counts[id] = Math.max(0, (counts[id]||0) + (remove?-1:1));
  onChange();
  if(fromRect && toRectFallback){
    const defs = getCardDefs();
    flyBetweenRects(fromRect, toRectFallback, (defs[id]&&defs[id].icon)||'🌰');
  }
  try{ fxHook('deckCardMoved', id, remove, poolSel, deckListSel); }catch(e){} // 2026-10-15 batch F: add / remove moment
  if(!remove && enforceRarityLimit) try{ vis4CapTip(id, counts, deckListSel); }catch(e){} // 2026-10-27 (package VIS4, K16)
}
// 2026-10-27 (package VIS4, K16; owner 10-27 11:22: "Tutorial when going over card cap (5/5) then one for higher rarities (3/3)"): the first
// time a card in your deck reaches its rarity's copy cap (by a click, a drop, or a click past it), a one-line coach tip says so; a card whose
// cap is below a Common's (Uncommon 4, Rare 3 ...) has its own tip, also once. Only the rarity cap counts (not "you own 2").
