  const defs = getCardDefs();
  if(ev.type==='play' && !ev.reserve){ const rc = matchState && matchState.replayCards && matchState.replayCards[ev.uid]; hp = (rc && rc.maxHp) || ((defs[ev.defId]||{}).health) || 0; }
