  if(ev.type === 'dive' && ev.strike) return {cls:'', text: ev.targetDefId ? TX('ui.eq2-log-dive', {unit: nm(ev.attDefId), target: nm(ev.targetDefId), n: ev.bonus}) : TX('ui.en7-log-strike-none', {unit: nm(ev.attDefId), n: ev.bonus})};
