const W2_BROKE_NAME = {armor:'Armor', flying:'Flying', swimmer:'Swimmer', burrow:'Burrow', trigger:'a trigger'};
function w2BrokeName(k){ if(!k) return ''; if(W2_BROKE_NAME[k]) return W2_BROKE_NAME[k]; const pd = PASSIVE_DEFS.find(p=> p.key === k); return pd ? pd.label : k; }
// ==== Field effects 2 (2026-10-16): battle-log lines and looks for the new field effects (rules in bramblewood-engine.js,
// fieldEffects2Tick). Hazards log one header line, then one line per unit they hurt.
const FIELD2_OWN_TICKS = new Set(['landslide', 'landslideHit', 'crushingDepths', 'crushingHit', 'hail', 'hailHit', 'glassStorm', 'glassHit', 'lavaSpout', 'lavaSpoutHit', 'leylines', 'leylinesHit', 'leylinesCastle', 'consternation', 'mirage', 'haunted',
  'sulphurFumes', 'ashRain', 'ashRainCastle', 'ashy', 'arrowSlits', 'arrowSlitHit', 'awash', 'volley', 'volleyHit', 'volleyCastle']); // + the raid's back-row volley (2026-10-17) // + field effects 3 (2026-10-17), + Awash (2026-10-17)
const FIELD2_HIT = {landslideHit:['🪨', 'rocks'], crushingHit:['🫧', 'the crushing depths'], hailHit:['🌨️', 'the hail'], glassHit:['💎', 'flying glass'], lavaSpoutHit:['♨️', 'the lava spout'], leylinesHit:['✴️', 'the ley lines'], arrowSlitHit:['🏹', 'an arrow from the walls']};
function field2LogText(ev, nm){
  const who = s=> s === 'A' ? 'your' : "the enemy's";
  if(ev.type === 'fieldTick'){
    const h = FIELD2_HIT[ev.field];
    if(h) return ev.atheist ? {cls:'', text:`✴️ ${nm(ev.defId)} doesn't believe in ley lines: no damage.`} : {cls:'', text:`${h[0]} ${nm(ev.defId)} takes ${dnLogNum(ev.dmg, ev)} from ${h[1]}${ev.roll ? ` (${ev.roll})` : ''}${ev.swimmer ? ' (it swims: half)' : ''}.`};
    switch(ev.field){
      case 'landslide': return {cls:'', text:`🪨 Landslide! Rocks come down on three neighbouring columns: ${ev.amount} damage to every unit there that isn't flying.`}; // 2026-10-17
      case 'crushingDepths': return {cls:'', text:`🫧 The depths press down: ${ev.amount} water damage to every unit (Swimmers take half).`};
      case 'hail': return {cls:'', text:`🌨️ Hail: ${ev.amount} ice damage to every unit.`};
      case 'glassStorm': return {cls:'', text:'💎 The glass-storm buffets every unit (1 each).'}; // 2026-10-22 (package FX)
      case 'lavaSpout': return {cls:'', text:`♨️ Lava bursts up through a column (${ev.amount} fire damage).`};
      case 'leylines': return {cls:'', text:'✴️ The ley lines burn: 1 magic damage to every unit and to both brambles.'}; // 2026-10-22 (package FX)
      case 'leylinesCastle': return {cls:'', text:`✴️ The ley lines burn ${who(ev.side)} bramble: −${ev.dmg}.`};
      case 'consternation': return {cls:'', text:`😰 Consternation: ${ev.count} card${ev.count === 1 ? '' : 's'} in ${who(ev.side)} hand lose ${ev.amount}/${ev.amount}.`};
      case 'mirage': return {cls:'', text: ev.none ? `🪞 A mirage flickers by ${nm(ev.defId)}, but there's no room for it.` : `🪞 A mirage: an Illusion of ${nm(ev.defId)} appears beside it (1/1).`};
      case 'haunted': return {cls:'', text:'👻 Something stirs in the haunted air…'};
      // Field effects 3 (2026-10-17)
      case 'sulphurFumes': return {cls:'', text: ev.count ? `💨 Sulphur fumes roll off the vents: ${ev.count} unit${ev.count === 1 ? '' : 's'} choke (−${ev.amount} Attack this round).` : '💨 Sulphur fumes roll off the vents, but nobody breathes them in.'};
      case 'ashRain': return {cls:'', text:`🌋 Ash rains down: both brambles take ${ev.amount}, and the sun dims.`};
      case 'ashRainCastle': return {cls:'', text:`🌋 Ash settles on ${who(ev.side)} bramble: −${ev.dmg}.`};
      case 'ashy': return {cls:'', text:'🌫️ The eruption leaves the ground Ashy: flyers are grounded and the air is thick (4 rounds).'};
      case 'arrowSlits': return {cls:'', text: ev.none ? '🏹 An arrow from the walls thuds into empty ground.' : `🏹 The walls loose an arrow at ${nm(ev.defId)}.`};
      case 'awash': return {cls:'', text: ev.none ? '〰️ The water swirls over an empty field.' : `〰️ Wave ${ev.n}: the water takes ${nm(ev.defId)}.`}; // 2026-10-17; "Wave" on screen since 2026-10-18 (Awash and Wave are one)
      // The raid's back rows (2026-10-17)
      case 'volley': return {cls:'gold', text: ev.side === 'A' ? '🏹 Your allies\u2019 rows strike from behind the line.' : '🏹 The enemy\u2019s back rows strike.'};
      case 'volleyHit': return {cls:'', text:`🏹 ${nm(ev.fromDefId)} (${ev.row === 2 ? 'back' : 'middle'} row) hits ${nm(ev.defId)} for ${dnLogNum(ev.dmg, ev)}.`};
      case 'volleyCastle': return {cls:'', text:`🏹 ${nm(ev.fromDefId)} (${ev.row === 2 ? 'back' : 'middle'} row) hits ${ev.side === 'B' ? 'the enemy' : 'your'} bramble for ${dnLogNum(ev.dmg, ev)}${ev.shielded ? ' (shielded)' : ''}.`};
    }
    return null;
  }
  if(ev.type === 'statusFx' && ev.kind === 'choking') return {cls:'', text:`💨 ${nm(ev.targetDefId)} is Choking: −${ev.amount} Attack this round.`}; // 2026-10-17
  if(ev.type === 'evaded' && ev.reason === 'ashy') return {cls:'', text:`🌫️ ${nm(ev.attDefId)} loses ${nm(ev.targetDefId)} in the ash and misses.`}; // 2026-10-17
  if((ev.type === 'lumber' || ev.type === 'stone') && ev.leylines) return {cls:'gold', text:`✴️ The ley lines: ${ev.side === 'A' ? 'you gain' : 'the enemy gains'} ${ev.amount} ${ev.type === 'stone' ? 'Stone 🪨' : 'Lumber 🪵'}.`};
  if(ev.type === 'statusFx' && ev.kind === 'frightened') return {cls:'', text:`👻 ${nm(ev.targetDefId)} is Frightened: it won't attack this round.`};
  if(ev.type === 'slipFizzle') return {cls:'', text:`⛸️ ${nm(ev.defId)} slips: its skill fails.`};
  if(ev.type === 'evaded' && ev.reason === 'slippery') return {cls:'', text:`⛸️ ${nm(ev.attDefId)} slips on the ice and misses ${nm(ev.targetDefId)}.`};
  if(ev.type === 'evaded' && ev.reason === 'canopy') return {cls:'', text:`🌳 ${nm(ev.targetDefId)} darts through the branches: ${nm(ev.attDefId)} misses.`};
  if(ev.type === 'skipTurn' && ev.reason === 'frightened') return {cls:'', text:`${nm(ev.defId)} is too frightened to attack. 👻`};
  if(ev.type === 'play' && ev.consterned > 0) return {cls:'', text:`${sideLabel(ev.side)} played ${nm(ev.defId)} (😰 −${ev.consterned}/−${ev.consterned} from Consternation).`};
  if(ev.type === 'spawn' && ev.kind === 'mirage') return {cls:'', text:`🪞 ${nm(ev.defId)} shimmers into being.`};
  if(ev.type === 'bloom' && ev.parasite) return {cls:'poison', text: TX('ui.en7-log-para-bloom', {unit: nm(ev.defId), target: nm(ev.targetDefId)})}; // EN7 (2026-10-24)
  if(ev.type === 'bloom' && ev.failed) return {cls:'', text: TX('ui.eng9-bloom-fail-log', {name: nm(ev.defId)})}; // ENG9 (2026-10-26, EN7-2)
  if(ev.type === 'bloom') return {cls:'', text: TX(ev.lumber ? 'ui.bl-log-lumber' : 'ui.bl-log', {name: nm(ev.defId), n: ev.lumber||0})}; // BL (2026-10-23)
  if(ev.type === 'reviveGrave') return {cls:'gold', text: TX('ui.eng9-log-revive-grave', {name: nm(ev.defId)})}; // ENG9 (2026-10-26): Revive N
  if(ev.type === 'skillSpent') return {cls:'', text: TX('ui.eng9-log-spent', {name: nm(ev.defId)})}; // ENG9 (2026-10-26, G23 / G24)
  if(ev.type === 'spawn' && ev.kind === 'bloom') return {cls:'', text: ''};
  return null;
}
function field2Vfx(ev){
  if(!ev || !matchState) return; const m = matchState, F = window.SkillFX, bf = document.getElementById('battlefieldEl');
  const fx = lvl=> !reducedMotion() && fxAtLeast(lvl || 'low');
  const fl = (el, txt, cls)=>{ if(el) try{ floatText(el, txt, cls); }catch(e){} };
  const snd = k=>{ try{ SoundKit[k] && SoundKit[k](); }catch(e){} };
  const rcOf = u=> m.replayCards && u != null ? m.replayCards[u] : null;
  const at = el=>{ const r = el.getBoundingClientRect(); return {x:r.left + r.width/2, y:r.top + r.height/2}; };
  if(ev.type === 'fieldTick'){
    const h = FIELD2_HIT[ev.field];
    if(h){ const el = boardCardEl(ev.uid), rc = rcOf(ev.uid); if(rc && ev.dmg > 0) rc.hp = Math.max(0, (rc.hp||0) - ev.dmg); try{ updateCardHpDisplay(ev.uid); }catch(e){}
      if(!el) return; if(ev.atheist){ fl(el, '✴️ Atheist', 'quick'); return; }
      try{ dnFloat(el, ev.dmg, {type: ev.dmgType || (ev.field === 'lavaSpoutHit' ? 'heat' : null), mods: ev.mods}); }catch(e){} try{ shakeEl(el); }catch(e){} /* DN2 */
      if(!F || !fx()) return; const c = at(el);
      if(ev.field === 'hailHit' && F.burst) F.burst(c.x, c.y - 20, 270, 'ice', 6);
      else if(ev.field === 'glassHit' && F.burst) F.burst(c.x, c.y, Math.random()*360, 'zap', 5);
      else if(ev.field === 'landslideHit' && F.burst) F.burst(c.x, c.y - 24, 270, 'wood', 7);
      else if(ev.field === 'crushingHit' && F.ring) F.ring(c.x, c.y, 'sfx-water', 110, 520);
      else if(ev.field === 'lavaSpoutHit'){ try{ eruptionGeyserVfx(el); }catch(e){} }
      else if(ev.field === 'leylinesHit' && F.ring) F.ring(c.x, c.y, 'sfx-violet', 90, 480);
      return; }
    switch(ev.field){
      // 2026-10-17 (user: "Landslide's effect is too much. it should only affect the L/C/R cards, and the vfx should only land on those."): the
      // rocks (FX.A.landslide) fall only on the units the header names (ev.uids: the three struck columns), no whole-board band or rumble.
      case 'landslide': snd('boom'); if(fx()){ const cards = (ev.uids || []).map(u=> boardCardEl(u)).filter(Boolean);
        if(cards.length && window.FX && FX.A && FX.A.landslide) try{ FX.A.landslide(cards, {host:bf}); }catch(e){} } break;
      case 'crushingDepths': snd('splash'); if(bf && fx()){ bf.classList.remove('crush-press'); void bf.offsetWidth; bf.classList.add('crush-press'); setTimeout(()=> bf.classList.remove('crush-press'), 900); } break;
      case 'hail': snd('freezeChime'); if(fx()) boardSweepVfx('hail', 'A'); break;
      case 'glassStorm': snd('swipeTone'); if(fx()) boardSweepVfx('glass', Math.random() < .5 ? 'A' : 'B'); break;
      case 'leylines': snd('curse'); if(fx()) boardSweepVfx('leylines', 'A'); break;
      case 'lavaSpout': snd('boom'); break;
      case 'consternation': if(ev.side === 'A'){ const hs = document.getElementById('handStrip'); fl(hs, `😰 −${ev.amount}/−${ev.amount}`, 'debuff'); try{ renderHand(); }catch(e){} } break;
      // Field effects 3 (2026-10-17): fumes a soft yellow sweep, ash the hail's sweep in grey, the walls' arrow a float on the target.
      case 'sulphurFumes': snd('swipeTone'); if(fx()) boardSweepVfx('glass', 'B'); break;
      case 'ashRain': snd('boom'); if(fx()) boardSweepVfx('hail', 'A'); break;
      case 'ashy': snd('boom'); if(bf && fx()){ bf.classList.remove('erupt-rumble'); void bf.offsetWidth; bf.classList.add('erupt-rumble'); setTimeout(()=> bf.classList.remove('erupt-rumble'), 700); } break;
      case 'arrowSlits': if(!ev.none) snd('swipeTone'); break;
      case 'awash': if(!ev.none){ const el = boardCardEl(ev.uid); fl(el, `〰️ Wave ${ev.n}`, 'quick'); } break; // 2026-10-17: the ride itself is the wave event that follows (2026-10-18: "Wave", not "Awash")
      // The raid's back-row volley (2026-10-17): the striker bobs forward, the struck card (or castle) shows the number.
      // 2026-10-19 (package RV2, owner 08:42: "It should look like the columns all attack for real"): a real attack now (raidStrikeVfx):
      // the lunge toward its target, then the impact (number, shake, squash, sound) as the blow lands, Health stepping down with it.
      case 'volleyHit': case 'volleyCastle': { raidStrikeVfx(ev); break; }
      case 'mirage': if(ev.illusionUid != null) setTimeout(()=>{ const el = boardCardEl(ev.illusionUid); if(!el) return; el.classList.add('mirage-shimmer'); fl(el, '🪞 Illusion', 'quick'); setTimeout(()=> el.classList.remove('mirage-shimmer'), 1200); }, 420); break;
    }
    return;
  }
  if(ev.type === 'statusFx' && ev.kind === 'frightened'){ const el = boardCardEl(ev.targetUid), rc = rcOf(ev.targetUid); if(rc) rc.frightRound = (m.engine && m.engine.turnNo) ? m.engine.turnNo() : rc.frightRound;
    fl(el, '👻 Frightened', 'debuff'); if(el && F && F.fearShiver && fx()) F.fearShiver(el); try{ updateCardStatusDisplay(ev.targetUid); }catch(e){} return; }
  if(ev.type === 'slipFizzle'){ fl(boardCardEl(ev.uid), '⛸️ Slipped', 'quick'); return; }
  if(ev.type === 'statusFx' && ev.kind === 'choking'){ fl(boardCardEl(ev.targetUid), `💨 −${ev.amount}`, 'debuff'); return; } // Sulphur Fumes (2026-10-17)
  if(ev.type === 'evaded' && ev.reason === 'ashy'){ fl(boardCardEl(ev.attUid), '🌫️ Lost in ash', 'quick'); return; } // Ashy (2026-10-17)
  if(ev.type === 'evaded' && ev.reason === 'slippery'){ fl(boardCardEl(ev.attUid), '⛸️ Slip!', 'quick'); return; }
  if(ev.type === 'hit' && (ev.laneBonus > 0 || ev.tallGrass)){ const el = boardCardEl(ev.targetUid); const fr = matchFieldRules(m) || {};
    const t = ev.tallGrass ? '🌾 ×2' : ''; const ln = ev.laneBonus > 0 ? `${ev.lane === 'bishop' ? '♝' : ev.lane === 'rook' ? '♜' : (fr.bishopPath ? '♝' : '♜')} +${ev.laneBonus}` : '';
    setTimeout(()=> fl(el, [ln, t].filter(Boolean).join(' '), 'quick'), 160); return; }
}
