    const fld = ev.kind === 'sk2Scavenge' ? 'sk2Scavenge' : ev.kind === 'sk2Salvage' ? 'sk2Salvage' : 'sk2Berries', u = ev.attUid, rc = rcOf(u); if(rc) rc[fld] = ev.total || 0;
