  if(ev.kind === 'arson'){ fl(hqTileEl(ev.targetSide), `🔥 −${ev.amount}🪵`, 'debuff'); snd('curse'); return; }
  if(ev.kind === 'fortify'){ fl(el, '🏯', 'quick'); return; }
