    const regenSelf = !!(el && ev.attUid != null && String(ev.attUid) === String(ev.targetUid) && ((getCardDefs()[ev.attDefId]||{}).effects||{}).regen
      && window.SkillFX && SkillFX.regen && fxAtLeast('med') && !reducedMotion() && skillFxOnce('regen' + ev.targetUid));
