  { let g = null; try{ g = c && c.uid && typeof socketGemByUid === 'function' ? socketGemByUid(c.uid) : null; }catch(e){} const k = g && socketKind(g); if(k) parts.push(k.icon + ' ' + TX('ui.h1-gem-' + k.id)); } // 2026-10-24 (package H1): its socketed gem
