  if(p.paysTo > p.level) return TX('ui.fg-fuse-pays', {from: p.level, to: p.paysTo}) + (p.paysTo < 10 && p.nextPct > 0 ? ' · ' + TX('ui.fg-fuse-part', {pct: Math.round(p.nextPct * 100), next: p.paysTo + 1}) : '');
