  const back = `<span class="fr-back bw-back bk-unit" role="img" aria-label="${escapeAttr(TX('ui.rc-forge-unknown'))}"><b aria-hidden="true">?</b></span>`;
  const look = seen ? bestCopyClass(id, d) : '', foil = /is-holo|is-shiny/.test(look);
