// FORGE_FG:END

// Promotion (2026-10-09, user: "some cards can be promoted - this changes the card to another card.
// For now, we can try basic ant as an example. And it can become Ant Warrior or 2 other Ant cards.
// (Their rarities usually start as uncommon or below)"). A card lists `promotesTo` (its choices) and
// `promoteAt` (the level it must reach). Promoting unlocks the chosen card, turns every copy of the
// old card in your decks into it, and sends the old card back to level 0 — so you can raise it again
// later and take one of the other paths.
const PROMOTE_COST = {gold:300, dust:100}; // ×5 with the forge economy v2 income (2026-10-11)
let forgePromotePick = null;
function promotionTargets(id){ const d = getCardDefs()[id], defs = getCardDefs(); return d && Array.isArray(d.promotesTo) ? d.promotesTo.filter(t=> defs[t]) : []; }
// 2026-10-23 (package TU2, owner E10: "No. Combining or converting cards to different cards is a concept we havent explored. HOWEVER,
// please prepare this tab. This is not a subtap - it will be its own feature page!"): Promotion leaves the Forge's card panel for its
// own page (renderPromotionPage, tab 'promotion'), which says plainly that it is not built yet. A card that lists promotesTo shows a
// pointer to that page here instead of the Promote controls; forgePromote and its data stay in the code, unused, for the real page.
const PROMOTION_PAGE_LIVE = false;
function forgePromotionHTML(id, sel, L){
  const targets = promotionTargets(id); if(!targets.length) return '';
  if(!PROMOTION_PAGE_LIVE) return `<div class="forge-promote is-soon"><div class="fp-head">⬆ ${escapeHtml(TX('ui.tu2-promo-title'))} <span class="tu2-soon-chip">${escapeHtml(TX('ui.tu2-coming-soon'))}</span></div><p class="forge-note">${escapeHtml(TX('ui.tu2-promo-forge-note'))}</p><button type="button" class="btn small" data-go-promotion>${escapeHtml(TX('ui.tu2-promo-open'))}</button></div>`;
  const defs = getCardDefs(), at = Math.max(1, Number(sel.promoteAt)||3);
  if(L < at) return `<div class="forge-promote is-locked"><div class="fp-head">⬆ ${escapeHtml(_t('Promotion at Lv {n}', {n:at}))}</div><p class="forge-note">${targets.map(t=> `${defs[t].icon||''} ${escapeHtml(defs[t].name)}`).join(' · ')}</p></div>`;
  if(!targets.includes(forgePromotePick)) forgePromotePick = null;
  const afford = myCurrencies.gold >= PROMOTE_COST.gold && myCurrencies.dust >= PROMOTE_COST.dust;
  const pick = forgePromotePick && defs[forgePromotePick];
  return `<div class="forge-promote">
    <div class="fp-head">⬆ ${escapeHtml(_t('Promote'))}</div>
    <p class="forge-note">${escapeHtml(_t('Pick what it becomes. Your decks get the new card; this one goes back to level 0.'))}</p>
    <div class="fp-choices">${targets.map(t=> `<button type="button" class="fp-choice ${t===forgePromotePick?'selected':''}" data-promote="${escapeAttr(t)}" aria-pressed="${t===forgePromotePick}">${cardTileHTML(defs[t], {inPlay:true})}${myUnlockedCardIds.has(t) ? '<span class="fp-owned">✓</span>' : ''}</button>`).join('')}</div>
    <button type="button" class="btn primary forge-act" id="forgePromoteBtn" ${pick && afford ? '' : 'aria-disabled="true"'}>⬆ ${pick ? escapeHtml(_t('Promote to {name}', {name:pick.name})) : escapeHtml(_t('Pick a promotion'))}${btnCostHTML(PROMOTE_COST)}</button>
  </div>`;
}
async function forgePromote(btn){
  if(forgeBusy || !forgeSelectedId) return;
  const id = forgeSelectedId, to = forgePromotePick, defs = getCardDefs(), d = defs[id];
  const at = Math.max(1, Number(d && d.promoteAt)||3);
  const uid = forgeUid(id), cL = forgeCopyLevel(id, uid); // 2026-10-18 (package NF): the copy on the anvil is promoted
  if(!to || !promotionTargets(id).includes(to) || cL < at || myCurrencies.gold < PROMOTE_COST.gold || myCurrencies.dust < PROMOTE_COST.dust){ denyShake(btn); if(to && cL >= at){ if(myCurrencies.dust < PROMOTE_COST.dust) cobbleSay('dust'); else if(myCurrencies.gold < PROMOTE_COST.gold) cobbleSay('gold'); } return; }
  forgeBusy = true; btn.disabled = true;
  const beforeHTML = cardTileHTML(d, {size:'full', extraClass:'forge-preview'});
  myCurrencies.gold -= PROMOTE_COST.gold; myCurrencies.dust -= PROMOTE_COST.dust; saveCurrencies();
  unlockCardForPlayer(to, 'promotion');
  forgeSetCopyLevel(id, uid, 0); // that copy goes back to its starting level (it used to be every copy of the card)
  const swap = counts=>{ if(!counts || !counts[id]) return false; counts[to] = (counts[to]||0) + counts[id]; delete counts[id]; return true; };
  let changed = false;
  try{ (myDecks||[]).forEach(dk=> { if(swap(dk.counts)) changed = true; }); }catch(e){}
  if(swap(myDeckCounts)) changed = true;
  if(changed){ try{ saveMyDecks(); localStorage.setItem('bramblewood_arena_deck', JSON.stringify(myDeckCounts)); }catch(e){} }
  logTxn({action:'promoted', cardId:to, cardName:defs[to].name, icon:defs[to].icon, source:'Promotion from '+d.name, before:id, after:to});
  const afterHTML = cardTileHTML(defs[to], {size:'full', extraClass:'forge-preview'});
  try{ await forgeCentreStage(()=>{ // 2026-10-19 (package UX): on the centre stage
    fxHook('forgeUpgrade', 'promote', document.getElementById('anvilStage'), {from: d.rarity, to: defs[to].rarity}); // batch D (2026-10-15, docs/effects-lab-contract.md)
    return forgeSmithAnimation(beforeHTML, afterHTML, true); }); }catch(e){}
  forgeBusy = false; forgePromotePick = null; forgeSelectedId = to; renderForge();
  showToast(TX('toast.was-promoted-to', {name: escapeHtml(d.name), v2: escapeHtml(defs[to].name), v3: changed ? ' Your decks have the new card.' : ''}), 'ok');
}
// The smithing sequence. Resolves once the card has flipped to its new face.
function forgeSmithAnimation(beforeHTML, afterHTML, heavy){
  return new Promise(resolve=>{
    const stage = document.getElementById('anvilStage');
    const mountEl = stage && stage.querySelector('.forge-preview-wrap');
    const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if(!stage || !mountEl || reduce || !hasGsap()){ resolve(); return; }
    const card = mountEl.querySelector('.card-tile'), hammer = stage.querySelector('.forge-hammer');
    stage.classList.add('is-hot');
    const sparks = ()=>{
      for(let k=0;k<10;k++){
        const sp = document.createElement('span'); sp.className = 'forge-spark'; stage.appendChild(sp);
        const ang = -Math.PI*(0.1 + Math.random()*0.8), d = 40 + Math.random()*70;
        gsap.fromTo(sp, {x:0, y:0, opacity:1, scale:1}, {x:Math.cos(ang)*d*(Math.random()<.5?-1:1), y:Math.sin(ang)*d, opacity:0, scale:.3, duration:.45+Math.random()*.3, ease:'power2.out', onComplete:()=> sp.remove()});
      }
    };
    const tl = gsap.timeline();
    tl.set(hammer, {opacity:1, rotation:-55, y:-30, x:40});
    const strikes = heavy ? 4 : 3;
    for(let k=0;k<strikes;k++){
      tl.to(hammer, {rotation:-55, y:-34, duration:.16, ease:'power2.out'})
        .to(hammer, {rotation:10, y:6, duration:.09, ease:'power3.in', onComplete:()=>{ try{ SoundKit.clang(); }catch(e){} sparks(); }})
        .to(card, {scaleY:.93, scaleX:1.04, duration:.05, yoyo:true, repeat:1, ease:'power1.out'}, '<');
    }
    tl.to(hammer, {opacity:0, y:-50, duration:.2})
      .add(()=>{
        stage.classList.remove('is-hot'); stage.classList.add('is-quench');
        for(let k=0;k<6;k++){ const st = document.createElement('span'); st.className = 'forge-steam'; stage.appendChild(st);
          gsap.fromTo(st, {x:(Math.random()-0.5)*80, y:0, opacity:.7, scale:.5}, {y:-90-Math.random()*40, opacity:0, scale:1.6, duration:1+Math.random()*.4, ease:'power1.out', onComplete:()=> st.remove()}); }
        try{ SoundKit.coin && SoundKit.coin(); }catch(e){}
      })
      .add(()=>{
        const flip = flipRevealCard(mountEl, {frontHTML: beforeHTML, backHTML: afterHTML, onFlipped: ()=>{ const c = mountEl.querySelector('.forge-preview'); if(c) starFallVfx.celebrate(c, heavy ? 3+Math.floor(Math.random()*5) : 1+Math.floor(Math.random()*4)); }});
        if(flip) flip.reveal();
        setTimeout(()=>{ stage.classList.remove('is-quench'); resolve(); }, 760);
      }, '+=0.15');
  });
}
// Temper on the anvil (2026-10-14): the level-up plays ProcFX.forge's stages on the card itself: heat glow → three hammer
// strikes with sparks → quench steam → temper shine. The forge timeline runs from 'heat' to its end at FORGE_TEMPER_SPEED,
// about 2 s, as long as the old smithing sequence. Each hammer impact plays the anvil clang, the quench a hiss of drips
// and the temper a chime; the existing LEVEL burst follows in forgeTemper. Falls back to forgeSmithAnimation without
// ProcFX; skipped under reduced motion. Prestige, refine, limit break and promotion keep forgeSmithAnimation.
const FORGE_TEMPER_SPEED = {heat:3.5, hammer:2, quench:3.2, temper:2.2}; // ≈ 0.46 s + 0.95 s + 0.6 s
function forgeTemperAnimation(beforeHTML, afterHTML){
  return new Promise(resolve=>{
    const stage = document.getElementById('anvilStage'), mountEl = stage && stage.querySelector('.forge-preview-wrap');
    const card = mountEl && mountEl.querySelector('.card-tile');
    if(!stage || !card || reducedMotion() || !hasGsap()){ resolve(); return; }
    if(!window.ProcFX || !ProcFX.forge){ forgeSmithAnimation(beforeHTML, afterHTML, false).then(resolve, resolve); return; }
    let f = null; try{ f = ProcFX.forge(card, {seed: 'temper:' + (forgeSelectedId || '') + ':' + Date.now()}); }catch(e){ f = null; }
    if(!f || !f.tl){ forgeSmithAnimation(beforeHTML, afterHTML, false).then(resolve, resolve); return; }
    // The hammer, sparks and steam layer is lifted off the tile onto the wrap, at the same origin, so the heat/quench
    // filters tint only the card and the strikes stay bright.
    const fxl = card.querySelector(':scope > .pfx-forge-fx');
    if(fxl){ fxl.style.left = card.offsetLeft + 'px'; fxl.style.top = card.offsetTop + 'px'; mountEl.appendChild(fxl); }
    const tl = f.tl, hammer = stage.querySelector('.forge-hammer');
    if(hammer) hammer.style.opacity = '0'; // ProcFX brings its own hammer onto the card
    stage.classList.add('is-hot');
    // Sounds ride the timeline, so they stay on the strikes at any speed: impacts land 0.15 s after each swing starts.
    // 2026-10-15 (user: "The forge sfx should play a little later, in time with the hammer vfx. Then RIGHT after it's done hammering,
    // the card goes into its shining animation!"): the forge's three-blow sound used to start on the click, during the heat, a
    // second ahead of the hammer; each blow now plays on its own impact. And the quench pause is gone: a beat after the last blow
    // the timeline jumps straight to the temper shine.
    [1.9, 2.45, 3.0].forEach((at, i)=> tl.call(()=>{ try{ SoundKit.forgeHit ? SoundKit.forgeHit(i, i === 2) : SoundKit.clang(); }catch(e){} }, null, at + .15));
    tl.call(()=>{ stage.classList.remove('is-hot'); tl.timeScale(FORGE_TEMPER_SPEED.temper); tl.seek('temper', true); }, null, 3.0 + .4);
    tl.call(()=>{ try{ SoundKit.readyChime ? SoundKit.readyChime() : (SoundKit.coin && SoundKit.coin()); }catch(e){} }, null, 'temper+=0.15');
    let done = false;
    const finish = ()=>{ if(done) return; done = true;
      try{ f.destroy(); }catch(e){}
      stage.classList.remove('is-hot', 'is-quench');
      if(mountEl.isConnected) mountEl.innerHTML = afterHTML; // the tempered face; renderForge redraws the panel right after
      resolve(); };
    tl.eventCallback('onComplete', finish);
    setTimeout(finish, 4000); // never hold the Forge hostage
    // Pace per stage: the heat and the cool-down move quickly, the hammer gets the most real time so each strike reads.
    tl.call(()=> tl.timeScale(FORGE_TEMPER_SPEED.hammer), null, 'hammer');
    tl.seek('heat').timeScale(FORGE_TEMPER_SPEED.heat).play();
  });
}
// Cobble says why the Forge said no (2026-10-14): Dust, Leaves, Materia, the Forge's tier or the map gate.
function cobbleSay(key){ try{ playDialogue('forge_cobble_' + key, {force:true}); }catch(e){} }
function cobbleWhyNot(L, id, uid){
  if(levelGateNeed((L||0) + 1)) return cobbleSay('gate');
  if(forgeTierFor(id, (L||0) + 1)) return cobbleSay('tier');
  const c = levelUpCost(L, id, uid);
  if((myCurrencies.dust||0) < c.dust) return cobbleSay('dust');
  if((myCurrencies.gold||0) < c.gold) return cobbleSay('gold');
  if(Object.entries(c.mats||{}).some(([m, n])=> ownedCount(m) < n)) return cobbleSay('mats');
}
async function forgeTemper(btn){
  if(forgeBusy || !forgeSelectedId) return;
  // 2026-10-18 (package NF, owner 23:37: "Forging one card doesn't mean all copies become stronger!"): only the copy on the anvil
  // (the picker's, your best by default) goes up a level, paid partly by that copy's own credit.
  const id = forgeSelectedId, uid = forgeUid(id), L = forgeCopyLevel(id, uid);
  if(L>=playerLevelCap(id) || L < 1 || !canAffordLevelUp(L, id, uid)){ denyShake(btn); if(L >= 1 && L < playerLevelCap(id)) cobbleWhyNot(L, id, uid); return; } // Level 0 → 1 is the Nest's (2026-10-12); BAL2: a Base card's top is Lv 4
  forgeBusy = true; btn.disabled = true; if(reducedMotion() || !hasGsap()) try{ SoundKit.forgeStrike(); }catch(e){} // with the animation, each blow sounds on its hammer impact (2026-10-15)
  const c = levelUpCost(L, id, uid), keep = (copyByUid(id, uid) || {}).uid;
  const beforeHTML = cardTileHTML(forgeCopyDef(id, getCardDefs()[id]), {size:'full', extraClass:'forge-preview'});
  myCurrencies.dust -= c.dust; myCurrencies.gold -= c.gold; saveCurrencies();
  if(c.credit && (c.credit.dust || c.credit.gold)) spendForgeCredit(id, c.credit, uid);
  Object.entries(c.mats||{}).forEach(([mid, n])=> spendCopies(mid, n));
  forgeSetCopyLevel(id, uid, L+1); if(keep) forgeCopyPick = {id, uid: keep}; // the tempered copy stays on the anvil
  try{ bumpQuestCounter('forgeLevels', 1); }catch(e){} // 2026-10-26 (package RES4): a Trail challenge counts copies tempered
  const afterHTML = cardTileHTML(forgeCopyDef(id, getCardDefs()[id]), {size:'full', extraClass:'forge-preview'});
  // 2026-10-19 (package UX, owner 21:36: "Forging should have centre of field treatment"): the tempering and its LEVEL burst play on
  // the centre stage, then the card flies back to the anvil
  let centred = false; try{ centred = await forgeCentreStage(()=> forgeTemperAnimation(beforeHTML, afterHTML), {burst: {kind: 'levelUp', text: 'LEVEL ' + (L+1) + '!'}, hold: 900}); }catch(e){}
  forgeBusy = false; renderForge();
  const pop = document.querySelector('#forgeDetail .forge-level-label');
  if(pop){ pop.classList.add('pop'); }
  if(!centred) metaFx('levelUp', '#forgeDetail .card-tile', {text:'LEVEL ' + (L+1) + '!'});
  showToast(TX('toast.is-now-level', {v1: getCardDefs()[id].name, v2: L+1}), 'ok');
}
async function forgePrestige(btn){
  if(forgeBusy || !forgeSelectedId) return;
  const id = forgeSelectedId;
  if(!canAffordPrestige(id)){ denyShake(btn); return; }
  forgeBusy = true; btn.disabled = true;
  const beforeHTML = cardTileHTML(getCardDefs()[id], {size:'full', extraClass:'forge-preview'});
  if(!prestigeUpCard(id)){ forgeBusy = false; denyShake(btn); return; }
  try{ SoundKit.prestigeTone && SoundKit.prestigeTone(); }catch(e){}
  const afterHTML = cardTileHTML(getCardDefs()[id], {size:'full', extraClass:'forge-preview'});
  try{ await forgeCentreStage(()=>{ // 2026-10-19 (package UX): on the centre stage
    fxHook('forgeUpgrade', 'prestige', document.getElementById('anvilStage'), {tier: (PRESTIGE_TIERS[getCardPrestige(id) - 1] || {}).key}); // batch D (2026-10-15, docs/effects-lab-contract.md)
    return forgeSmithAnimation(beforeHTML, afterHTML, true); }); }catch(e){}
  forgeBusy = false; renderForge();
}
/* ---- Home landing page (2026-09-20, per explicit request: "Have a 'Home' landing page...
   contains the Play, Deck, Codex" + "Shop (in main nav)" + "Settings and Profile button will be
   ...below the Codex button... share a row") — this REPLACES the old always-visible topbar tab
   strip (Codex/Play/Forge/Simulator) as the app's primary navigation. Forge lives inside Codex
   now (see codexShell above) and the Simulator lives inside the new Deck section (below); Home
   itself just has four big section buttons plus a Settings/Profile row underneath. ---- */
function homeTileDetails(){
  const out = {};
  try{
    const p = loadConquestProgress();
    for(const map of CONQUEST_MAPS){ if(!isMapUnlocked(map, p)) continue; const i = map.nodes.findIndex((n, k)=> n.kind!=='tutorial' && isNodeVisible(map, n, k, p) && !p.completed.includes(conquestNodeId(map.id, n.key))); if(i >= 0){ out.play = `Next: ${map.nodes[i].icon||''} ${map.nodes[i].name}`; break; } }
  }catch(e){}
  try{ const d = (myDecks||[]).find(x=> x.id===activeDeckId); out.deck = `${(d && d.name) || 'Your deck'} · ⚔ ${mainDeckLevel(myDeckCounts, myLeaderId) || 1}`; }catch(e){}
  try{ const defs = getCardDefs(), ids = Object.keys(defs).filter(id=> !defs[id].test && !defs[id].token && !isHofVariant(defs[id])); out.codex = (()=>{ const c = collectionStats(); return `${c.owned} / ${c.total} cards`; })(); }catch(e){}
  try{ const owned = Object.keys(myCardCopies||{}).filter(k=> (myCardCopies[k]||[]).length).length; out.nest = owned ? `${owned} card${owned===1?'':'s'} collected` : 'Win cards to fill it'; }catch(e){}
  try{ const packs = (typeof SHOP_PACKS_DEFAULT!=='undefined' ? SHOP_PACKS_DEFAULT : []).filter(x=> packOnSale(x) && x.cost && x.cost.gold); if(packs.length){ const c = Math.min(...packs.map(x=> x.cost.gold)); out.shop = `Packs from ${c} 🍁`; } }catch(e){}
  try{ const live = liveRaidDefs(); if(live.length) out.raid = live.length >= 2 ? `${live.length} bosses this week` : `This week: ${live[0].name}`; }catch(e){}
  return out;
}
// Community page (2026-10-10, user: "Clicking community should jump you straight to a community page. Over there, then
// you can switch between the different options."): Ranking, Friends and Guild share one switcher above whichever is open.
// 2026-10-15 (user, on a screenshot of the bar: "This bar does not look very good. Friends should be the default section."): Friends
// comes first; the bar sits directly above the open section (it used to land under Friends), as wide as the section, with the
// title and an even three-way tab strip centred together instead of a title far left and big buttons crammed to the right.
const COMMUNITY_TABS = [['friends','👥', 'Friends'], ['ranking','🏆', 'Ranking'], ['guild','🛡️', 'Guild']];
function syncCommunityTabs(tab){
  if(tab !== 'friends') try{ npcSuggestRevealed = false; }catch(e){} // the next visit to Friends pauses 1 s again
  let bar = document.getElementById('communityTabs');
  const on = COMMUNITY_TABS.some(([t])=> t === tab), open = COMMUNITY_TABS.filter(([t])=> tabOpen(t));
  if(!on || open.length < 2){ if(bar) bar.hidden = true; return; }
  const view = document.getElementById('view-' + tab); if(!view) return;
  if(!bar){ bar = document.createElement('div'); bar.id = 'communityTabs'; bar.className = 'community-tabs'; }
  if(bar.nextElementSibling !== view) view.parentNode.insertBefore(bar, view);
  bar.innerHTML = `<h2 class="community-title"><span aria-hidden="true">👥</span> Community</h2><div class="community-seg" role="tablist" aria-label="Community">${open.map(([t, ic, l])=> `<button type="button" class="cm-tab ${t===tab?'is-on':''}" role="tab" aria-selected="${t===tab}" data-commtab="${t}"><span aria-hidden="true">${ic}</span> ${l}</button>`).join('')}</div>`;
  bar.hidden = false;
  bar.querySelectorAll('[data-commtab]').forEach(b=> b.onclick = ()=> switchTab(b.dataset.commtab));
}
