const RAID_BONUS_TICKET_KEY = 'bramblewood_raid_bonus_tickets_v1';
PROGRESS_KEYS.push(RAID_BONUS_TICKET_KEY);
function raidBonusTicketName(){ return TX('ui.tu2-bonus-ticket-name'); }
function raidBonusTicketIcon(){ return '<span class="rk-tk-ico is-bonus">🎫<i aria-hidden="true">🐙</i></span>'; }
function raidBonusTickets(){ try{ return Math.max(0, Math.floor(Number(localStorage.getItem(RAID_BONUS_TICKET_KEY)) || 0)); }catch(e){ return 0; } }
function addRaidBonusTickets(n){ const v = Math.max(0, raidBonusTickets() + Math.round(Number(n) || 0)); try{ localStorage.setItem(RAID_BONUS_TICKET_KEY, String(v)); }catch(e){} return v; }
function raidTicketsHeld(){ return raidTicketItems() + raidBonusTickets(); }
function addRaidTicketItems(n){ const v = Math.max(0, raidTicketItems() + Math.round(Number(n) || 0)); try{ localStorage.setItem(RAID_TICKET_ITEM_KEY, String(v)); }catch(e){} return v; }
