  const me = m.players[1], E = m.engine;
  if(id === 'draught' && me.hq.hp >= me.hq.maxHp) return TX('toast.your-castle-is-already-at-full');
  if(id === 'scoutmap' && (!me.deck || !me.deck.length)) return TX('toast.your-deck-is-empty');
  if(id === 'firepot' && !E.allBoardCards(m.players[2]).some(c=> c.hp > 0 && !c.cageOf)) return TX('toast.there-is-nothing-to-throw-it');
  if(id === 'honeycake' && !E.allBoardCards(me).some(c=> c.hp > 0 && c.hp < c.maxHp)) return TX('toast.none-of-your-units-is-hurt');
  if(id === 'whetstone' && !E.allBoardCards(me).some(c=> c.hp > 0 && !c.cageOf)) return TX('toast.you-have-no-units-on-the');
  if(id === 'caltrops' && !E.allBoardCards(m.players[2]).some(c=> c.hp > 0 && (c.wait||0) > 0)) return TX('toast.no-enemy-unit-is-still-waiting');
