// The item leaves the pack and arcs to each target (2026-10-17). Returns how long until it lands (0: no flight).
function itemFlight(id, from, rects){
  if(!from || !rects.length || reducedMotion() || !fxAtLeast('low')) return 0;
  const d = ITEM_DEFS[id], sx = from.left + from.width/2, sy = from.top + from.height/2, dur = 440;
  rects.slice(0, 8).forEach((tr, i)=>{
    const ex = tr.left + tr.width/2, ey = tr.top + tr.height/2, lift = Math.min(160, 60 + Math.abs(ex - sx) * .25);
    const f = document.createElement('div'); f.className = 'item-fly'; f.setAttribute('aria-hidden', 'true'); f.textContent = d.icon;
    f.style.setProperty('--ik', ITEM_TINT[id] || '#ffd36a');
    document.body.appendChild(f);
    const mx = (sx + ex)/2, my = Math.min(sy, ey) - lift;
    const at = (x, y, s, rot)=> `translate(${(x - 18).toFixed(1)}px, ${(y - 18).toFixed(1)}px) scale(${s}) rotate(${rot}deg)`;
    try{ f.animate([{transform: at(sx, sy, .6, 0), opacity:.0}, {transform: at(sx, sy - 10, 1.15, -8), opacity:1, offset:.12}, {transform: at(mx, my, 1.35, 140), opacity:1, offset:.55}, {transform: at(ex, ey, .9, 330), opacity:1}],
      {duration: dur, delay: i * 55, easing: 'cubic-bezier(.35,.1,.45,1)', fill: 'both'}); }catch(e){}
    setTimeout(()=> f.remove(), dur + i * 55 + 30);
  });
  return dur + Math.min(rects.length, 8) * 55 - 55;
}
// Where it lands (2026-10-17): a ring in the item's colour and a floating number on each target, the board catches up, a
