function wildpathCost(n){ return n.capstone ? 25 : n.y >= 380 ? 5 : n.y >= 290 ? 10 : n.y >= 200 ? 15 : 20; }
function wildpathRanks(){ try{ return JSON.parse(localStorage.getItem(WILDPATH_KEY) || '{}') || {}; }catch(e){ return {}; } }
function wildpathSpent(){ const r = wildpathRanks(); let t = 0; WILDPATH_TREES.forEach(tr=> tr.nodes.forEach(n=>{ t += (r[n.id]||0) * wildpathCost(n); })); return t; }
function wildpathAvailable(){ return Math.max(0, wildpathPoints().total - wildpathSpent()); }
function wildpathCanLearn(n){ const r = wildpathRanks(); if((r[n.id]||0) >= (n.ranks||1)) return 'max'; if(!(n.req||[]).every(q=> (r[q]||0) > 0) && (n.req||[]).length) return 'locked'; return wildpathAvailable() >= wildpathCost(n) ? 'ok' : 'points'; }
function wildpathLearn(id){ const n = WILDPATH_TREES.flatMap(t=> t.nodes).find(x=> x.id === id); if(!n || wildpathCanLearn(n) !== 'ok') return false; const r = wildpathRanks(); r[id] = (r[id]||0) + 1; try{ localStorage.setItem(WILDPATH_KEY, JSON.stringify(r)); }catch(e){} return true; }
function wildpathTreeSVG(tree){
  const byId = Object.fromEntries(tree.nodes.map(n=> [n.id, n]));
  // a wobbly, hand-inked line between two nodes (deterministic jitter from the ids)
  const seed = str=> [...str].reduce((a, ch)=> (a*31 + ch.charCodeAt(0)) % 9973, 7);
  const ink = (a, b)=>{ const k = seed(a.id + b.id), mx = (a.x + b.x)/2 + ((k % 41) - 20), my = (a.y + b.y)/2 + ((k % 23) - 11);
    return `M${a.x} ${a.y} Q ${mx} ${my} ${b.x} ${b.y}`; };
  const links = tree.nodes.flatMap(n=> (n.req||[]).map(r=> byId[r] ? `<path class="wp-ink" d="${ink(byId[r], n)}" style="--len:${Math.round(Math.hypot(n.x - byId[r].x, n.y - byId[r].y) * 1.15)}"/>` : ''));
  const nodes = tree.nodes.map((n, i)=> `<g class="wp-node${n.capstone ? ' is-cap' : ''}${i === 0 ? ' is-start' : ''}${wildpathSel === n.id ? ' is-sel' : ''}" data-wp="${n.id}" tabindex="0" role="button" aria-label="${escapeAttr(n.name + ': ' + n.desc)}" transform="translate(${n.x} ${n.y})" style="--i:${i}">
      <circle class="wp-halo" r="${n.capstone ? 26 : 20}"/><circle class="wp-dot" r="${n.capstone ? 19 : 15}"/><text class="wp-ico" text-anchor="middle" dominant-baseline="central">${n.icon}</text>
      ${n.ranks ? `<text class="wp-rank" x="${n.capstone ? 18 : 14}" y="${n.capstone ? -16 : -12}" text-anchor="middle">${wildpathRanks()[n.id]||0}/${n.ranks}</text>` : ''}</g>`);
  return `<svg class="wp-tree-svg" viewBox="0 0 300 430" style="--tint:${tree.tint}" aria-label="${escapeAttr(tree.name)} path">${links.join('')}${nodes.join('')}</svg>`;
}
// Path points (2026-10-12, action-items lap, D32 with my suggested default: "1 per map, +1 per boss S rank"): worked out
// from Conquest progress, so every save already has its points. Spending them waits until the trails leave preview.
// Wildpaths wait for Map 21 (2026-10-13, user: "remove it till about Map 21. At that point, do not count Skirmishes from Map 0-20
// for this"): the note and the page open once Map 20's last fight is won, and only maps from 21 on earn points.
const WILDPATH_FROM_MAP = 21;
function wildpathsOpen(){
  try{ const m20 = mainConquestMaps()[WILDPATH_FROM_MAP - 1]; if(!m20) return false; const key = mapRewardNodeKey(m20);
    return !!key && (loadConquestProgress().completed || []).includes(conquestNodeId(m20.id, key)); }catch(e){ return false; }
}
// 2026-10-17 (user: "1 point per map, 2 from boss S rank"): a map cleared (its boss, the reward fight, beaten) is 1 point, and an S
// rank or better on that boss adds 2. Before: 1 per map, and +1 for every boss-kind fight on the map won at S (so a map with two
// bosses could give 3). Still only maps from WILDPATH_FROM_MAP on count.
const WILDPATH_PER_MAP = 1, WILDPATH_PER_BOSS_S = 2;
function wildpathPoints(){
  const pr = loadConquestProgress(), done = new Set(pr.completed || []), ranks = pr.ranks || {};
  let maps = 0, sRanks = 0;
  mainConquestMaps().filter((m, i)=> !m.reserved && i >= WILDPATH_FROM_MAP).forEach(m=>{
    const key = mapRewardNodeKey(m); if(!key) return; const id = conquestNodeId(m.id, key);
    if(done.has(id)) maps++;
    if(done.has(id) && rankAtLeast(ranks[id], 'S')) sRanks++;
  });
  return {maps, sRanks, fromMaps: maps * WILDPATH_PER_MAP, fromS: sRanks * WILDPATH_PER_BOSS_S, total: maps * WILDPATH_PER_MAP + sRanks * WILDPATH_PER_BOSS_S};
}
const WILDPATH_EARN_TIP = '1 Path point for each map you clear, +2 for an S rank on its boss.';
// Hover tooltips (2026-10-17, user: "Hover tooltips for Wildpaths"): every mark explains itself on hover or keyboard focus (and on a tap,
// after it is picked): its name, what it does, its cost a rank, ranks learned and what it needs first.
function wildpathTipHTML(n, all){
  const r = wildpathRanks()[n.id] || 0, st = wildpathCanLearn(n), c = wildpathCost(n);
  const need = (n.req||[]).length ? 'Comes after ' + n.req.map(q=> (all.find(x=> x.id === q) || {}).name || q).join(' or ') + '.' : 'A starting mark.';
  const state = st === 'max' ? 'Learned.' : st === 'locked' ? 'Learn the one before first.' : st === 'points' ? `Needs ✦ ${c}; you have ✦ ${wildpathAvailable()}.` : 'Ready to learn.';
  return `<b>${n.icon} ${escapeHtml(n.name)}</b>${n.capstone ? ' <small>capstone</small>' : ''}<span>${escapeHtml(n.desc)}</span><small>✦ ${c} a rank${n.ranks ? ` · ${r}/${n.ranks} learned` : ''}</small><small>${escapeHtml(need)} ${escapeHtml(state)}</small>`;
}
