// Home menu "brandish" wiring (2026-09-20, per explicit requests: "Brandish the menu items -
// make them look nice. On hover, and click, they dazzle and float back and forth (3d-like)."
// and "Clicking the chestnut on the main page makes fun knock sound and the icon also vibrates
// a little"). The hover half of the dazzle/float is pure CSS (:hover in arena_template.html);
// this only needs to handle the CLICK half, which needs JS because it must self-terminate (a
// class that's still on the button when the animation ends would just look frozen mid-tilt, and
// would also block the same animation from retriggering on the next click).
function wireHomeMenuFlourish(root){
  // Magnetic cursor-follow tilt (2026-09-20, "look at modern examples - embody"): rather than
  // the old scripted always-rocking hover animation, the button now genuinely leans toward
  // wherever the cursor is over its face — a common "premium"/tactile technique in modern game
  // and app UI. --tiltX/--tiltY (read by the CSS transform, and re-read live by the click-pop
  // keyframes so a click mid-hover keeps its current lean rather than snapping flat) are set
  // directly from pointer position each mousemove; CSS's own transition timing smooths the
  // motion between events and handles the spring-back to neutral on mouseleave, so no rAF loop
  // is needed here. Big buttons tilt a bit more than the small Settings/Profile row, since they
  // have more visual weight to sell the effect.
  root.querySelectorAll('.home-menu-btn, .home-menu-btn-small').forEach(btn=>{
    const maxTilt = btn.classList.contains('home-menu-btn') ? 10 : 6;
    btn.addEventListener('mousemove', (e)=>{
      const r = btn.getBoundingClientRect();
      const nx = ((e.clientX - r.left) / r.width) * 2 - 1;   // -1 (left edge) .. 1 (right edge)
      const ny = ((e.clientY - r.top) / r.height) * 2 - 1;   // -1 (top edge) .. 1 (bottom edge)
      // Sign convention (matches the classic "vanilla-tilt" magnetic-card effect): whichever
      // edge the cursor is nearest tips TOWARD the viewer, like the button turning to face the
      // cursor, rather than dipping away from it — so a negative rotateX/rotateY is what lifts
      // the top/right edge up out of the screen.
      btn.style.setProperty('--tiltY', (-nx * maxTilt).toFixed(2) + 'deg');
      btn.style.setProperty('--tiltX', (ny * maxTilt).toFixed(2) + 'deg');
    });
    btn.addEventListener('mouseleave', ()=>{
      btn.style.setProperty('--tiltX', '0deg');
      btn.style.setProperty('--tiltY', '0deg');
    });
    btn.addEventListener('click', ()=>{
      btn.classList.remove('btn-dazzle');
      void btn.offsetWidth; // force reflow so re-adding the class retriggers the animation even on rapid repeat clicks
      btn.classList.add('btn-dazzle');
    });
    btn.addEventListener('animationend', (e)=>{ if(e.animationName==='menuBtnClickPop') btn.classList.remove('btn-dazzle'); });
  });
  const chestnut = root.querySelector('.home-menu-mark');
  if(chestnut){
    chestnut.addEventListener('click', ()=>{
      SoundKit.woodKnock();
      chestnut.classList.remove('chestnut-knock');
      void chestnut.offsetWidth;
      chestnut.classList.add('chestnut-knock');
    });
    chestnut.addEventListener('animationend', (e)=>{ if(e.animationName==='knockVibrate') chestnut.classList.remove('chestnut-knock'); });
  }
}

/* ---- Deck menu (2026-09-20, per explicit request: "Deck Menu: Similar to the 'Player' page.
   Shows your decks. Deck has a small preview w/ Castle | Leader | Deck pill items." +
   "Simulator is moved into the Deck menu.") ---- */
let deckSubTab = 'list'; // 'list' | 'sim' — mirrors playSubTab's own pattern
let deckEditingId = null; // non-null while a specific deck's builder is open
// Explicit Save (2026-10-08, user: "Need to press save to save Deck"): while the builder is open its
// edits only change the working copy (myDeckCounts / myCharacterId / myLeaderId). Save writes them to
// the deck; Discard reloads the deck as saved. Leaving with unsaved edits asks first.
var deckDraftOn = false, deckDirty = false;
function deckDraftActive(){ return deckDraftOn; }
function markDeckDirty(){ if(!deckDirty){ deckDirty = true; } refreshDeckSaveBar(); }
function deckSaveBarHTML(){ return `<div class="deck-savebar ${deckDirty?'is-dirty':''}" id="deckSaveBar" role="status"><span class="dsb-state">${deckDirty?'Unsaved changes':'All changes saved'}</span><button type="button" class="btn small ghost" id="deckDiscardBtn" ${deckDirty?'':'disabled'}>Discard</button><button type="button" class="btn small primary" id="deckSaveBtn" ${deckDirty?'':'disabled'}>💾 Save deck</button></div>`; }
function refreshDeckSaveBar(){
  const bar = document.getElementById('deckSaveBar'); if(!bar) return;
  bar.classList.toggle('is-dirty', deckDirty);
  bar.querySelector('.dsb-state').textContent = deckDirty ? 'Unsaved changes' : 'All changes saved';
  bar.querySelectorAll('button').forEach(b=> b.disabled = !deckDirty);
}
function commitDeckDraft(){
  deckDraftOn = false;
  try{ saveMyDeck(); saveMyCharacter(); saveMyLeader(); } finally { deckDraftOn = !!deckEditingId; }
  deckDirty = false; refreshDeckSaveBar();
  try{ SoundKit.codeImport && SoundKit.codeImport(); }catch(e){}
}
function discardDeckDraft(){
  const id = activeDeckId;
  deckDraftOn = false; deckDirty = false;
  try{ switchActiveDeck(id); } finally { deckDraftOn = !!deckEditingId; }
}
function endDeckDraft(){ deckDraftOn = false; deckDirty = false; document.getElementById('deckSaveBar')?.remove(); }
// Runs `then` once any unsaved edits are saved or discarded (or the player stays). Returns false if it had to ask.
function deckLeaveGuard(then){
  if(!deckDirty){ then(); return true; }
  const d = getActiveDeck();
  bwChoice({title:TX('dialog.save-your-deck'), body:TX('dialog.you-changed-without-saving', {v1: d ? '“' + d.name + '”' : 'this deck'}),
    choices:[{key:'save', label:TX('dialog.save'), primary:true}, {key:'discard', label:TX('dialog.discard-changes')}, {key:'stay', label:TX('dialog.keep-editing'), ghost:true}]})
  .then(k=>{ if(k==='save'){ commitDeckDraft(); then(); } else if(k==='discard'){ discardDeckDraft(); then(); } });
  return false;
}
try{ window.addEventListener('beforeunload', e=>{ if(deckDirty){ e.preventDefault(); e.returnValue = ''; } }); }catch(e){}
let deckHeroView = false; // Deck → 🦸 Hero: the Hero Hall instead of the deck builder
var deckOpenBuilderOnce = false; // set by buttons that should land in the builder, not the list (2026-10-08)
let deckShowList = true; // D16 (2026-10-03): Deck opens straight into the active deck's builder; "Manage decks" shows the list
// ---- The Hero Hall (Deck → 🦸 Hero) ----
let heroCreatePeople = 'legion';
// The Hero Hall lives in the Stomping Grounds now (2026-10-13); it redraws whichever page it's on.
function heroHallRerender(){ if(typeof currentTab !== 'undefined' && currentTab === 'stomp') renderStomp(); else renderDeckSection(); }
// 2026-10-19 (package SG, owner 23:43: "Stomping Grounds UI fidelity should match the rest."): the Stomping Grounds is a place now,
// like the Forge and the Nest: the Arena's training ring (map art "marena") under a veil, a hanging sign, a dust layer, the Hero on
// a mound of trampled earth, the three benches as their own panels, and loading / error states. A visual and layout pass only: the
// same buttons, ids, data attributes and handlers (tests/e2e/hero.py and the batch-F hooks in bramblewood-fx-f.js rely on them).
// The scene's shell (sign, subtitle, dust) is built once per visit, so a stat click redraws only #stompBody and the dust keeps drifting.
let stompLoadTries = 0;
function stompDataReady(){ try{ return typeof CARD_DEFS_BASELINE !== 'undefined' && Object.keys(CARD_DEFS_BASELINE).length > 0 && typeof HERO_PEOPLES !== 'undefined'; }catch(e){ return false; } }
function stompStateHTML(kind){
  // kind: 'loading' | 'error'. The loading state is a card-shaped placeholder and three bench placeholders, as the page will look.
  if(kind === 'loading') return `<section class="panel stomp-state is-loading" role="status" aria-live="polite"><div class="ss-skel" aria-hidden="true"><span class="ss-card"></span><span class="ss-lines"><i></i><i></i><i></i></span></div><p class="ss-msg">${escapeHtml(TX('ui.stomp-loading'))}</p></section>`;
  return `<section class="panel stomp-state is-error" role="alert"><span class="ss-ico" aria-hidden="true">🐾</span><h3>${escapeHtml(TX('ui.stomp-error'))}</h3><p class="panel-sub">${escapeHtml(TX('ui.stomp-error-hint'))}</p><button type="button" class="btn primary" id="stompRetryBtn">↻ ${escapeHtml(TX('ui.stomp-retry'))}</button></section>`;
}
function renderStomp(){
  const root = document.getElementById('view-stomp'); if(!root) return;
  root.classList.add('stomp-scene', 'map-theme-marena');
  const title = TX('ui.stomp-title');
  root.dataset.sign = '🐾 ' + (window.i18 ? i18(title) : title);
  if(!root.querySelector(':scope > #stompBody')){
    root.innerHTML = `<div class="stomp-dust" aria-hidden="true">${Array.from({length:12}, (_, k)=> `<i style="left:${(k*37)%94 + 3}%; animation-delay:${-((k*1.3)%7).toFixed(1)}s; animation-duration:${7 + (k*0.9)%5}s"></i>`).join('')}</div>
      <header class="stomp-head"><h2 class="sr-only">🐾 ${escapeHtml(title)}</h2><p class="stomp-sub">${escapeHtml(TX('ui.stomp-sub'))}</p></header>
      <div id="stompBody"></div>`;
  }
  const body = document.getElementById('stompBody');
  if(!stompDataReady()){
    body.innerHTML = stompStateHTML(stompLoadTries < 20 ? 'loading' : 'error');
    if(stompLoadTries++ < 20) setTimeout(()=>{ if(typeof currentTab !== 'undefined' && currentTab === 'stomp') renderStomp(); }, 250);
    else { const rb = document.getElementById('stompRetryBtn'); if(rb) rb.onclick = ()=>{ stompLoadTries = 0; renderStomp(); }; }
    return;
  }
  stompLoadTries = 0;
  try{ renderHeroHall(body); }
  catch(e){
    try{ console.error('[Bramblewood] Stomping Grounds failed to draw:', e); }catch(_){}
    body.innerHTML = stompStateHTML('error');
    const rb = document.getElementById('stompRetryBtn'); if(rb) rb.onclick = ()=>{ root.innerHTML = ''; renderStomp(); };
  }
}
// A people's Level-1 Hero as the card it would be (2026-10-19, package SG): the create screen shows real card tiles, not bare art.
function heroPreviewDef(k){
  const P = HERO_PEOPLES[k], ad = CARD_DEFS_BASELINE[P.art] || {};
  return {id:HERO_ID, name:P.label, icon:P.icon, art:ad.art || '', hero:true, heroLevel:1, attack:P.base.attack, health:P.base.health,
    cost:1, wait:1, rarity:heroRarityForLevel(1), archetypes:P.archetypes.slice(), effects:{}, locked:false};
}
function renderHeroHall(body){
  if(!body) return;
  if(!myHero){
    body.innerHTML = `<section class="panel hero-hall hero-create stomp-stage">
      <div class="stomp-intro"><span class="si-ico" aria-hidden="true">🦸</span><div><h2>🦸 Raise a Hero</h2>
      <p class="panel-sub">Your own card. It levels up from battles and from crafting Materia in the Forge, to Level 100. You spend its stat points and pick its skills.</p></div></div>
      <h3 class="stomp-kicker">${escapeHtml(TX('ui.stomp-choose-people'))}</h3>
      <div class="hero-peoples" role="radiogroup" aria-label="${escapeAttr(TX('ui.stomp-choose-people'))}">${Object.entries(HERO_PEOPLES).map(([k, P])=> `<button type="button" class="hero-people ${k===heroCreatePeople?'on':''}" data-people="${k}" role="radio" aria-checked="${k===heroCreatePeople}">
        <span class="hp-card">${cardTileHTML(heroPreviewDef(k), {extraClass:'is-hero-card'})}</span>
        <span class="hp-text"><b>${P.icon} ${escapeHtml(P.label)}</b><small>${escapeHtml(P.blurb)}</small><small class="hp-base">Starts ⚔${P.base.attack} ❤${P.base.health}</small></span></button>`).join('')}</div>
      <div class="stomp-create-row"><label class="hero-name-row">Name <input id="heroNameInput" maxlength="24" placeholder="${escapeAttr(HERO_PEOPLES[heroCreatePeople].label)}"></label>
      <button type="button" class="btn primary big" id="heroCreateBtn">🦸 Raise my Hero</button></div>
    </section>`;
    body.querySelectorAll('[data-people]').forEach(b=> b.addEventListener('click', ()=>{ heroCreatePeople = b.dataset.people; renderHeroHall(body); }));
    document.getElementById('heroCreateBtn').addEventListener('click', ()=>{
      const name = (document.getElementById('heroNameInput').value || '').trim().slice(0, 24) || HERO_PEOPLES[heroCreatePeople].label;
      myHero = {people: heroCreatePeople, name, xp:0, xpv:2, lvBase:1, xpB:0, xpM:0 /* SX: the 3-part bar's pools */, alloc:{atk:0,hp:0,speed:0}, picks:{}, materia:{}, battles:0, wins:0, created: Date.now()};
      saveHero(); showToast(TX('toast.joins-your-cause-add-them-to', {name: escapeHtml(name)}), 'ok');
      heroHallRerender();
    });
    return;
  }
  const h = myHero, P = HERO_PEOPLES[h.people], lv = heroLevelOf(h), L = lv.level, d = heroDef();
  const free = heroPointsFree(h), inDeck = (myDeckCounts && myDeckCounts[HERO_ID] > 0);
  // 2026-10-19 (package SG): each stat's value sits in the colour of its badge on the card (⚔ red, ❤ green, ⏳ blue) via data-stat.
  const statRow = (key, label, now, step, note, max)=> `<div class="hero-stat" data-stat="${key}"><span class="hs-label">${label}</span><b class="hs-val">${now}</b>
      <span class="hs-cost">${HERO_COSTS[key]} pts ${note}</span>
      <button type="button" class="btn small" data-hstat="${key}" data-dir="-1" ${h.alloc[key]<=0?'disabled':''} aria-label="Less ${escapeAttr(label)}">−</button>
      <button type="button" class="btn small primary" data-hstat="${key}" data-dir="1" ${free < HERO_COSTS[key] || (max!=null && h.alloc[key]>=max) ?'disabled':''} aria-label="More ${escapeAttr(label)}">+</button></div>`;
  // 2026-10-19 (package SG): every skill row opens with its skill's icon in a round token, as the Codex's skill book does.
  const skIco = k=> `<span class="hk-ico" aria-hidden="true">${(k && skillIconHTML(k)) || '✦'}</span>`;
  const skills = HERO_SKILL_LEVELS.map(at=>{
    const picked = h.picks[at];
    if(picked){ const sd = heroSkillDef(picked); return `<div class="hero-skill is-picked">${skIco(picked)}<span class="hk-lv">Lv ${at}</span><b>${escapeHtml(sd ? sd.label : picked)}</b><small>${escapeHtml(sd && sd.desc ? sd.desc(heroSkillValue(L)) : '')}</small></div>`; }
    if(L < at) return `<div class="hero-skill is-locked"><span class="hk-ico" aria-hidden="true">🔒</span><span class="hk-lv">Lv ${at}</span><small>A new skill at Level ${at}</small></div>`;
    return `<div class="hero-skill is-choose"><span class="hk-ico" aria-hidden="true">✨</span><span class="hk-lv">Lv ${at}</span><b>Pick one</b><div class="hk-choices">${heroSkillOffer(h, at).map(k=>{ const sd = heroSkillDef(k); return `<button type="button" class="btn small" data-hpick="${at}" data-skill="${k}" title="${escapeAttr(sd.desc ? sd.desc(heroSkillValue(L)) : '')}"><span class="hkc-ico" aria-hidden="true">${skillIconHTML(k) || '✦'}</span> ${escapeHtml(sd.label)}</button>`; }).join('')}</div></div>`;
  }).join('');
  const noSkills = !Object.keys(h.picks || {}).length && L < HERO_SKILL_LEVELS[0];
  const mats = materiaStore(), noMats = !MATERIA_KINDS.some(k=> (mats[k.id]||0) > 0);
  body.innerHTML = `<section class="panel hero-hall stomp-stage">
    <div class="hero-top">
      <div class="stomp-plinth"><div class="hero-card-big has-dc">${detailCardHTML(d, {extraClass:'is-hero-card', tileOpts:{size:'detail'}}) /* 2026-10-30 (package CS-C): the Hero is the Detail card (tilt, spin, flip) */}</div></div>
      <div class="hero-info">
        <h2>🦸 ${escapeHtml(d.name)} <small>${escapeHtml(P.label)}</small></h2>
        <div class="hero-level"><b>Level ${L}</b>${L < HERO_MAX_LEVEL ? heroXpBarHTML(h) : '<small>Max level</small>'}</div>
        ${(()=>{ const r = rarityDef(d.rarity), nx = heroNextRarity(L); return `<div class="hero-rarity"><span class="hr-now" style="--hr:${r.color||'#eab308'}">${escapeHtml(_t(r.label))}</span>${nx ? `<small>${escapeHtml(_t('{rarity} at Level {n}', {rarity:_t(rarityDef(nx.rarity).label), n:nx.level}))}</small>` : `<small>${escapeHtml(_t('Top rarity'))}</small>`}</div>`; })()}
        <div class="hero-facts"><span>🪵 Costs ${d.cost}</span><span>⏳ Wait ${d.wait}</span><span>⚔ ${h.battles||0} battles · ${h.wins||0} wins</span></div>
        <div class="hero-deck-row">${inDeck ? '<span class="hero-in-deck">✓ In your active deck</span><button type="button" class="btn small ghost" id="heroDeckBtn">Take out of deck</button>' : '<button type="button" class="btn primary" id="heroDeckBtn">🃏 Add to my deck</button>'}</div>
        <p class="panel-sub hero-howto">XP: win with your Hero in the deck <b>+30</b> (+10 if it took the field), lose or draw <b>+10</b>, craft Materia <b>+${MATERIA_HERO_XP}</b>. Live and online matches don't carry your Hero yet.</p>
        <p class="panel-sub hero-xp-rule">${escapeHtml(TX('ui.sx-xp-rule', {n: Math.round((1 - HERO_XP_EITHER_BATTLE) * 100)}))}</p>${'' /* 2026-10-23 (package SX): the 3-part bar's rule, also its tooltip */}
      </div>
    </div>
  </section>
  <div class="hero-cols">
      <section class="panel hero-block"><h3><span class="hb-ico" aria-hidden="true">🏋️</span>Stat points <span class="hero-free ${free>0?'has':''}">${free} free</span></h3>
        ${statRow('atk', '⚔ Attack', d.attack, 1, '/ +1')}
        ${statRow('hp', '❤ Health', d.health, 1, '/ +1')}
        ${statRow('speed', '⏳ Swiftness', d.wait===0 ? 'Wait 0' : 'Wait 1', 1, '/ Wait −1', 1)}
        <button type="button" class="btn small ghost" id="heroRespecBtn" ${heroPointsSpent(h)?'':'disabled'}>↺ Reset points (free for now)</button>
      </section>
      <section class="panel hero-block"><h3><span class="hb-ico" aria-hidden="true">📘</span>Skills</h3>${noSkills ? `<p class="empty-hint stomp-empty">${escapeHtml(TX('ui.stomp-no-skills', {n: HERO_SKILL_LEVELS[0]}))}</p>` : ''}${skills}</section>
      <section class="panel hero-block"><h3><span class="hb-ico" aria-hidden="true">💎</span>Materia</h3>
        <p class="panel-sub">Craft a crystal from ${MATERIA_DUST_COST} ✨ Dust. Your Hero gains ${MATERIA_HERO_XP} XP each time. Crystals are kept for socketing, coming later.</p>
        <div class="hero-materia">${MATERIA_KINDS.map(k=> `<span class="mk-${k.id} ${(mats[k.id]||0) ? '' : 'is-none'}" title="${escapeAttr(k.name)}">${k.icon} ${mats[k.id]||0}</span>`).join('')}</div>
        ${noMats ? `<p class="empty-hint stomp-empty">${escapeHtml(TX('ui.stomp-no-materia'))}</p>` : ''}
        <button type="button" class="btn primary" id="heroCraftBtn" ${(myCurrencies.dust||0) < MATERIA_DUST_COST ? 'disabled' : ''}>💎 Craft Materia · ${MATERIA_DUST_COST} ✨</button>
        <small class="hero-dust">You have ${myCurrencies.dust||0} ✨</small>
      </section>
  </div>`;
  { const hc = body.querySelector('.hero-card-big.has-dc'); if(hc) mountDetailCard(hc, {}); } // 2026-10-30 (package CS-C)
  body.querySelectorAll('[data-hstat]').forEach(b=> b.addEventListener('click', ()=>{
    const k = b.dataset.hstat, dir = +b.dataset.dir;
    if(dir > 0 && heroPointsFree(myHero) < HERO_COSTS[k]) return;
    myHero.alloc[k] = Math.max(0, myHero.alloc[k] + dir); saveHero(); heroHallRerender();
    try{ fxHook('heroStat', k, dir); }catch(e){} // 2026-10-15 batch F
  }));
  body.querySelectorAll('[data-hpick]').forEach(b=> b.addEventListener('click', ()=>{ myHero.picks[b.dataset.hpick] = b.dataset.skill; saveHero(); showToast(TX('toast.learned', {v1: escapeHtml(heroSkillDef(b.dataset.skill).label)}), 'ok'); heroHallRerender(); }));
  body.querySelectorAll('[data-hpick]').forEach(b=> b.addEventListener('click', ()=>{ try{ fxHook('heroSkillPick', b.dataset.hpick); }catch(e){} })); // 2026-10-15 batch F
  const rs = document.getElementById('heroRespecBtn'); if(rs) rs.addEventListener('click', ()=>{ myHero.alloc = {atk:0,hp:0,speed:0}; saveHero(); heroHallRerender(); });
  document.getElementById('heroDeckBtn').addEventListener('click', ()=>{
    if(inDeck){ delete myDeckCounts[HERO_ID]; }
    else { myDeckCounts[HERO_ID] = 1; if(deckTotal(myDeckCounts) > DECK_SIZE){ deckHeroView = false; showToast(TX('toast.your-hero-takes-a-deck-slot', {DECK_SIZE})); } }
    try{ saveMyDeck(); }catch(e){ try{ syncActiveDeckFromCounts && syncActiveDeckFromCounts(); }catch(_){} }
    heroHallRerender();
  });
  document.getElementById('heroCraftBtn').addEventListener('click', ()=>{ if(craftMateria()) heroHallRerender(); });
  heroHallLevelFlourish(body);
}
function addTentPoles(root){ if(root && !root.querySelector(':scope > .tent-pole')) root.insertAdjacentHTML('afterbegin', '<span class="tent-pole left" aria-hidden="true"></span><span class="tent-pole right" aria-hidden="true"></span>'); }
function renderDeckSection(){ renderDeckSectionInner();
  // 2026-10-15 (user: "I should be able to go to the Tavern page from the Camp feature page(s)."): the Camp's foot has a door to
  // the Tavern once it's open (max Energy moved out of the Camp the same day: Nest, Forge, then Tavern).
  try{ const root = document.getElementById('view-deck'); if(root && !deckEditingId && featureUnlockedSafe('tavern')){
    root.insertAdjacentHTML('beforeend', `<section class="camp-tavern-door" aria-label="The Tavern"><span class="ctd-ico" aria-hidden="true">🍺</span><span class="ctd-txt"><b>The Tavern</b><small>Recruit a card with Beer, raise max Energy to 60 · 🍺 ${myCurrencies.beer||0} Beer</small></span><button type="button" class="btn small primary" id="campTavernBtn">Go to the Tavern</button></section>`);
    const b = root.querySelector('#campTavernBtn'); if(b) b.onclick = ()=> openTavern(); } }catch(e){} }
function renderDeckSectionInner(){
  const root = document.getElementById('view-deck');
  setTimeout(()=> addTentPoles(root), 0);
  if(!deckEditingId && !deckShowList && deckSubTab==='list' && myDecks.some(d=> d.id===activeDeckId)) deckEditingId = activeDeckId;
  if(deckEditingId){
    // Editing a specific deck reuses the exact same "Build your deck" UI the old Player sub-tab
    // had (renderPlayerSubTab) — it always edits whichever deck is ACTIVE, so opening the editor
    // for a non-active deck switches to it first (see switchActiveDeck's own comment above).
    if(activeDeckId!==deckEditingId){ endDeckDraft(); switchActiveDeck(deckEditingId); }
    deckDraftOn = true;
    // The save bar sits on the deck's "20/20 cards ✓ ready to play" row (2026-10-15; it floated over the page before): see
    // renderPlayerSubTab and deckSaveBarHTML.
    document.getElementById('deckSaveBar')?.remove();
    root.innerHTML = `<div class="play-subtabs-row deck-switch-row">
        <button type="button" class="btn small deck-back-btn" id="deckBackBtn" title="Back to your decks">‹ Back</button>
        <div class="deck-switcher" role="tablist" aria-label="Your decks">
          ${myDecks.map(d=> `<button type="button" class="deck-chip ${d.id===deckEditingId?'on':''}" data-switchdeck="${d.id}" role="tab" aria-selected="${d.id===deckEditingId}"${d.id===deckEditingId?' title="Click to rename"':''}>${d.id===mainDeckId?'<span class="dc-star" title="Main deck: the one you play with">★</span>':''}${escapeHtml(d.name)}${deckIsLegal(d)?'':'<span class="dc-warn" title="Not ready to play: needs exactly '+DECK_SIZE+' cards">!</span>'}</button>`).join('')}
          <button type="button" class="deck-chip deck-chip-new" id="deckNewChip" title="New deck">➕ New</button>
        </div>
        <div class="play-subtabs-actions">
          ${deckEditingId===mainDeckId ? `<span class="deck-main-tag ne-main-tag" title="${escapeAttr(TX('ui.ui4-main-deck-sub'))}"><b>★ ${escapeHtml(TX('ui.ui4-main-deck'))}</b><small>${escapeHtml(TX('ui.ui4-main-deck-sub'))}</small></span>` /* 2026-10-24 (package NE, owner 17:34 #19: the subtitle "you play with this one") */ : '<button type="button" class="btn small" id="deckMakeMainBtn" title="Play with this deck">★ Make main deck</button>'}
          <button type="button" class="btn small ghost" id="deckManageBtn" title="Rename, copy codes, import or delete decks">🗂 Manage decks</button>
        </div>
      </div>
      <div id="deckBuilderBody"></div>`;
    // Clicking the deck you're already in renames it (it's obvious which deck you mean).
    root.querySelectorAll('[data-switchdeck]').forEach(b=> b.addEventListener('click', ()=>{ if(b.dataset.switchdeck === deckEditingId){ startDeckRename(b, b.dataset.switchdeck); return; } deckLeaveGuard(()=>{ endDeckDraft(); deckEditingId = b.dataset.switchdeck; renderDeckSection(); }); }));
    document.getElementById('deckNewChip').addEventListener('click', e=>{ if(deckSlotDenied(e.currentTarget)) return; /* 2026-10-23 (package UI4): deck slots */ deckLeaveGuard(()=>{ endDeckDraft(); const d = createNewDeck(); deckEditingId = d.id; renderDeckSection(); }); });
    const mm = document.getElementById('deckMakeMainBtn');
    if(mm) mm.addEventListener('click', ()=>{ if(deckDirty) commitDeckDraft(); setMainDeck(deckEditingId); SoundKit.codeImport && SoundKit.codeImport(); renderDeckSection(); });
    document.getElementById('deckManageBtn').addEventListener('click', ()=> deckLeaveGuard(()=>{ endDeckDraft(); deckEditingId = null; deckShowList = true; renderDeckSection(); }));
    document.getElementById('deckBackBtn').addEventListener('click', ()=> deckLeaveGuard(()=>{ endDeckDraft(); deckEditingId = null; deckShowList = true; deckHeroView = false; renderDeckSection(); }));

    renderPlayerSubTab(document.getElementById('deckBuilderBody'));
    { const sv = document.getElementById('deckSaveBtn'), dc = document.getElementById('deckDiscardBtn'); // on the count row (2026-10-15)
      if(sv) sv.addEventListener('click', ()=>{ commitDeckDraft(); showToast(TX('toast.deck-saved'), 'ok'); renderDeckSection(); });
      if(dc) dc.addEventListener('click', ()=>{ discardDeckDraft(); renderDeckSection(); }); }
    return;
  }
  endDeckDraft();
  root.innerHTML = `
    <div class="play-subtabs-row">
      <div class="play-subtabs" role="tablist">
        <button class="tab-btn ${deckSubTab==='list'?'active':''}" data-decktab="list" role="tab" aria-selected="${deckSubTab==='list'}"><span class="tab-emoji">🃏</span> My Decks</button>
        ${adminEntryVisible() ? `<button class="tab-btn ${deckSubTab==='sim'?'active':''}" data-decktab="sim" role="tab" aria-selected="${deckSubTab==='sim'}"><span class="tab-emoji">📊</span> Simulator</button>` : ''}
      </div>
      <!-- 2026-09-26 (user report: "the UI is not well margined. the codex button maybe should be
           on the right of my decks/simulator") — this Codex cross-nav button used to sit inline
           inside the <h2>🃏 My Decks</h2> text below (a redundant second "My Decks" label, right
           next to the tab that already says the same thing), styled with .subnav-right-btn's
           margin-left:auto — which did nothing, since a bare <h2> is not a flex container. Moved
           it up onto this row instead, using the exact same .play-subtabs-row/.play-subtabs-actions
           space-between pattern renderPlay() already uses for its own Energy-pill/Settings actions,
           so it now sits genuinely right-aligned and only shows on the "My Decks" sub-tab. -->
      <div class="play-subtabs-actions"></div>
    </div>
    <div id="deckSubBody"></div>`;
  root.querySelectorAll('[data-decktab]').forEach(b=> b.addEventListener('click', ()=>{ deckSubTab = b.getAttribute('data-decktab'); renderDeckSection(); }));
  // 2026-10-18 (WP4): the handlers for #deckToCodexBtn and #deckHeroBtn went; neither button is drawn any more (the Hero trains in
  // the Stomping Grounds).
  const body = document.getElementById('deckSubBody');
  if(deckSubTab==='sim' && !adminEntryVisible()) deckSubTab = 'list'; // D4 (2026-10-03): the Simulator is an admin tool now
  if(deckSubTab==='sim'){ body.innerHTML = '<div id="view-sim"></div>'; renderSim(); return; }
  renderDeckListTab(body);
}
let deckListView = 'medium'; // 2026-10-13 (user: "By default, deck editor shows decks in 'Medium'. Remove the 'Large vs Medium' option")
function renderDeckListTab(body){
  body.innerHTML = `<div class="panel"><div class="dl-head"><h2>🃏 My Decks</h2>
</div>
      <p class="panel-sub">Your ★ main deck is the one you play with. Decks can hold any number of cards while you build; only a ${DECK_SIZE}-card deck can be played.</p>
      <div class="deck-menu-grid ${deckListView==='medium'?'is-medium':''}" id="deckMenuGrid"></div>
      <div class="deck-menu-bottom-actions">
        <button class="btn primary ${deckSlotFree() ? '' : 'is-slot-full'}" id="newDeckBtn" ${deckSlotFree() ? '' : 'aria-disabled="true"'}>${deckSlotFree() ? '➕' : '🔒'} New Deck</button>
        <button class="btn" id="importDeckCodeBtn">📥 Import Deck Code</button>
      </div>
      ${deckSlotPanelHTML('camp') /* 2026-10-23 (package UI4): deck slots */}
    </div>`;
  wireDeckSlots(body, ()=> renderDeckSection());
  const grid = document.getElementById('deckMenuGrid');
  // 2026-10-18 (audit R3-WP6): the Large/Medium buttons went on 2026-10-13; their handler (and its never-read bramblewood_deck_view key) went too.
  if(deckListView==='medium'){
    // 2026-10-23 (package UI4, owner 01:03 #5: "In the camp, it's not so obvious which is your main deck."): the main deck comes first, with
    // its ribbon and gold frame (deckMediumPreviewHTML); the others sit a little quieter
    grid.innerHTML = myDecks.slice().sort((a, b)=> (b.id === mainDeckId) - (a.id === mainDeckId)).map(d=> `<button type="button" class="dmp-btn ${d.id === mainDeckId ? 'is-main' : 'is-other'}" data-editdeck="${d.id}" aria-label="${escapeAttr((d.id === mainDeckId ? TX('ui.ui4-main-deck') + ': ' : '') + 'Edit ' + d.name)}">${deckMediumPreviewHTML(d)}</button>`).join('')
      + neEmptySlotsHTML(); // 2026-10-24 (package NE, owner 17:01 #13)
    grid.querySelectorAll('[data-ne-slot]').forEach(b=> b.addEventListener('click', e=>{ if(deckSlotDenied(e.currentTarget)) return; deckHeroView = false; const d = createNewDeck(); deckEditingId = d.id; deckShowList = false; renderDeckSection(); }));
    grid.querySelectorAll('[data-editdeck]').forEach(b=> b.addEventListener('click', ()=>{ deckHeroView = false; deckEditingId = b.getAttribute('data-editdeck'); deckShowList = false; renderDeckSection(); }));
    document.getElementById('newDeckBtn').addEventListener('click', e=>{ if(deckSlotDenied(e.currentTarget)) return; /* 2026-10-23 (package UI4) */ deckHeroView = false; const d = createNewDeck(); deckEditingId = d.id; deckShowList = false; renderDeckSection(); });
    document.getElementById('importDeckCodeBtn').addEventListener('click', ()=> importDeckCodeFlow(document.getElementById('importDeckCodeBtn')));
    return;
  }
  grid.innerHTML = myDecks.map(d=> `
    <div class="deck-menu-card deck-large-preview ${d.id===mainDeckId?'active':''} ${deckIsLegal(d)?'':'is-illegal'}" data-deckid="${d.id}">
      <div class="deck-menu-card-head">
        <input class="deck-menu-name-input" aria-label="Deck name" data-deckid="${d.id}" value="${escapeAttr(d.name)}" maxlength="40">
        ${d.id===mainDeckId?'<span class="deck-active-badge">★ MAIN</span>':''}
        ${deckIsLegal(d)?'':`<span class="deck-illegal-badge" title="Needs exactly ${DECK_SIZE} cards to play">${deckTotal(d.counts||{})}/${DECK_SIZE}</span>`}
      </div>
      ${deckShowcaseHTML(d)}
      ${deckCardsStripHTML(d)}
      <div class="deck-menu-card-actions">
        <button class="btn small primary" data-editdeck="${d.id}">✏️ Edit</button>
        ${d.id!==mainDeckId?`<button class="btn small" data-selectdeck="${d.id}" title="Play with this deck">★ Make main</button>`:''}
        <button class="btn small" data-exportdeck="${d.id}" title="Copy a shareable code for this deck">📋 Code</button>
        <button class="btn small ghost dm-delete" data-deletedeck="${d.id}" ${myDecks.length>1 ? '' : 'disabled aria-disabled="true"'} title="${myDecks.length>1 ? 'Delete this deck' : 'You need at least one deck'}">🗑 Delete</button>
      </div>
    </div>`).join('');
  grid.querySelectorAll('[data-editdeck]').forEach(b=> b.addEventListener('click', ()=>{ deckHeroView = false; deckEditingId = b.getAttribute('data-editdeck'); deckShowList = false; renderDeckSection(); }));
  grid.querySelectorAll('[data-selectdeck]').forEach(b=> b.addEventListener('click', ()=>{ const id = b.getAttribute('data-selectdeck'); setMainDeck(id); switchActiveDeck(id); renderDeckSection(); }));
  grid.querySelectorAll('[data-deletedeck]').forEach(b=> b.addEventListener('click', ()=>{
    if(confirm(TX('dialog.delete-this-deck-this-cannot-be'))){ deleteDeck(b.getAttribute('data-deletedeck')); renderDeckSection(); }
  }));
  grid.querySelectorAll('[data-exportdeck]').forEach(b=> b.addEventListener('click', ()=>{
    const d = myDecks.find(x=>x.id===b.getAttribute('data-exportdeck'));
    if(d) exportDeckCode(d, b);
  }));
  grid.querySelectorAll('.deck-menu-name-input').forEach(inp=>{
    inp.addEventListener('click', e=> e.stopPropagation());
    inp.addEventListener('change', ()=>{ renameDeck(inp.getAttribute('data-deckid'), inp.value); renderDeckSection(); });
  });
  document.getElementById('newDeckBtn').addEventListener('click', e=>{ if(deckSlotDenied(e.currentTarget)) return; /* 2026-10-23 (package UI4) */ deckHeroView = false; const d = createNewDeck(); deckEditingId = d.id; deckShowList = false; renderDeckSection(); });
  document.getElementById('importDeckCodeBtn').addEventListener('click', ()=> importDeckCodeFlow(document.getElementById('importDeckCodeBtn')));
}
// Copies `d`'s code to the clipboard (async Clipboard API, needs a real user gesture — this is
// always called from one, a button click). Falls back to a pre-filled prompt() (select-all +
// Ctrl/Cmd+C still works from there) when the Clipboard API is unavailable or the browser denies
// it — a locked-down/insecure context, an iframe without the permission, etc. — so the feature
// never just silently fails with no way to actually get the code out.
// In-game text dialog (2026-10-08, user: "the import deck code should be native UI, not Chrome
// UI"): a parchment modal in the game's own style instead of window.prompt. Resolves to the text,
// or null when cancelled. readonly mode shows a code to copy, with a Copy button.
function bwChoice({title, body, choices}){
  return new Promise(resolve=>{
    const ov = document.createElement('div'); ov.className = 'modal-overlay bw-text-dialog';
    ov.innerHTML = `<div class="modal" role="alertdialog" aria-modal="true" aria-label="${escapeAttr(title)}">
      <div class="modal-head-row"><h2>${escapeHtml(title)}</h2></div>
      <p class="panel-sub">${escapeHtml(body||'')}</p>
      <div class="modal-actions">${choices.map(c=> `<button type="button" class="btn ${c.primary?'primary':c.ghost?'ghost':''}" data-k="${escapeAttr(c.key)}">${escapeHtml(c.label)}</button>`).join('')}</div></div>`;
    document.body.appendChild(ov);
    const done = k=>{ ov.remove(); resolve(k); };
    ov.querySelectorAll('[data-k]').forEach(b=> b.onclick = ()=> done(b.dataset.k));
    ov.onkeydown = e=>{ if(e.key==='Escape'){ e.stopPropagation(); done('stay'); } };
    setTimeout(()=> (ov.querySelector('.btn.primary') || ov.querySelector('button')).focus(), 30);
  });
}
function bwConfirm({title, body, list, okLabel, focusCancel, centre}){
  return new Promise(resolve=>{
    // centre (2026-10-14, user: "The forfeit menu should be in the centre methinks, and everywhere else darkened (fade transition)"):
    // the dialog sits in the middle of the screen over a dimmed backdrop that fades in, and fades out again when it closes.
    const ov = document.createElement('div'); ov.className = 'modal-overlay bw-text-dialog' + (centre ? ' bw-centre-dialog' : '');
    ov.innerHTML = `<div class="modal" role="alertdialog" aria-modal="true" aria-label="${escapeAttr(title)}">
      <div class="modal-head-row"><h2>${escapeHtml(title)}</h2><button type="button" class="modal-close-btn" data-x aria-label="Close">✕</button></div>
      <p class="panel-sub">${escapeHtml(body||'')}</p>
      ${list && list.length ? `<ul class="bwc-list">${list.map(x=> `<li>${escapeHtml(x)}</li>`).join('')}</ul>` : ''}
      <div class="modal-actions"><button type="button" class="btn ghost" data-x>Cancel</button><button type="button" class="btn primary" data-ok>${escapeHtml(okLabel||'OK')}</button></div></div>`;
    document.body.appendChild(ov);
    let closed = false;
    const done = v=>{ if(closed) return; closed = true; resolve(v);
      if(centre && !reducedMotion()){ ov.classList.add('is-out'); setTimeout(()=> ov.remove(), 260); } else ov.remove(); };
    ov.querySelectorAll('[data-x]').forEach(b=> b.onclick = ()=> done(false));
    ov.onclick = e=>{ if(e.target === ov) done(false); };
    ov.onkeydown = e=>{ if(e.key==='Escape'){ e.stopPropagation(); done(false); } };
    ov.querySelector('[data-ok]').onclick = ()=> done(true);
    setTimeout(()=> ov.querySelector(focusCancel ? '.modal-actions [data-x]' : '[data-ok]').focus(), 30);
  });
}
function bwTextDialog({title, body, value, placeholder, okLabel, readonly}){
  return new Promise(resolve=>{
    const ov = document.createElement('div'); ov.className = 'modal-overlay bw-text-dialog';
    ov.innerHTML = `<div class="modal" role="dialog" aria-modal="true" aria-label="${escapeAttr(title)}">
      <div class="modal-head-row"><h2>${escapeHtml(title)}</h2><button type="button" class="modal-close-btn" data-x aria-label="Close">✕</button></div>
      ${body ? `<p class="panel-sub">${escapeHtml(body)}</p>` : ''}
      <textarea rows="3" spellcheck="false" ${readonly ? 'readonly' : ''} placeholder="${escapeAttr(placeholder||'')}">${escapeHtml(value||'')}</textarea>
      <p class="btd-msg" aria-live="polite"></p>
      <div class="modal-actions"><button type="button" class="btn ghost" data-x>${readonly ? 'Close' : 'Cancel'}</button>
        <button type="button" class="btn primary" data-ok>${escapeHtml(okLabel || (readonly ? '📋 Copy' : 'OK'))}</button></div></div>`;
    document.body.appendChild(ov);
    const ta = ov.querySelector('textarea'), msg = ov.querySelector('.btd-msg');
    const done = v=>{ ov.remove(); resolve(v); };
    ov.querySelectorAll('[data-x]').forEach(b=> b.onclick = ()=> done(null));
    ov.onclick = e=>{ if(e.target === ov) done(null); };
    ov.onkeydown = e=>{ if(e.key==='Escape'){ e.stopPropagation(); done(null); } else if(e.key==='Enter' && !e.shiftKey && !readonly){ e.preventDefault(); ov.querySelector('[data-ok]').click(); } };
    ov.querySelector('[data-ok]').onclick = ()=>{
      if(readonly){ ta.select(); let ok = false; try{ ok = document.execCommand('copy'); }catch(e){} msg.textContent = ok ? '📋 Copied!' : 'Selected: press Ctrl/⌘ + C to copy.'; if(ok) setTimeout(()=> done(ta.value), 600); return; }
      done(ta.value);
    };
    setTimeout(()=>{ ta.focus(); if(readonly) ta.select(); }, 30);
  });
}
function exportDeckCode(d, btnEl){
  const code = encodeDeckCode(d);
  const onCopied = ()=>{ SoundKit.codeCopy(); if(btnEl) floatText(btnEl, '📋 Copied!', 'heal'); };
  const fallback = ()=> bwTextDialog({title:'Deck code', body:'Copy this code and share it. Anyone can import it as a new deck.', value:code, readonly:true});
  if(navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(code).then(onCopied, fallback);
  else fallback();
}
// Prompts for a pasted code, decodes it, and — on success — creates a brand-new deck from it
// (never overwrites an existing one) so importing a friend's build can never clobber your own
// work by mistake. Any dropped/defaulted fields (an unknown card, a missing Castle) are reported
// back via a plain-language summary rather than silently importing something subtly different
// from what the code actually said.
async function importDeckCodeFlow(btnEl){
  if(deckSlotDenied(btnEl)) return; // 2026-10-23 (package UI4): an imported deck takes a deck slot too
  const raw = await bwTextDialog({title:'Import a deck', body:'Paste a Bramblewood deck code. It becomes a new deck; none of yours are changed.', placeholder:'Paste the code here', okLabel:'⬇ Import'});
  if(raw==null || !raw.trim()) return; // cancelled or empty — not an error, just a no-op
  const result = decodeDeckCode(raw);
  if(!result.ok){
    SoundKit.deny(); if(btnEl){ denyShake(btnEl); floatText(btnEl, '⚠ '+result.reason, 'debuff'); }
    return;
  }
  // 2026-10-23 (package PG): an imported deck is cut to the copy limits (rarity, copies you own); the cards cut are named
  const fit = clampDeckToLimits(result.deck.counts, result.deck.leaderId);
  if(fit.cut.length){ const defs = getCardDefs(); setTimeout(()=> showToast(TX('toast.pg-import-cut', {n: fit.cut.reduce((s, c)=> s + c.from - c.to, 0), list: fit.cut.slice(0, 4).map(c=> `${(defs[c.id]||{}).name || c.id} ${c.from}→${c.to}`).join(', ')}), 'warn'), 600); }
  const nd = { id: genDeckId(), name: result.deck.name, characterId: result.deck.characterId, leaderId: result.deck.leaderId, counts: fit.counts };
  // Avoid a confusing pair of decks with identical names sitting side by side in the list.
  if(myDecks.some(x=>x.name===nd.name)) nd.name = nd.name + ' (imported)';
  myDecks.push(nd); saveMyDecks();
  switchActiveDeck(nd.id);
  SoundKit.codeImport();
  if(btnEl) floatText(btnEl, result.warnings.length ? '✅ Imported (see notes)' : '✅ Imported!', 'heal');
  if(result.warnings.length) console.warn('Deck import warnings:', result.warnings);
  deckEditingId = nd.id;
  renderDeckSection();
}

