      if(kind === 'sparkle') f.innerHTML = Array.from({length:12}, (_, k)=> `<i style="left:${(9 + (k*41)%84)}%; top:${(7 + (k*59)%86)}%; --dl:${((k*0.31)%1.9).toFixed(2)}s; --h:${(k*67)%360}"></i>`).join('');
