    el.style.setProperty('--hy', (py*100).toFixed(1)+'%');
    el.style.setProperty('--hbx', (50 + (px-0.5)*60).toFixed(1)+'%');
    el.style.setProperty('--hby', (50 + (py-0.5)*60).toFixed(1)+'%');
    el.style.setProperty('--hrx', ((0.5-py)*14).toFixed(2)+'deg');
