const PACK_BUNDLES = [10, 25, 50, 100];
function pullClass(r, d){ return [r.shiny ? 'is-shiny' : '', r.foil ? copyFinishClass(d, {foil:true, finish:r.finish}) : ''].filter(Boolean).join(' '); }
// Set discounts (2026-10-08, user: "10 = 5% discount. 25 get 12.5%. 50 get 15% and so on").
